COLLDATA("asabahur","ur",[[7980,"§۸۰۰۰ ۔ مسیب بن ابی السائب(1)\nنسب: مسیب بن ابی السائب بن عبد اللہ بن عابد بن عمران بن مخزوم۔ لقب: قرشی، مخزومی۔ سائب ان کے بھائی کا نام ہے۔ زبیر بن بکار ان کے تذکرہ میں ابو عمر سے نقل کرتے ہیں کہ یہ مسلمان ہو گئے تھے اور نبی صلی اللہ علیہ وسلم کے ساتھ ہجرت کی حدیبیہ کے مقام سے۔ اور ان کا ایک بیٹا عبد اللہ تھا جو محاصرہ عثمان رضی اللہ عنہ میں شہید ہو گیا تھا۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۲۲) استیعاب (ت: ۲۴۳۷) تجرید (۷۷/۲)"}],[7981,"§۸۰۰۱ ۔ مسیب بن عمرو(2)\nابو موسیٰ نے ذیل میں ان کا تذکرہ کیا ہے اور مقاتل بن سلیمان سے نقل کیا ہے کہ ان کا تذکرہ سورہ والعادیات کی تفسیر میں ملتا ہے کہ نبی صلی اللہ علیہ وسلم نے بنو کنانہ کے ایک قبیلہ کے خلاف فوجی دستہ روانہ کیا اور مسیب بن عمرو اس کا کمانڈر مقرر فرمایا۔ کچھ عرصے تک اس قافلہ کی کوئی خبر نہ آئی چنانچہ منافقوں نے یہ افواہ اڑا دی کہ وہ سب مارے گئے اس پر سورہ عادیات نازل ہوئی: ﴿وَالْعَادِيَاتِ ضَبْحًا﴾۔(1)","",{"fn":"(1) سورۃ العادیات الآیۃ (۱)\n(2) اسد الغابہ (ت: ۴۹۲۳) تجرید (۷۷/۲)"}],[7982,"§۸۰۰۲ ۔ مشرح اشعری(4)\nبقول بغوی: امام بخاری رحمہ اللہ(1) نے صحابہ میں ان کا تذکرہ کیا ہے اور ابن ابی عاصم اور ابن سکن(2) وغیرہ نے سلمہ بن وہرام کے طریق سے تخریج کیا کہ میس اشعریہ جو کہ مشرح کی بیٹی ہیں انہوں نے اپنے والد مشرح کے بارے میں مجھے بتایا کہ میرے والد صحابی تھے اور انہوں نے ناخن کاٹ کر جمع کر کے ان کو دفن کر دیا اور فرمایا کہ میں نے نبی صلی اللہ علیہ وسلم کو ایسے کرتے ہوئے دیکھا ہے۔(3) اس کی سند میں محمد بن سلیمان بن مسمول راوی انتہائی ضعیف ہیں۔\nامام بیہقی رحمہ اللہ نے بھی اسی سند کے ساتھ الباب الاربعین من شعب الایمان کے آخر میں اس کی تخریج کی ہے اور فرمایا کہ ابن السکن نے اس کے علاوہ ان سے کوئی روایت نہیں لی۔","",{"fn":"(1) تاریخ کبیر (۴۵/۸)\n(2) احاد والمثانی (۴۵۹/۴)\n(3) معجم الکبیر (الحدیث: ۷۶۲/۲۰) مسند بزار (الحدیث: ۲۸۵) مجمع الزوائد (الحدیث: ۱۶۸/۵) جامع المسانید (۳۲۱/۱۱)\n(4) اسد الغابہ (ت: ۴۹۲۴) استیعاب (ت: ۲۵۸۱) تجرید (۷۸/۲)"}],[7983,"§۸۰۰۳ ۔ مشموج(2)\nخالد سعدی کے بیٹے ہیں اور مشہور محمد بن علی بن حجر کے دادا ہیں۔\nبقول ابن حبان: ان کو نبی صلی اللہ علیہ وسلم کی صحبت کا شرف ملا ہے۔ اور ابن السکن نے حسین بن اسماعیل فارسی سے انہوں نے حاتم بن عبد اللہ بن عبدہ سے اور وہ علی بن حجر بن ایاس بن مقاتل بن مشرح اپنے والد سے اور وہ اپنے والد ایاس سے اور وہ اپنے دادا مشرح سے روایت کرتے ہیں کہ میں وفد عبد القیس کے ساتھ حضور صلی اللہ علیہ وسلم کی خدمت میں آیا۔ حضور اکرم صلی اللہ علیہ وسلم نے پوچھا کہ کیا تم میں کوئی غیر بھی ہے؟ تو انہوں نے جواب دیا کہ ہماری بہن کا لڑکا ہمارا غیر ہے تو ارشاد فرمایا نہیں بلکہ وہ تمہاری قوم ہی کا ایک فرد ہے۔(1) پھر آپ نے اسے ایک چادر پہنائی اور صحراء میں ایک قطعہ زمین بھی عطا فرمایا اور اس پر ان کو فرمان لکھ کر جاری فرمایا۔","",{"fn":"(1) ابو داؤد کتاب الادب باب فی العصبیۃ (الحدیث: ۵۱۲۲) معجم الکبیر (الحدیث: ۱۴۲/۲) جامع المسانید (۳۲۲/۱)\n(2) اسد الغابہ (ت: ۴۹۲۵) تجرید (۷۸/۲)"}],[7984,"§۸۰۰۴ ۔ مصعب بن شیبہ\nمصعب بن شیبہ بن عثمان حجمی۔ مسلم بن شیبہ کے حالات میں ان کا تذکرہ ہو چکا ہے۔"],[7985,"§۸۰۰۵ ۔ مصعب بن عمیر(1)\nنسب: مصعب بن عمیر بن ہاشم بن عبد مناف بن عبددار بن قصی بن کلاب عبدری۔ کنیت: ابو عبد اللہ۔\nیہ بھی شروع میں اسلام لانے والوں میں سے یعنی سابقون اولون میں تھے۔ ابوعمر(2) فرماتے ہیں کہ یہ بہت پہلے اسلام لے آئے تھے جبکہ نبی علیہ السلام دارارقم میں تشریف رکھتے تھے۔ لیکن انہوں نے اپنی والدہ اور اپنی قوم کے ڈر سے اپنے اسلام کو چھپائے رکھا۔ لیکن عثمان بن طلحہ کو معلوم ہو گیا، اس نے ان کے گھر والوں کو بتا دیا۔ انہوں نے ان کو باندھ کر قید کر دیا تا آنکہ وہ ہجرت کر کے حبشہ تشریف لے گئے۔ پھر مکہ واپس آکر مدینہ کی طرف ہجرت کر گئے۔\nجنگ بدر و احد میں شریک رہے، بلکہ جنگ اُحد میں تو لشکر کا جھنڈا بھی ان کے پاس تھا اور اسی غزوہ میں یہ شہید ہو گئے۔(3) محمد بن اسحاق نے صالح بن کیسان سے اور وہ آلِ سعد کے کسی آدمی سے اور وہ سعد بن ابی وقاص رضی اللہ عنہ سے روایت کرتے ہیں کہ مصعب بن عمیر مکے کے خوش پوش اور ناز و نعمت میں پلے ہوئے نوجوان تھے اور ہمیشہ اپنے والدین کے ساتھ رہتے تھے۔(4) امام ترمذی(5) نے ضعیف سند سے روایت کیا ہے کہ سیدنا علی رضی اللہ عنہ نے فرمایا کہ نبی علیہ السلام سیدنا مصعب کو دیکھ کر رو پڑے کہ یہ کس ناز و نعمت میں پلا ہے اور اب اس کا کیا حشر ہے۔\nصحیح ابن حبان میں ہے کہ سیدنا مصعب نے اپنی وراثت میں صرف ایک کپڑا چھوڑا جس سے سر ڈھانپا جاتا تو پاؤں ننگے ہو جاتے اگر پاؤں کی طرف کپڑا کیا جاتا تو سر ننگا ہو جاتا۔ تو نبی علیہ السلام نے فرمایا کہ کپڑا سر کی طرف کر دو اور پاؤں پر اذخر نامی گھاس ڈال کر ڈھانپ دو۔(6)\nابن اسحاق مغازی میں فرماتے ہیں(7)(8) کہ یزید بن حبیب سے مروی ہے کہ لوگ جب عقبہ اولی سے واپس آئے تو نبی علیہ السلام نے مصعب بن عمیر کو ان کے ساتھ دین کی تعلیم کے لیے بھیج دیا اور انہوں نے پہلی ہجرت حبشہ کی طرف کی پھر مکہ آکر دوبارہ مدینہ کی طرف ہجرت فرمائی اور صحیح بخاری(9) میں براء رضی اللہ عنہ سے مروی ہے کہ مصعب بن عمیر اور ابن ام مکتوم سب سے پہلے ہجرت کر کے ہم سے مل گئے۔ ابوداؤد نے یہ بھی اضافہ فرمایا کہ پہلی ہجرت میں ہم سے آ کر مل گئے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۲۹) استیعاب (ت: ۲۵۸۲) تجرید (۷۸/۲)\n(2) استیعاب (۸۶/۴)\n(3) اسد الغابہ (۱۳۴/۴) سیرۃ النبویۃ (۲۴۲/۲)\n(4) طبقات کبریٰ (۸۲/۳) مغازی (ص ۱۹۳)\n(5) ترمذی کتاب صفۃ القیامہ باب حدیث علی (الحدیث: ۲۴۷۶)\n(6) ترمذی کتاب المناقب، باب مناقب مصعب (الحدیث: ۳۸۵۳) مصنف بن ابی شیبہ (الحدیث: ۲۶۰/۳)\n(7) دلائل النبوۃ (الحدیث: ۷/۴)\n(8) سیرۃ النبوۃ (۵۹/۲)\n(9) بخاری کتاب مناقب الانصار باب مقدم النبی (الحدیث: ۳۹۲۴، ۳۹۲۵)"}],[7986,"§۸۰۰۶ ۔ مصعب ابن امرأۃ الجلاس\nعمیر بن سعد کے حالات میں ان کا تذکرہ ہو چکا ہے۔"],[7987,"§۸۰۰۷ ۔ مصعب الاسلمی(1)\nامام بغوی و طبرانی(2) ان کا تذکرہ کرتے ہوئے جریر بن حازم کے طریق سے تخریج کرتے ہیں کہ عبدالملک بن عمیر مصعب الاسلمی سے روایت کرتے ہیں کہ انہوں نے فرمایا کہ ہماری قوم کا ایک لڑکا حضور علیہ السلام کی خدمت میں حاضر ہو کر عرض کرتا ہے کہ اے اللہ کے رسول صلی اللہ علیہ وسلم! آپ مجھے ان لوگوں میں شامل فرما دیجئے جن کی آپ قیامت کے دن شفاعت فرمائیں گے۔ تو آپ علیہ السلام نے فرمایا: تم اس معاملہ میں کثرت سجود کے ساتھ میری مدد کرو(3) تو میں تمہاری شفاعت کر سکتا ہوں۔\nبزار نے طالوت بن عباد سے نقل کیا اور وہ جریر سے روایت کرتے ہیں کہ عبدالملک سے مروی ہے مدینہ میں ایک غلام تھا جس کی کنیت ابومصعب تھی۔ پھر لمبی حدیث بیان فرمائی اور فرمایا کہ یہ حدیث صرف اسی سند سے مروی ہے اور امام عسکری فرماتے ہیں یہ مرسل ہے۔\nمیں کہتا ہوں: بزار کی روایت میں بظاہر ارسال ہے لیکن اس میں ابومصعب کا ذکر ہے اور ان کے علاوہ باقی روایتوں میں وصل ظاہر ہے، لیکن عبدالملک راوی مدلس ہے یعنی اپنے استادوں کو چھپا لیتا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۲۶) تجرید (۷۸/۲)\n(2) معجم الکبیر (الحدیث: ۳۶۵/۲۰)\n(3) مصنف ابن ابی شیبہ (الحدیث: ۴۷۵/۲) معجم الکبیر (۸۵۱/۲۰) مجمع الزوائد (الحدیث: ۳۶۹/۱۰) جامع المسانید (۳۲۴/۱۱)"}],[7988,"§۸۰۰۸ ۔ مضارب بن زید العجلی(1)\nانہوں نے بھی دور نبوت پایا اور سیف نے ان کا تذکرہ کیا ہے اور یہ مثنیٰ بن حارثہ کے کمانڈروں میں سے ہیں۔ اور جب اہل عراق سے جنگ کرنے کے لیے چلے تو ان کے امراء مقدمۃ الجیش میں تھے۔ اور یہ ۱۳ھ کی بات ہے۔ پھر یہ اس کے بعد جنگ قادسیہ میں شریک ہوئے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۲۰) تجرید (۷۸/۲)"}],[7989,"§۸۰۰۹ ۔ مُضَرِّح\nان کا ذکر مُطَرِّح میں گزر چکا ہے۔"],[7990,"§۸۰۱۰ ۔ مضرّس بن سفیان(1)\nنسب: مضرّس بن سفیان بن خفاجہ بن نابغہ بن عتر بن حبیب بن وائلہ بن دہمان بن نضر بن معاویہ بن بکر بن ہوازن۔ لقب: نصری۔ بقول ابن کلبی: یہ نبی علیہ السلام کے ساتھ غزوہ حنین میں شریک ہوئے تھے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۳۳) تجرید اسماء الصحابہ (۷۸/۲)"}],[7991,"§۸۰۱۱ ۔ مضرس بن عمرو ثعلبی\nابو عمر شیبانی غنی کے انساب میں ان کا تذکرہ کرتے ہوئے لکھتے ہیں کہ ان کو نبی علیہ السلام کی صحبت کا شرف ملا ہے۔"],[7992,"§۸۰۱۲ ۔ مضطجع بن اثاثہ(1)\nمضطجع بن اثاثہ بن عباد بن عبدالمطلب، لقب: قرشی، مطلبی یہ مسطح کے بھائی ہیں۔ موسیٰ بن عقبہ نے شرکاء بدر میں ان کا تذکرہ کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۳۲) تجرید (۷۸/۲)"}],[7993,"§۸۰۱۳ ۔ مضطجع\nیہ ایک دوسرے شخص ہیں جن کا ذکر منبعث کے تحت آئے گا۔"],[7994,"§۸۰۱۴ ۔ مطاع اللخمی\nمسعود بن ضحاک کے حالات میں گزر چکا ہے۔"],[7995,"§۸۰۱۵ ۔ مُطرح بن جندلہ(1)\nان کو جدالہ سلمی بھی کہا جاتا ہے۔ ابو موسیٰ نے ذیل میں روایت کی ہے زیدتی کے طریق سے کہ محمد بن سیرین ابن عباس رضی اللہ عنہما سے روایت کرتے ہیں کہ بنو سلیم کا ایک دیہاتی مطرح بن جندلہ نبی علیہ السلام سے پوچھنے لگا، اے اللہ کے رسول! آپ کی اُمت کو نوح علیہ السلام کی اُمت پر کتنی فضیلت حاصل ہے؟ تو نبی علیہ السلام نے ارشاد فرمایا: جتنی فضیلت اللہ تعالیٰ کو تمام مخلوقات پر ہے۔۔ الخ۔(2) ابن نقاش نے موضوعات میں اس کی تخریج کرتے ہوئے لکھا ہے کہ نبی علیہ السلام نے ان کا نام مطرح ابن الاسلام رکھا تھا۔ اور اسمٰعیل بن ابی زیاد سامی نے لیث بن ابی سلیم کی تفسیر میں ضحاک سے روایت نقل کی ہے انہوں نے ابن عباس رضی اللہ عنہما سے اسی طرح کی روایت نقل کی ہے لیکن اس میں ان کو مطرح بن جدالہ کہا گیا ہے، ابن مندہ نے بھی ان کا تذکرہ کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۳۸) تجرید (۷۹/۲)\n(2) جامع المسانید (۳۲۵/۱۱) اسد الغابہ (ت: ۴۹۴۰) تجرید (۷۹/۲)"}],[7996,"§۸۰۱۶ ۔ مطرف بن بُہصل\nنسب: مطرف بن بہصل بن کعب بن قشع بن دلف بن بہیم بن عبداللہ بن جماز بن مالک بن زمان بن عمرو بن تمیم اتمی مازنی۔ اعشی کے حالات میں ان کا تذکرہ گزر چکا ہے، اور مزید نصلہ بن بہصل کے تحت آئے گا۔ ان شاء اللہ"],[7997,"§۸۰۱۷ ۔ مطرف بن خالد(1)\nمطرف بن خالد بن نضلہ الباہلی۔ ابو احمد عسکری نے صحابہ میں ان کا تذکرہ کیا ہے اور فرمایا کہ یہ مسلمان ہو گئے تھے اور نبی علیہ السلام نے ان کو ایک فرمان لکھ دیا تھا۔\nاور بقول رشاطی مطرف الکاہلی فتح مکہ کے بعد نبی علیہ السلام کی خدمت میں حاضر ہوئے تھے آپ نے ان کو فرمان لکھ دیا تھا جس میں زکوۃ صدقات کے فرائض کی تفصیل تھی۔\nابن شاہین فرماتے ہیں: مطرف بن کاہن الباہلی جو بنوفریص میں سے ہیں پھر حدیث بیان کرتے ہوئے لکھتے ہیں کہ عمرو بن مالک نے منذر سے روایت کیا ہے کہ حسین بن محمد بن علی نے علی بن محمد مدائنی سے انہوں نے ابو معشر سے انہوں نے یزید بن رومان سے کہ محمد بن اسحاق اپنے شیوخ سے روایت کرتے ہیں کہ انہوں نے فرمایا کہ مطرف بن کاہن الباہلی بنوفریص قبیلہ سے تعلق رکھتا ہے یہ فتح مکہ کے بعد نبی علیہ السلام کے پاس حاضر ہو کر عرض کرنے لگے کہ ہم اسلام پر راضی ہیں اور ہم نے اللہ کے دین کا معائنہ کر لیا ہے آسمانوں میں اور یہ بھی ہم نے دیکھ لیا کہ اللہ کے سوا کوئی معبود نہیں اور ہم نے آپ کی ہر اس بات میں تصدیق کی جو آپ کی زبان مبارک سے نکلی۔ لہذا آپ ہمارے لیے فرمان لکھ دیں تو نبی علیہ السلام نے یہ لکھا۔\nمحمد رسول اللہ صلی اللہ علیہ وسلم کی طرف سے مطرف بن کاہن کے لیے اور باطلہ قبیلہ سے تعلق رکھنے والے ہر اس آدمی کے لیے جو ان کے گھر میں رہائش پذیر ہو کہ جو بھی کسی بنجر زمین کو آباد کرے جس میں جانوروں کے لیے چراگاہیں ہوں تو وہ زمین اسی شخص کی ملکیت ہوگی اور اس پر ہر تیس گائیوں میں ایک بوڑھی گائے ہوگی اور ہر چالیس بکریوں میں یک سالہ بکری ہوگی اور ہر پچاس اونٹوں میں ایک یک سالہ اونٹنی ہوگی۔۔۔ الخ۔(2) اور آخر میں یہ بھی ہے کہ مطرف واپس جاتے ہوئے یہ شعر پڑھ رہے تھے۔ شام کے وقت رقص کرتی اونٹنیوں کے رب کی قسم آٹھویں سال اور جوان اونٹ کے ہر جانب۔ چند اشعار میں نبی علیہ السلام کی تعریف کی۔ اس سے بخوبی یہ بات معلوم ہوئی کہ ان کا تعلق باہلہ سے تھا۔\nابو عبید البکری اپنی معجم میں فرماتے ہیں کہ یعقوب نے کہا کہ بیشہ ایک وادی ہے تھامہ کے پہاڑوں کی طرف سے اور بعض نسخوں میں ہے کہ بنی ہلال کے پہاڑوں سے اور بعض نسخوں میں سلول کا ذکر ہے اس سے یقینی معلوم ہوتا ہے کہ یہ باہلی ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۴۰) تجرید (۷۹/۲)\n(2) شرح معانی الآثار (۱۱۸/۳)"}],[7998,"§۸۰۱۸ ۔ مطرف بن عبداللہ\nنسب: مطرف بن عبداللہ بن اعلم بن عمرو بن ربیعہ، لقب: عقیلی۔ ابن سعد اور رشاطی نے وفد بنی عقیل میں ان کا بھی تذکرہ فرمایا اور ابن سعد تو فرماتے ہیں کہ ہشام بن محمد بن سائب کلبی روایت کیا ہے کہ بنو عقیل کے ایک آدمی نے اپنی قوم کے مشائخ سے نقل کرتے ہوئے بتایا کہ ہم بنو عقیل کے کچھ آدمی نبی علیہ السلام کی خدمت میں حاضر ہوئے جن میں ربیع بن معاویہ بن خفاجہ بن عمرو بن عقیل اور مطرف بن عبداللہ بن اعلم بن عمرو بن نبیل اور انس بن مشفق بن عامر بن عقیل تھے۔ ان سب حضرات نے نبی علیہ السلام کے دست اقدس پر بیعت کر کے اسلام قبول کر لیا اور اپنی قوم کے دیگر لوگوں کے لیے جو کسی وجہ سے نہیں آسکے تھے ان کی طرف سے بیعت کرلی۔ نبی علیہ السلام نے ان کو عقیق نامی زمین لکھ کر ان کے نام کر دی جو بہت سرسبز و شاداب چشموں اور کھجوروں والی زمین تھی۔ اور اس حدیث میں یہ بھی ہے جب تک یہ لوگ نماز قائم کریں، زکوۃ ادا کریں، بات سنیں اور مانیں، اس جیسا حق معلوم نہیں۔ لوگوں کا کہنا ہے: وہ خط مطرف کے پاس تھا۔"],[7999,"§۸۰۱۹ ۔ مطرف بن کاہن\nمطرف بن خالد کے تحت ان کا ذکر ہو چکا ہے۔"],[8000,"§۸۰۲۰ ۔ مطر بن زرّاع\nان کو ابن فیل بھی کہا جاتا ہے، ان کا تذکرہ اگلے نمبر کے بعد آئے گا۔"],[8001,"§۸۰۲۱ ۔ مطر بن عکامس السلمی(1)\nان کو کوفیوں میں شمار کیا جاتا ہے اور بقول ابن حبان ان کو نبی علیہ السلام کی صحبت کا شرف حاصل ہوا ہے، لیکن امام طبرانی(2) کے ہاں ان کے صحابی ہونے میں اختلاف ہے۔ عثمان دارمی ابن ابی حاتم نے یحیی بن معین سے پوچھا کہ یہ نبی علیہ السلام سے ملے ہیں تو انہوں نے فرمایا: مجھے کچھ پتہ نہیں اور ان سے صرف ایک حدیث مروی ہے۔ اور عبداللہ بن احمد نے اپنے والد سے پوچھا کہ یہ صحابی ہیں؟ تو انہوں نے کہا کہ مشہور تو نہیں ہے۔ پھر پوچھا کہ ان کی کوئی روایت ہے؟ تو انہوں نے کہا: مجھے معلوم نہیں۔ اور بقول بردیجی ان سے صرف ابو اسحاق نے روایت لی ہے۔ اور ان کے صحابی ہونے کی بات صحیح نہیں ہے۔ اور بقول ابو احمد عسکری بعض ان کے صحبت کی قائل نہیں اور بعض نے ان کو صحابہ میں شامل کیا ہے۔\nنبی علیہ السلام سے مروی ہے کہ جب اللہ تعالیٰ کسی بندے کے بارے میں یہ فیصلہ فرما لیتے ہیں کہ فلاں جگہ پر اس کی روح قبض کی جائے گی تو اس بندے کے لیے اس جگہ کوئی ضرورت اور حاجت پیش کر دیتے ہیں۔(3) عبداللہ بن احمد نے زیادات مسند میں اس کی تخریج فرمائی ہے اور امام ترمذی(4) نے تخریج کرنے کے بعد فرمایا یہ حسن غریب ہے اور مطر کی اس کے علاوہ اور کوئی روایت مشہور نہیں ہے۔ امام حاکم رحمہ اللہ نے اس کی تصحیح فرمائی ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۳۵) استیعاب (ت: ۲۵۸۳) تجرید (۷۹/۲)\n(2) مستدرک حاکم (الحدیث: ۴۲/۱) معجم الکبیر (الحدیث: ۷۸۵/۲۰)\n(3) مسند احمد (الحدیث: ۲۲۷/۵) مجمع الزوائد (الحدیث: ۲۱/۶) جامع المسانید (۳۲۸/۱۱)\n(4) ترمذی کتاب القدر باب ما جاء فی ان النفس تموت حیث ما کتب لھا (الحدیث: ۲۱۴۶)"}],[8002,"§۸۰۲۲ ۔ مطر بن ہلال الغنوی(1)\nان کو مطر بن فیل بھی کہا جاتا ہے اور بقول ابن حبان یہ مطر بن زراع ہیں جن کو نبی علیہ السلام کی صحبت کا شرف حاصل ہوا۔ امام بغوی رحمہ اللہ نے یحیی بن حماد کے طریق سے مطر بن عبدالرحمن اعنق سے روایت کیا ہے کہ عبدالقیس کی ایک عورت نے مجھے بتایا (جن کو ام ابان بنت وازع بن زراع کہا جاتا تھا) کہ ان کے دادا زراع ان کے ساتھ عبد القیس سے نبی علیہ السلام کی خدمت میں جانے کے لیے اپنے بیمار بیٹے اور ماں شریک بھائی کو لے کر نکلے۔ عبد القیس میں سے مطر بن فیل عنزی نامی کوئی بندہ نہیں۔ تو انح نے اس سے کہا تو ہمارے ساتھ نکلا ہے، ایک لٹکا پاگل شخص(2) کو لے کر اور ایک دوسرا شخص جو ہم میں سے نہیں۔ تو اس نے کہا کہ اس پاگل شخص کے لیے نبی علیہ السلام دعا فرمائیں گے، امید ہے کہ اللہ اس کو شفا دے دیں اور باقی رہا عنزی تو وہ میرا ماں شریک بھائی ہے جس کے بغیر میں رہ نہیں سکتا۔\nابن مندہ نے موسیٰ بن اسماعیل کے طریق سے مطر سے تخریج کی ہے لیکن انہوں نے مطر بن ہلال فرمایا ہے۔ اور بزار نے ابوداؤد طیالسی کے طریق سے مطر سے بسندہ زراع تک تخریج کیا ہے کہ وہ سفر کے ارادہ سے نکلے اور ان کے ساتھ انح بھی تھے جو کہ اپنے پاگل بیٹے کو لے کر نکلے جس کا نام مطر تھا اور ایک اس کا بھائی بھی تھا۔ الخ۔(3) اور ان کا تذکرہ صحار بن عباس، اور جہم بن قثم کے حالات میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۳۷) استیعاب (ت: ۲۵۸۴) تجرید (۷۹/۲)\n(2) ابوداؤد کتاب الادب باب فی قبلۃ الرجل (الحدیث: ۵۲۲۵) معجم الکبیر (الحدیث: ۵۳۱۳/۵) (۵۳۱۴/۵) الآحاد والمثانی (الحدیث: ۳۰۴/۳) (الحدیث: ۳۰۶/۳) مجمع الزوائد (الحدیث: ۳۹۰/۹) تاریخ الکبیر (۴۴۷/۳)\n(3) ابوداؤد کتاب الادب باب فی قبلۃ الرجل (الحدیث: ۵۲۲۵)"}],[8003,"§۸۰۲۳ ۔ مطر اللیثی\nان کا تذکرہ مکیل کے حالات میں ہے۔"],[8004,"§۸۰۲۴ ۔ مطر العنزی\nیہ عبد القیس کے اتحادی ہیں اور عقبہ بن جمروہ کے بھائی ہیں۔ ان کا تذکرہ صحار بن عباس کے حالات میں ہو چکا اور بعض حضرات کا کہنا ہے کہ یہ وہی مطر بن فیل ہیں جن کا تذکرہ ابھی ابھی گزرا ہے۔"],[8005,"§۸۰۲۵ ۔ مطعم بن عبیدہ البلوی(1)\nابن یونس ان کے تذکرہ میں فرماتے ہیں کہ یہ صحابی ہیں اور ربیعہ بن لقیط نے ان سے روایت لی ہے۔ ابن مندہ نے ان کی حدیث کو ابن لہیعہ کے طریق سے اسحاق بن ربیعہ بن لقیط سے تخریج کیا ہے کہ ان کے والد ربیعہ نے فرمایا کہ میں عبد اللہ بن عمرو کے ساتھ ایک فتنے کے معاملہ میں نکلا تو ان کے دروازے پر مطعم بن عبیدہ بلوی سے ملا تو انہوں نے کہا کہ نبی علیہ السلام نے مجھ سے وعدہ لیا تھا کہ میں سنوں اور اطاعت و فرمانبرداری کروں امیر کی اگر چہ وہ کٹے ہوئے(2) اعضاء والا کالا سیاہ ہی کیوں نہ ہو۔ بقول ابن مندہ: یہ حدیث غریب ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۳۹۴۲) تجرید (۷۸/۲)\n(2) جامع المسانید (۳۲۹/۱۱)"}],[8006,"§۸۰۲۶ ۔ مطعم آخر\nان کا تذکرہ حارثہ کے حالات میں گزر چکا ہے۔"],[8007,"§۸۰۲۷ ۔ المطلب بن ازہر(1)(2)\nمطلب بن ازہر بن عبد عوف زہری۔ عبدالرحمن بن عوف بن عبد عوف کے چچا کے بیٹے ہیں۔ ابن اسحاق نے مہاجر بن حبشہ میں ان کا تذکرہ کیا ہے اور فرمایا کہ یہ وہیں فوت ہو گئے تھے اور ان کا وارث ان کا بیٹا عبد اللہ بنا جس کے بارے میں کہا گیا کہ یہ اسلام میں سب سے پہلا وارث ہے اور بقول واقدی انہوں نے حبشہ کی طرف ہجرت ثانیہ کی تھی تو ان کا بیٹا عبداللہ پیدا ہوا۔ اور بقول ابن الکلبی انہوں نے اور ان کے بیٹے عبداللہ نے حبشہ کی طرف ہجرت فرمائی اور یہ دونوں وہیں حبشہ میں فوت ہو گئے۔ اور مطلب کے ساتھ ان کی بیوی رملہ بنت ابی عوف بن صہیرو بن سعید بن سعد بن سہم سہمی بھی تھی۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۴۳) استیعاب (ت: ۲۴۴۰) تجرید (۷۹/۲)\n(2) سیرۃ النبویۃ (۶/۴)"}],[8008,"§۸۰۲۸ ۔ المطلب بن ابی البختری\nنسب: المطلب بن ابی البختری بن حارث بن اسد بن عبد العزی القرشی الاسدی۔ ان کا والد بدر کے روز کافر مارا گیا۔ اور یہ اس کے بعد زندہ رہے اور یہ اسود کے بھائی ہیں جن کا ذکر الف کی سختی میں گزر چکا ہے۔ زبیر بن بکار ان کا تذکرہ کرتے ہوئے فرماتے ہیں کہ یہ اپنے بھائی کی طرح بھاری جسامت والے تھے۔"],[8009,"§۸۰۲۹ ۔ المطلب بن حنطب(1)\nنسب: مطلب بن حنطب بن حارث بن عبید اللہ بن مخزوم، کنیت عبداللہ بن حنطب کے والد ہیں۔ ابن اسحاق نے بدر کے قیدیوں میں ان کا تذکرہ کیا ہے۔ پھر یہ مسلمان ہو گئے اور عبداللہ بن حنطب کے حالات میں ان کی حدیث گزر چکی ہے، جس کی سند میں اختلاف ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۴۴) استیعاب (ت: ۲۴۴۱) تجرید (۷۹/۲)"}],[8010,"§۸۰۳۰ ۔ المطلب بن ربیعہ(1)\nنسب: مطلب بن ربیعہ بن حارث بن عبد المطلب بن ہاشم۔ امام بغوی رحمہ اللہ نے عبداللہ بن حارث کے طریق سے مطلب بن ابی وداعہ سے تخریج کیا ہے۔ فرماتے ہیں کہ سیدنا عباس رضی اللہ عنہ نبی علیہ السلام کی خدمت اقدس میں حاضر ہوئے گویا کہ کچھ سنتے ہوئے آ رہے تھے۔ پھر پوری حدیث بیان کی جس میں یہ بھی تھا کہ اللہ تعالیٰ نے ساری مخلوق کو پیدا فرمایا اور سب سے بہترین قبیلہ میں مجھے پیدا فرمایا۔(2)\nمغازی ابن اسحاق(3) میں ہے کہ ابو وداعہ جنگ بدر میں قید ہو کر آیا تھا تو نبی علیہ السلام نے ارشاد فرمایا اس کا ایک عقلمند، مالدار، تاجر بیٹا ہے۔\nاور انہوں نے ام المومنین سیدہ حفصہ رضی اللہ عنہا سے بھی روایت لی ہے جو کہ صحیح مسلم میں زہری کی روایت سے موجود ہے کہ سائب بن یزید مطلب سے اور وہ سیدہ حفصہ رضی اللہ عنہا سے روایت کرتے ہیں بیٹھ کر(4) نفل نماز پڑھنے کے بارے میں پھر اس روایت کو ان کے بیٹوں جعفر، کثیر، اور عبد الرحمن اور ان کے پوتے ابوسفیان بن عبدالرحمن نے ان سے روایت کیا ہے۔\nامام بغوی اور ابن شاہین نے عکرمہ بن خالد کے طریق سے جعفر بن مطلب بن ابی وداعہ اپنے والد سے روایت کرتے ہیں کہ میں نے نبی علیہ السلام کو مکہ مکرمہ میں سورہ نجم کی تلاوت کرتے ہوئے سنا ہے یعنی آپ نے اس کی تلاوت کے دوران سجدہ فرمایا۔ عبدالمطلب کے حالات میں ان کا ذکر گزر چکا ہے۔ بقول بغوی: مطلب بن ربیعہ ہیں اور یہ بھی کہا گیا ہے کہ یہ عبدالمطلب بن ربیعہ ہیں۔ ابن شاہین نے صباح بن یحیی کے طریق سے یزید بن ابی زیاد سے ان کی ایک روایت تخریج کی ہے۔ عبداللہ بن حارث ان سے روایت کرتے ہیں کہ نبی علیہ السلام کا فرمان ہے: \"جس نے عباس کو تکلیف پہنچائی اس نے مجھے تکلیف دی\"۔(5)","",{"fn":"(1) اسد الغابہ (ت: ۴۹۴۵) استیعاب (ت: ۲۴۴۲) تجرید (۸۰/۲)\n(2) اتحاف السادۃ المتقین (الحدیث: ۸۹/۹) مناقب الشافعی للبیہقی (الحدیث: ۴۶/۱)\n(3) سیرۃ النبویۃ (۲۱۹/۲)\n(4) مسلم کتاب صلاۃ المسافر باب جواز النافلۃ قائما او قاعدا (الحدیث: ۱۷۰۹) ترمذی ابواب الصلوۃ باب ما جاء فی الرجل یتطوع جالسا (الحدیث: ۳۷۳) مسند احمد (الحدیث: ۲۸۶/۶)\n(5) معجم الکبیر (الحدیث: ۱۸۶/۲۰)"}],[8011,"§۸۰۳۱ ۔ المطلب بن ابی وداعہ(1)\nحارث بن حبیرہ بن سعید بن سعد بن سہم۔ نسبت: قرشی، سہمی۔ ابن سعد نے مسلمانان فتح مکہ میں ان کا تذکرہ کیا ہے۔ بقول واقدی: یہ مدینہ کے رہائشی تھے اور وہیں ان کی ایک حویلی تھی اور ایک زمانہ تک وہیں رہے۔ اور ابن الکلبی فرماتے ہیں یہ نبی علیہ السلام کے ہم عصر تھے اور بقول ابو عبیدہ ان کو بارگاہ نبوت کی صحبت کا شرف بھی حاصل تھا۔\nانہوں نے نبی علیہ السلام سے روایت بیان کی ہے جو کہ مسند احمد(2) میں عکرمہ بن خالد تک صحیح سند کے ساتھ موجود ہے۔ مطلب بن ابی وداعہ فرماتے ہیں کہ میں نے نبی علیہ السلام کو سورہ نجم کی تلاوت میں سجدہ کرتے ہوئے دیکھا ہے۔ پھر اس حدیث کے آخر میں فرماتے ہیں کہ میں نے بھی کبھی سورہ نجم میں سجدوں کو نہیں چھوڑا۔ یہ عبدالرزاق کی معمر سے روایت تھی، جبکہ رباح بن زید نے معمر سے روایت کرتے ہوئے عکرمہ بن خالد اور مطلب کے درمیان جعفر بن مطلب کو بھی داخل کیا ہے۔ اور یہ بھی کہا کہ میں اس وقت کافر تھا اس لیے میں نے سجدہ نہیں کیا۔ لیکن اب جس کسی سے بھی میں یہ سورۃ سنتا ہوں سجدہ کیے بغیر نہیں رہ سکتا۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۴۶) استیعاب (ت: ۲۴۴۳) تجرید (۸۰/۲)\n(2) مسند احمد (الحدیث: ۴۲۰/۳) مصنف عبدالرزاق (الحدیث: ۵۸۸۱)"}],[8012,"§۸۰۳۲ ۔ المطلب السلمی\nبئر معونہ کی جنگ میں ان کا تذکرہ ملتا ہے۔ ابن لہیعہ نے ابوالاسود سے انہوں نے عروہ سے روایت کیا ہے کہ نبی علیہ السلام نے منذر بن عمر ساعدی کو بھیجا اور ان کے ساتھ مطلب سلمی بھی تھے۔ تاکہ ان کو راستہ بتا سکیں۔۔۔۔ پھر پورا واقعہ بیان کیا۔ طبرانی نے اپنے طریق سے اس حدیث کی تخریج کی ہے۔"],[8013,"§۸۰۳۳ ۔ مطیع بن اسود\nنسب: مطیع بن اسود بن مطلب بن اسد بن عبد العزی بن قصی۔ لقب: قرشی، اسدی۔ زبیر بن بکار فرماتے ہیں کہ میں نے زبیر بن عوام کو وصی (وصیت جاری کرنے والا) مقرر کیا۔ پھر ہشام بن عروہ کے طریق سے حدیث بیان کی کہ مطیع بن اسود نے کہا کہ میں نے خود سیدنا عمر رضی اللہ عنہ سے سنا ہے جو شخص وصی مقرر کرے تو زبیر بن عوام کو کرے اس لیے کہ وہ اسلام کے ستونوں میں سے ایک ستون ہیں۔\nاور ان کے والد اسود یہ وہی شخص ہیں جس نے عثمان بن حویرث سے قیصر کے دربار میں مقابلہ و معارضہ کیا تھا جبکہ اس نے یہ مطالبہ کیا تھا کہ مجھے مکہ کا گورنر بنا دیا جائے۔"],[8014,"§۸۰۳۴ ۔ مطیع بن اسود(1)\nنسب: مطیع بن اسود بن حارثہ بن نضلہ بن عوف بن عبید بن عوج بن عدی بن کعب بن لوی۔ لقب: قرشی، عدوی۔ پہلے ان کا نام عاصی (بمعنی نافرمان) تھا پھر نبی علیہ السلام نے تبدیل فرما کر مطیع (فرمانبردار) رکھ دیا یہ عبداللہ کے والد ہیں جن کا تذکرہ عین کی پٹی میں گزر گیا۔\nبقول ابن سعد(2) فتح مکہ کے دن مسلمان ہوئے اور نبی علیہ السلام(3) سے روایت کے ہیں جو کہ صحیح مسلم میں موجود ہے۔ ان کا بیٹا عبد اللہ اور عیسیٰ بن طلحہ تیمی اس کے روایت ہیں۔ بقول مصعب زبیری یہ عثمان رضی اللہ عنہ کے دورِ خلافت میں مدینہ کے اندر فوت ہوئے اور ابن البرقی کے بیان کے مطابق یہ جنگ جمل میں شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۴۷) استیعاب (ت: ۲۵۸۵) تجرید (۸۰/۲)\n(2) طبقات کبریٰ (۵۶/۵)\n(3) مسند احمد (الحدیث: ۴۱۲/۳) (الحدیث: ۲۱۳/۴) معجم الکبیر (الحدیث: ۲۹۲/۲۰)"}],[8015,"§۸۰۳۵ ۔ مطیع بن ذی\nبنی بکر بن کلاب کلابی میں سے ہیں۔ فاکہی نے کتاب مکہ میں ان کا تذکرہ کیا ہے۔ اور انہوں نے میمون بن حکم، محمد بن جعشم، اور ابن جریج سے روایت لی ہے فرماتے ہیں کہ نبی علیہ السلام نے ان کا نام مطیع رکھا حالانکہ اس سے پہلے ان کا نام عاصی تھا۔ اور(1) زیادہ ظاہر بات یہ ہے کہ جن کا نام عاصی تھا وہ آئندہ آنے والے مطیع بن عامر ہیں۔ اور لفظ ذی غلطی سے تبدیل ہو گیا ہے یہ اصل میں ذی لحیہ (داڑھی والا) تھا۔ لیکن فاکہی کی کتاب کا نسخہ تو بڑا با اعتماد اور یقینی ہے اور ہاں زیادہ کا احتمال ہو سکتا ہے۔","",{"fn":"(1) جامع المسانید (۳۴۲/۱۱)"}],[8016,"§۸۰۳۶ ۔ مطیع بن عامر(1)\nنسب: مطیع بن عامر بن عوف بن کعب بن ابی بکر بن کلاب بن ذواللحیہ کلابی کے بھائی ہیں۔ اور طبرانی، دار قطنی نے زائرین نبوت میں شمار کیا ہے اور بقی بن مخلد کی مسند میں ان کی حدیث موجود ہے۔ اور ابن الکلبی ان کا تذکرہ کرتے ہوئے فرماتے ہیں کہ یہ نبی علیہ السلام کے پاس آئے تھے تو آپ علیہ السلام نے پوچھا آپ کا نام کیا ہے؟ تو انہوں نے کہا: عاصی تو آقا علیہ السلام نے فرمایا آج کے بعد تمہارا نام مطیع ہے۔(2)","",{"fn":"(1) اسد الغابہ (ت: ۴۹۴۸) تجرید (۸۰/۲)\n(2) جامع المسانید (۳۴۲/۱۱)"}],[8017,"§۸۰۳۷ ۔ مطیہ بن مالک\nامام طبری نے صحابہ میں ان کا ذکر کیا ہے اور ابن فتحون نے اپنی مستدرک میں ان کا تذکرہ کیا ہے۔ اور مجھے تو اس بات کا اندیشہ ہے کہ یہ قطبہ بن مالک ہیں جن کا ذکر قاف کی تختی میں گزر گیا پھر غلطی سے قاف میم سے بدل گیا اور با، یا سے بدل گئی۔ واللہ اعلم"],[8018,"§۸۰۳۸ ۔ مظہر بن رافع(1)(2)\nنسب: مظہر بن رافع بن عدی بن یزید بن جشم بن حارثہ انصاری، حارثی۔ رافع بن خدیج کے چچا ہیں۔ اور بقول ابن ماکولا ان کا نام مُنظہر ہے اور ایک ان کا بھائی مُخیر ہے جس کو نبی علیہ السلام کی صحبت کا بھی شرف ملا اور روایت کا بھی ان دونوں سے روایت کرنے والے ان کے بھتیجے رافع ہیں۔\nمیں کہتا ہوں: صحیح بات یہ ہے کہ رافع کی اپنے دونوں چچا سے روایت مبہم ہے۔ ایک روایت میں مُظہیر نام ہے اور دوسرے کے بارے میں کہا جاتا ہے کہ ان کا نام مُخیر تھا۔ اور امام واقدی(3) شرکاء احد میں ان کا ذکر کیا ہے جو کہ سیدنا عمر رضی اللہ عنہ کے دور خلافت تک زندہ رہے پھر ان کے کافر غلاموں نے جو کہ ان کی زمین میں کھیتی باڑی کرتے تھے یہود کے ابھارنے پر ان کو خیبر میں شہید کر دیا۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۴۹) استیعاب (ت: ۲۵۸۶) تجرید (۸۰/۲)\n(2) الاکمال (۲۶۲/۲)\n(3) مغازی للواقدی (۷۱۶، ۷۱۷)"}],[8019,"§۸۰۳۹ ۔ معاذ بن انس الجہنی(1)\nیہ انصار کے ساتھی ہیں۔ بقول ابوسعید بن یونس: یہ صحابی ہیں ہیں جو کہ مصر و شام کے رہنے والے ہیں۔ انہوں نے نبی علیہ السلام کے علاوہ ابو درداء، کعب احبار سے بھی روایت بیان کی ہے اور خود ان سے روایت لینے والے صرف ان کے بیٹے سہل بن معاذ ہیں۔ ابواحمد عسکری کے بیان سے معلوم ہوتا ہے کہ عبد الملک بن مروان کے دور حکومت تک زندہ رہے۔ گویا کہ انہوں نے اس واقعہ کی طرف اشارہ کیا ہے جس کو امام بغوی رحمہ اللہ نے فروہ بن مجاہد کے طریق سے تخریج کیا ہے کہ سہل بن معاذ فرماتے ہیں کہ میں نے گرمی کے موسم میں عبدالملک کے زمانہ حکومت میں اپنے والد کے ساتھ جہاد میں شرکت کی ہے اور ہمارا امیر لشکر عبداللہ بن عبدالملک تھا۔ تو میرے والد لوگوں کے درمیان کھڑے ہو گئے(2)۔ پھر واقعہ ذکر کیا جس میں یہ بھی ہے کہ انہوں نے نبی علیہ السلام کی معیت میں جہاد کیا۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۵۰) استیعاب (ت: ۲۴۴۴) تجرید (۸۰/۲)\n(2) ترمذی کتاب صفۃ القیامۃ باب فی ترک اللباس (الحدیث: ۲۴۸۱) مستدرک حاکم (الحدیث: ۶۱/۱)"}],[8020,"§۸۰۴۰ ۔ معاذ بن جبل(1)\nنسب: معاذ بن جبل بن عمرو بن اوس بن عائذ بن عدی بن کعب بن عمرو بن ادی بن علی بن اسد بن ساردہ بن یزید بن جشم بن عدی بن نابی بن تمیم بن کعب بن سلمہ۔ کنیت: ابوعبدالرحمن۔ لقب: انصاری، خزرجی۔ حلال و حرام کے جاننے والے(2)، بہت بڑے امام و پیشرو تھے۔ بقول ابوادریس خولانی، یہ معاذ انتہائی سفید، خوبصورت چہرے والے، چمکدار دانتوں والے، سرمگیں آنکھوں والے تھے۔ اور بقول کعب بن مالک خوبصورت نوجوان تھے۔ بہت سخی تھے اپنی قوم کے ایک بہترین سپوت تھے۔\nاور بقول واقدی مردوں میں سب سے زیادہ خوبصورت مرد تھے اور تمام معرکوں میں شریک ہوئے۔\nانہوں نے نبی علیہ السلام سے کئی احادیث روایت کی ہیں۔ اور ان سے روایت کرنے والوں کی کثیر تعداد ہے۔ مثلاً ابن عباس، ابن عمر، ابن عدی، ابن ابی اوفی اشعری، عبد الرحمن بن سمرہ، جابر بن انس۔ ان کے علاوہ بڑے بڑے تابعین بھی ان سے روایت نقل کرتے ہیں۔ یہ غزوہ بدر میں شریک تھے، حالانکہ اس وقت ان کی عمر صرف اکیس سال تھی۔ اور نبی علیہ السلام(3) نے ان کو یمن کا گورنر مقرر فرمایا۔ اس کے بارے میں ابن عباس رضی اللہ عنہ کی روایت سے صحیح میں حدیث موجود ہے۔\nسیف نے فتوح میں اپنی سند کے ساتھ عبید بن صخر سے نقل کیا ہے کہ نبی علیہ السلام نے سیدنا معاذ رضی اللہ عنہ کو یمن کی طرف بھیجتے ہوئے ارشاد فرمایا: میں دین کے بارے میں تیری آزمائش کو اچھی طرح جان چکا ہوں اور وہ مشکلات جو محض دین کی وجہ سے تم پر ٹوٹ پڑیں گی، اور میں خوشنودی سے تمہیں ہدیہ لینے کی اجازت دیتا ہوں کہ اگر کوئی ہدیہ پیش کیا جائے تو اس کو قبول کر لینا۔ بقول راوی(4) پھر جب سیدنا معاذ رضی اللہ عنہ واپس لوٹے تو قیس غلام ان کو ہدیہ دینے گئے تھے۔ اسی سند کے ساتھ یہ بھی کہا کہ نبی علیہ السلام نے سیدنا معاذ کو الوداع کرتے ہوئے یوں دُعا دی تھی: \"اللہ تعالیٰ آپ کی حفاظت فرمائے آگے سے، پیچھے سے، دائیں سے، بائیں سے، تمہارے اوپر سے اور نیچے سے اور اللہ تعالیٰ تم سے جن و انس کے شر کو دور کر دے۔\"(5) سنن ابو داؤد(6) میں معاذ بن جبل سے روایت ہے فرماتے ہیں کہ نبی علیہ السلام نے مجھے ارشاد فرمایا: یقینا میں تم سے محبت کرتا ہوں ... الخ۔\nسیدنا انس رضی اللہ عنہ نے ان کو نبی علیہ السلام کے دور میں قرآن جمع کرنے والوں میں شمار کیا ہے یہ روایت بھی صحیح میں ہے۔ اور اسی حدیث میں یہ بھی ہے کہ عبد اللہ بن عمر رضی اللہ عنہ نبی علیہ السلام کی طرف منسوب کرتے ہوئے کہتے ہیں کہ آقا علیہ السلام کا ارشاد ہے کہ چار آدمیوں سے قرآن پڑھنا سیکھو، ان میں سے ایک سیدنا معاذ بن جبل رضی اللہ عنہ بھی ہیں۔\nامام شعبی رحمہ اللہ مسروق سے روایت کرتے ہوئے فرماتے ہیں کہ ہم ایک دفعہ سیدنا عبد اللہ ابن مسعود رضی اللہ عنہ کے پاس تھے کہ انہوں نے یہ پڑھا إِنَّ مُعَاذًا كَانَ أُمَّةً قَانِتًا لِلَّهِ تو فروہ بن نوفل نے کہا کہ لگتا ہے آپ بھول گئے ہیں تو عبداللہ بن مسعود رضی اللہ عنہ نے فرمایا نہیں۔ میں بھولا نہیں ہوں ہم تو صرف سیدنا معاذ رضی اللہ عنہ کو ابراہیم علیہ السلام سے تشبیہ دیتے ہیں۔ ابو نعیم نے حلیہ(7) میں سیدنا معاذ رضی اللہ عنہ کی شخصیت کو یوں بیان کیا۔ وہ فقہاء کے امام ہیں، علماء کا خزینہ ہیں، بیعت عقبہ میں شریک تھے۔ غزوہ بدر اور دیگر بہت سے معرکوں میں شرکت کی۔ انصار کے تمام نوجوانوں سے بہتر اور افضل تھے حلیم(8) تھے، باحیا تھے بہت سخی تھے، انتہائی خوبصورت اور خوش چہرے والے تھے۔\nان سے روایت کرنے والے صحابہ سیدنا عمر، ابو قتادہ، عبدالرحمن بن سمرہ وغیرہ ہیں۔\nعبدالرزاق کہتے ہیں: معمر اور زہری نے کعب بن مالک کے بیٹے سے نقل کرتے ہوئے ہمیں بتایا کہ سیدنا معاذ رضی اللہ عنہ انتہائی خوبصورت بھی نوجوان تھے اور بہت بڑے مستجاب الدعوات تھے جو بھی اللہ سے مانگتے اللہ انہیں عطا فرما دیتے تھے۔ بقول اعمش ابوسفیان فرماتے ہیں کہ ہمارے بہت سے بزرگوں نے ہمیں بتایا پھر پورا واقعہ ذکر کیا جس میں یہ بھی ہے کہ سیدنا عمر رضی اللہ عنہ نے ارشاد فرمایا کہ عورتیں معاذ جیسا نہ جن سکیں اور اگر معاذ نہ ہوتے تو عمر ہلاک ہو جاتا۔ محمد بن مخلد نے اپنے(9) فوائد میں اس کی تخریج کی ہے۔\nابوقلابہ کی سیدنا انس رضی اللہ عنہ سے روایت ہے جو امام ترمذی وغیرہ کے ہاں بعض صحابہ کے تذکرہ میں مرفوع ہے کہ صحابہ میں حلال و حرام کے سب سے بڑے عالم سیدنا معاذ ہیں۔\nابو عون ثقفی کی مرسل میں ہے کہ نبی علیہ السلام کا ارشاد ہے کہ قیامت کے دن معاذ لوگوں کے سامنے آئیں گے تاحد نظر بلندی پر ہوں گے۔ محمد بن عثمان بن ابی شیبہ(10) نے اپنی تاریخ میں اس کی تخریج کی ہے اور ابن عساکر(11) بھی ایک طریق سے محمد بن خطاب سے اس روایت کو لائے ہیں۔ طبقات ابن سعد(12) میں منقطع کے طریق سے ہے کہ نبی علیہ السلام نے سیدنا معاذ کو یمن کی طرف بھیجتے ہوئے ایک خط تحریر کروایا جس میں لکھا تھا: اے یمن والو! اپنے لوگوں میں سب سے بہترین بندہ تمہاری طرف بھیج رہا ہوں۔ ان کے فضائل و مناقب بہت زیادہ ہیں۔ سیدنا ابو بکر رضی اللہ عنہ کے دور خلافت میں یمن سے واپس آئے۔ وفات: ۱۷ھ یا ۱۸ھ عند الاکثر ملک شام میں طاعون کے مرض سے وفات پائی۔ کل عمر صرف ۳۴ سال تھی۔ اس(13) کے علاوہ بھی کچھ ضعیف قول ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۵۳) استیعاب (ت: ۲۴۴۵) تجرید (۸۰/۲)\n(2) ترمذی کتاب المناقب باب مناقب معاذ بن جبل (الحدیث: ۳۷۹۰) مسند احمد (الحدیث: ۲۲۹/۵) معجم الکبیر (الحدیث: ۲۰) توحید لابن خزیمہ (۳۳۷)\n(3) اسد الغابہ (۱۴۳/۴)\n(4) کنز العمال (الحدیث: ۱۵۰۸۶)\n(5) مختصر تاریخ دمشق (۳۷۲/۲۴)\n(6) ابو داؤد کتاب الصلاۃ باب الاستغفار (الحدیث: ۱۵۲۲)\n(7) بخاری کتاب فضائل القرآن باب القراء من اصحاب النبی (الحدیث: ۵۰۰۳) کتاب فضائل الصحابہ باب فضائل ابی بن کعب (الحدیث: ۶۲۹۰) مسند احمد (الحدیث: ۲۳۳/۳)\n(8) حلیۃ الاولیاء (۲۳۰/۱)\n(9) تاریخ دمشق (۳۷۴/۲۴) جامع المسانید (۳۶۳/۱۱)\n(10) معجم الکبیر (الحدیث: ۴۰/۲۰) (الحدیث: ۴۱/۲۰) مجمع الزوائد (الحدیث: ۳۱۱/۹) کنز العمال (الحدیث: ۳۳۳۶۴۱) حلیۃ الاولیاء (الحدیث: ۲۲۹/۱)\n(11) تاریخ دمشق (۳۷۳/۲۴)\n(12) طبقات کبریٰ (۵۹۰/۳)\n(13) مستدرک حاکم (الحدیث: ۲۷۱/۳) حلیۃ الاولیاء (الحدیث: ۲۴۰/۱)"}],[8021,"§۸۰۴۱ ۔ معاذ بن الحارث بن الارقم(1)\nنسب: معاذ بن حارث بن ارقم بن عوف بن وہب بن عمرو بن عوف بن غنم بن مالک بن نجار۔ لقب: انصاری، خزرجی۔ کنیت: ابو حلیمہ اس کنیت سے یہ زیادہ مشہور ہیں۔ اور ان کو قاری بھی کہا جاتا ہے۔ یا ان کی کنیت ابوالحارث ہے اور لقب ابو حلیمہ۔ بقول ابوعمر(2) یہ غزوہ خندق میں شریک تھے۔\nایک قول کے مطابق ان کو نبی علیہ السلام کے ساتھ صرف چھ سال رہنے کا موقع ملا۔ انہوں نے نبی علیہ السلام(3) سے بھی روایت کی اور خلفاء راشدین میں سے ابو بکر، عمر، عثمان رضی اللہ عنہم سے۔ ان سے روایت نقل کرنے والے ابن عمر رضی اللہ عنہ کے غلام نافع، عمران بن ابی انس، سعید المقبری، اور ابوالولید بصری ہیں۔ ابوعون مرسلاً بیان کرتے ہیں کہ ابو حلیمہ رمضان شریف میں دعائے قنوت پڑھا کرتے تھے۔ بقول امام بخاری رحمہ اللہ(4) شاید یہ مدینہ کے رہنے والے تھے اور ابو عبیدہ کے ساتھ واقعہ جسر میں شریک تھے۔ جب سب لوگ بھاگ گئے تو ان سے سیدنا عمر رضی اللہ عنہ نے فرمایا: میں تمہاری جماعت ہوں۔\nبزار اور ابن مندہ نے ربیعہ بن عثمان کے طریق سے تخریج کیا ہے کہ عمران بن ابی انس نے فرمایا کہ میں نے معاذ بن حارث سے سنا ہے کہ میں نے نبی علیہ السلام سے خود یہ ارشاد سنا ہے کہ میرا منبر جنت کے دروازوں میں سے ایک دروازے پر ہے۔(5) وفات: بقول ابن حبان انہوں نے زندگی کی کل ۶۹ بہاریں دیکھیں۔ ابن سعد(6) اور ابواحمد حاکم اور ابوحاتم رازی کے بقول یہ حرہ نامی جنگ میں شہید ہو گئے۔ میں کہتا ہوں: یہ حرہ نامی جنگ ۶۳ھ میں ہوئی، لہذا ان کی بیان کردہ عمر صحیح ہوئی۔ اور یہ وہی شخصیت ہیں جن کو سیدنا عمر رضی اللہ عنہ نے رمضان المبارک میں لوگوں کو تراویح پڑھانے کے لیے مقرر فرمایا تھا۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۵۴) استیعاب (ت: ۲۴۴۶) تجرید (۸۰/۲)\n(2) استیعاب (۴۶۲/۳)\n(3) جامع المسانید (۵۲۱/۱۱)\n(4) تاریخ کبیر (۳۶۱/۷)\n(5) مسند احمد (الحدیث: ۲۲۵/۵) (الحدیث: ۳۳۹/۵) معجم الکبیر (الحدیث: ۵۷۷۹/۶) (الحدیث: ۵۸۰۹/۶) سنن کبریٰ (الحدیث: ۲۴۷/۵) مجمع الزوائد (الحدیث: ۹/۴) جامع المسانید (۵۲۲/۱۱)\n(6) طبقات کبریٰ (۱۰/۱)"}],[8022,"§۸۰۴۲ ۔ معاذ بن حارث بن رفاعہ(1)\nنسب: معاذ بن حارث بن رفاعہ بن حارث بن سواد بن مالک بن غنم بن مالک بن نجار۔ نسب: انصاری، خزرجی۔ المعروف: ابن عفراء۔ بعض حضرات نے ان کے نسب میں موجود دوسرے حارث کا ذکر نہیں کیا۔ عفراء ان کی والدہ کا نام تھا اس سے یہ مشہور ہو گئے۔ بیعت عقبہ اولیٰ میں یہ اوس و خزرج کے ان چھ آدمیوں میں سے تھے جو سب سے پہلے نبی علیہ السلام سے ملے۔ غزوہ بدر میں شریک تھے۔ ابو جہل کے قتل میں بھی حصہ لیا۔ پھر بعد میں بھی زندہ رہے(2) ایک قول کے مطابق غزوہ بدر میں زخمی ہو گئے تھے پھر اسی زخم سے ان کی وفات ہوگئی۔\nان کی نبی علیہ السلام سے روایت سنن نسائی(3) وغیرہ میں موجود ہے نصر بن عبد الرحمن قرشی کے طریق سے۔ ان کی سند میں علی بن نصر پر اختلاف ہے۔ امام بغوی رحمہ اللہ کے ہاں سند صحیح ہے کہ نصر معاذ سے اور وہ قریش کے ایک آدمی سے نقل کرتے ہیں کہ میں نے معاذ بن عفراء کو بیت اللہ کا طواف کرتے ہوئے دیکھا ہے۔ انہوں نے طواف تو کیا لیکن عصر یا فجر کے بعد کا وقت تھا، لہذا نفل نہیں پڑھے۔ اور ارشاد فرمایا کہ میں نے نبی علیہ السلام سے خود سنا ہے کہ آپ فجر کے بعد نفل پڑھنے سے منع فرماتے تھے ...الخ۔ اور امام بغوی رحمہ اللہ کے ہاں ابو نصر سلیمان بن زیاد کے طریق سے معاذ بن عفراء سے روایت ہے کہ نبی علیہ السلام نے ارشاد فرمایا کہ میں نے اپنے رب کی زیارت کی ...الخ۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۵۵) تجرید (۸۱/۲)\n(2) معجم الکبیر (۱۷۷/۱۰) سیرۃ النبویۃ (۲۶۱/۲)\n(3) نسائی کتاب المواقیت باب من ادرک رکعتین من العصر (الحدیث: ۵۱۷) مصنف بن ابی شیبہ (الحدیث: ۳۴۸/۲) آحاد والمثانی (الحدیث: ۲۱/۴)"}],[8023,"§۸۰۴۳ ۔ معاذ بن الحارث بن سراقہ(1)\nلقب: انصاری، سلمی۔ ابن سعد(2) نے صحابہ رضی اللہ عنہم میں ان کا تذکرہ کیا ہے۔ ان کی شادی براء بن معرور کی بیٹی رباب سے ہوئی تھی جس سے ان کے بیٹے سعد پیدا ہوئے۔\nمیں کہتا ہوں: یہ سعد بن معاذ مشہور صحابی نہیں ہیں بلکہ صرف نام و نسب میں موافقت ہے وہ صحابی تو قبیلہ اوس کے سردار تھے جبکہ یہ تو خزرجی ہیں لہذا دونوں میں فرق واضح ہو گیا۔","",{"fn":"(1) تجرید (۸۰/۲)\n(2) طبقات کبریٰ (۲۰۰/۱)"}],[8024,"§۸۰۴۴ ۔ معاذ بن رباح\nنسب: معاذ بن رباح بن عمرو بن عبد اللہ بن انمار بن مالک بن بیار بن حطیط بن جشم ثقفی۔ کنیت ابو زہیر اور اس کنیت سے یہ مشہور ہیں ان کے نام میں اختلاف ہے۔ انہوں نے نبی علیہ السلام سے روایت بیان کی ہے۔(1)","",{"fn":"(1) ابن ماجہ کتاب الزہد باب الثناء الحسن (الحدیث: ۴۲۲۱) مسند احمد (الحدیث: ۴۱۶/۳) (الحدیث: ۴۶۶/۶) مستدرک حاکم (الحدیث: ۴۳۶/۴) سنن کبریٰ (الحدیث: ۱۲۳/۱۰) صحیح ابن حبان کتاب اخبارہ عن مناقب الصحابہ باب وصف الجنۃ و اہلہا (الحدیث: ۷۳۸۴) مصنف ابن شیبہ (الحدیث: ۵۱۰/۱۴) معجم الکبیر (الحدیث: ۳۸۲/۲۰)"}],[8025,"§۸۰۴۵ ۔ معاذ بن رفاعہ انصاری زرقی\nامام واقدی رحمہ اللہ نے ان کے تذکرہ میں لکھا ہے کہ غزوہ بنو قریظہ میں شریک تھے اور نبی علیہ السلام کے ساتھ گھوڑے پر تھے۔ میں کہتا ہوں: تابعین میں ایک اور معاذ بن رفاعہ ہیں جو اپنے والد رفاعہ، سیدنا جابر اور سیدہ خولہ سے روایت نقل کرتے ہیں۔ اور ان سے روایت لینے والے عبداللہ بن محمد بن عقیل ہیں۔"],[8026,"§۸۰۴۶ ۔ معاذ بن زرارہ(1)\nنسب: معاذ بن زرارہ بن عمرو بن عدی بن حارث۔ بنو ظفر سے ان کا تعلق ہے۔ بقول ابوعمر(2) یہ اور ان کے والد ابو غلہ، ابوذرہ غزوہ اُحد میں شریک تھے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۵۷) استیعاب (ت: ۲۴۴۷) تجرید (۸۱/۲)\n(2) استیعاب (۴۶۳/۳)"}],[8027,"§۸۰۴۷ ۔ معاذ بن سعد(1)\nمعاذ بن سعد یا سعد بن معاذ انصاری صحیح بخاری(2) میں شک کے ساتھ ذکر کیا ہے۔ موطا(3) میں امام مالک نافع سے اور وہ انصار کے ایک آدمی سے نقل کرتے ہیں کہ معاذ بن سعد یا سعد بن معاذ نے فرمایا کہ کعب بن مالک کی ایک لونڈی سلع میں بکریاں چرایا کرتی تھی ...الخ۔ امام بخاری رحمہ اللہ ہی یہ کتاب الذبائح میں نافع کی روایت کے بعد اس کو لائے ہیں، کعب بن مالک کے بیٹے اپنے بھائی سے نقل کرتے ہیں کہ ہاں واقعی ان کی ایک لونڈی تھی۔ ابن مندہ، ابونعیم اور ابن فتحون(4) نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۵۹) تجرید (۸۱/۲)\n(2) بخاری باب ذبیحۃ المرأۃ (الحدیث: ۵۵۰۵)\n(3) موطاء امام مالک کتاب الذبائح باب ما یجوز فی الزکوۃ (الحدیث: ۱۰۸۳) جامع المسانید (۵۲۳/۱۱)\n(4) اسد الغابہ (ت: ۴۹۶۰) استیعاب (ت: ۲۴۴۸) تجرید (۸۱/۲)"}],[8028,"§۸۰۴۸ ۔ معاذ بن الصمہ\nمعاذ بن صمہ بن عمرو بن جموح انصاری۔ بقول عدوی یہ غزوہ اُحد میں شریک تھے اسی طرح اس کے بعد کے غزوات میں شریک رہے، یہاں تک کہ حرہ میں شہید ہو گئے۔\nابو عبید قاسم بن سلام نے لکھا ہے کہ معاذ بن صمہ اور ان کا بھائی خراش دونوں غزوہ بدر میں شریک تھے۔ لہذا لکھ لیا جائے کہ یا یہ وہی ہیں یا کوئی اور ہیں۔"],[8029,"§۸۰۴۹ ۔ معاذ بن عبداللہ\nمعاذ بن عبد اللہ بن حطب۔ امام طبری رحمہ اللہ نے ان کا ذکر کیا ہے اور ابن فتحون نے اپنی مستدرک میں اس کا ذکر کیا ہے۔"],[8030,"§۸۰۵۰ ۔ معاذ بن عبداللہ التیمی\nبقول ابن حبان ان کو نبی علیہ السلام کی صحبت کا شرف حاصل ہوا۔"],[8031,"§۸۰۵۱ ۔ معاذ بن عبدالرحمن(1)\nنسب: معاذ بن عبد الرحمن بن عثمان بن عبد اللہ تیمی، ابن السکن نے ان کے والد کے حالات میں ان کا ذکر کیا ہے اور کہا ہے یہ دونوں بارگاہ نبوت کے صحبت یافتہ تھے۔ ابن فتحون نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے بحوالہ خلیفہ۔ امام بخاری رحمہ اللہ(2) فرماتے ہیں کہ انہوں نے اپنے والد سے سنا اور ان سے روایت لینے والے امام زہری ہیں۔ ان کا شمار ز کے رہنے والوں میں ہے۔ بعض کا کہنا ہے کہ سیدنا معاذ نے سیدنا عمر بن خطاب رضی اللہ عنہ سے روایت سنی ہے۔ حالانکہ یہ بات صحیح نہیں اور یہ معاذ عثمان کے بھائی ہیں۔ ابو حاتم کا بھی یہی قول ہے۔ نیز یہ کہ سیدنا عمر رضی اللہ عنہ سے ان کا سماع صحیح بات نہیں ہے۔ لہذا جب سیدنا عمر سے سماع صحیح نہیں تو یہ کیسے ہو سکتا ہے کہ انہوں نے نبی علیہ السلام کا زمانہ پایا ہو یا ان سے روایت کی ہو۔\nمیں کہتا ہوں: ان کی حدیث بخاری، مسلم اور نسائی میں حمران سے مروی ہے جو کہ اپنے آقا عثمان سے نقل کرتے ہیں پھر بخاری میں محمد بن ابراہیم تیمی کے طریق سے ہے جبکہ مسلم اور نسائی(3) میں نافع بن جبیر وغیرہ کے طریق سے ہے۔ یہ سب کی سب معاذ بن عبد الرحمن سے مروی ہیں جو کہ حمران سے روایت کرتے ہیں۔ ابن سعد نے مدینہ کے رہنے والوں میں سے طبقہ ثانیہ میں ان کا ذکر کیا ہے۔ ابن حبان نے معتمد علیہ تابعین میں شمار کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۶۱) استیعاب (ت: ۲۴۴۹) تجرید (۸۱/۲)\n(2) تاریخ کبیر (۳۶۳/۴)\n(3) نسائی کتاب المناسک باب ما ذکر فی منی (الحدیث: ۲۹۹۶)"}],[8032,"§۸۰۵۲ ۔ معاذ بن عثمان\nیہ معاذ بن عثمان ہیں یا عثمان بن معاذ ہیں۔ حمیدی نے اپنی مسند میں ان کی حدیث کی ابن عیینہ سے روایت کی ہے لیکن اسی شک کے ساتھ۔ لیکن معاذ بن عثمان ہونے کو ترجیح دی ہے ان کا تذکرہ عثمان کی تختی میں ہو چکا ہے۔"],[8033,"§۸۰۵۳ ۔ معاذ بن عفراء(1)\nیہ وہی حارث کے بیٹے ہیں جن کا ذکر پیچھے ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۶۲) استیعاب (ت: ۲۴۵۱) تجرید (۸۱/۲)"}],[8034,"§۸۰۵۴ ۔ معاذ بن عمرو بن الجموح\nنسب: معاذ بن عمرو بن جموح بن زید بن حرام بن کعب بن غنم بن کعب بن سلمہ، انصاری، خزرجی، سلمی۔ بقول امام بخاری رحمہ اللہ(1) ان کو نبی علیہ السلام کی صحبت کا شرف حاصل ہوا۔ ان کے والد کا تذکرہ بھی پیچھے گزر چکا ہے۔ یہ معاذ بیعت عقبہ میں بھی شریک تھے اور غزوہ بدر(2) میں شریک ہونے کے ساتھ ساتھ ابو جہل کے قتل کرنے والوں میں سے بھی ہیں۔ ابن اسحاق(3) مغازی میں فرماتے ہیں کہ ثور نے مجھے بتایا کہ عکرمہ ابن عباس رضی اللہ عنہ سے روایت کرتے ہیں کہ معاذ بن عمرو بن جموح نے کہا کہ میں نے لوگوں کو یہ کہتے ہوئے سنا کہ اس تک پہنچنا بہت مشکل ہے لیکن میں اس کی تاک میں رہا آخر میں اس کی طرف لپکا اور ایسی زبر دست ضرب لگائی کہ اس کے پاؤں کٹ گئے۔\nابن اسحاق نے بھی ابن ابی خیثمہ کی تخریج میں ذکر کیا ہے یوسف بھلول عبد اللہ بن ادریس سے اور وہ عبدالملک بن ابی بکر اور ان کے ساتھ ایک اور آدمی سے نقل کرتے ہیں اور یہ دونوں عکرمہ سے اور وہ ابن عباس رضی اللہ عنہ سے کہ معاذ بن عفراء نے کہا کہ میں نے کچھ لوگوں کو دیکھا کہ وہ جتھے کی شکل میں جمع ہو کر کہہ رہے تھے کہ ابوالحکم (ابو جہل) تک پہنچنا بہت مشکل ہے۔ جب میں نے یہ بات سنی تو میں اس کی تاک میں رہا جیسے ہی مجھے اس پر دسترس حاصل ہوئی تو میں نے اس پر حملہ کر دیا۔ الخ۔ پچھلی حدیث میں معاذ بن عمرو کا نام ہے اور اس حدیث میں معاذ بن عفراء کا۔ ممکن ہے کہ دونوں نے ہی حملہ کیا ہو لیکن راجح وہی ہے جو صحیحین میں ابو جہل کا واقعہ بیان کیا گیا ہے۔ عبدالرحمن بن عوف کی حدیث میں ہے کہ اس کو عفراء کے دو بیٹوں نے مارا، یکلخت وہ خاموش ہو گیا (یہاں تک کہ وہ ٹھنڈا ہو گیا) ان کے نام معوذ اور معاذ تھے۔\nمغازی میں یہ بھی اضافہ ہے کہ پھر ابو جہل کے بیٹے عکرمہ نے معاذ بن عمرو پر حملہ کیا اور ان کا ہاتھ کٹ گیا لیکن ابھی ساتھ ہی لٹک رہا تھا کہ انہوں نے اس پر پاؤں رکھ کر اس زور سے کھینچا کہ اس کو بدن سے جدا کر دیا اور پھر جہاد و لڑائی میں مصروف ہو گئے۔ اس کے بعد بھی وہ ایک زمانہ تک حیات رہے اور سیدنا عثمان رضی اللہ عنہ کے دور خلافت میں دار فانی سے دار بقاء کی طرف کوچ فرمایا۔ امام بخاری رحمہ اللہ(4) و غیرہ بھی اسی کے قائل ہیں۔","",{"fn":"(1) تاریخ کبیر (۳۶۰/۴)\n(2) سیرۃ النبویۃ (۲۰۸/۲)\n(3) سیرۃ النبویۃ (۸۰/۲)\n(4) تاریخ کبیر (۳۶۰/۴)"}],[8035,"§۸۰۵۵ ۔ معاذ بن عمرو بن قیس(1)\nنسب: معاذ بن عمرو بن قیس بن عبدالعزی بن غزنیہ بن عمرو بن عدی بن عوف بن مالک بن نجار انصاری خزرجی۔ امام بغوی رحمہ اللہ نے ابن القداح کے حوالہ سے نقل کیا ہے کہ یہ غزوہ اُحد اور اس کے بعد کے غزوات میں شریک تھے اور جنگ یمامہ میں ان کی شہادت ہوئی۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۶۳) استیعاب (ت: ۲۴۵۲) تجرید (۸۱/۲)"}],[8036,"§۸۰۵۶ ۔ معاذ بن ماعص(1)\nنام: معاذ بن ماعص یا معاذ بن مُعاص یا معاذ بن ناعص۔ نسب: معاذ بن ماعص بن میسرہ بن خلدہ بن عامر بن زریق۔ یہ عباد انصاری زرقی کے بھائی ہیں۔ بقول ابن اسحاق(2) اور موسیٰ بن عقبہ یہ معاذ غزوہ بدر میں شریک تھے۔ واقدی یونس بن محمد ظفری سے روایت کرتے ہیں کہ معاذ بن رفاعہ نے کہا کہ معاذ بن ماعص غزوہ بدر میں زخمی ہو گئے تھے پھر اسی زخم سے ان کی موت واقع ہوئی۔ امام واقدی رحمہ اللہ فرماتے ہیں کہ غزوہ بدر و اُحد میں ان کی شرکت یقینی ہے اور بئر معونہ میں ان کی شہادت ہوئی۔ ابن مندہ نے ابراہیم بن منذر کے طریق سے محمد بن طلحہ تیمی سے نقل کیا ہے کہ معاذ بن ماعص ان لوگوں میں سے ہیں جنہوں نے نبی علیہ السلام کی اونٹنیاں بھگا لے جانے والوں کا پیچھا کیا تھا۔ عیینہ بن حصن کے ساتھ اور ان کے امیر سعید بن زید تھے۔ امام واقدی رحمہ اللہ نے بھی ابو بکر بن ابی جہم کے طریق سے اسی طرح کی روایت کی ہے۔ موسیٰ بن عقبہ کے مغازی میں ہے کہ یہ غزوہ موتہ میں(3) شہید ہو گئے۔ جبکہ اسی کتاب کے ایک نسخہ میں ہے کہ یہ شہید ہونے والے ان کے بھائی عباد تھے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۶۴) استیعاب (ت: ۲۴۵۳) تجرید (۸۱/۲)\n(2) سیرۃ النبویۃ (۲۵۹/۳) طبقات کبریٰ (۵۹۵/۳)\n(3) مختصر تاریخ دمشق (۳۸۵/۲۴)"}],[8037,"§۸۰۵۷ ۔ معاذ بن محمود(1)\nمعاذ بن محمود بن عمرو بن محصن انصاری۔ کنیت: ابوالحارث مدینہ کی مسجد کے امام تھے۔ ابن ابی حاتم اپنے والد سے نقل کرتے ہیں کہ یہ تینتیس سال مدینہ کی مسجد کے امام رہے اور ۵۴ھ میں وفات ہوئی۔ بقول امام ذہبی رحمہ اللہ اس سے معلوم ہوا کہ یہ صحابی ہیں جیسا کہ بعض حضرات اس کے قائل ہیں۔","",{"fn":"(1) تجرید (۸۲/۲)"}],[8038,"§۸۰۵۸ ۔ معاذ الانصاری\nبحکایت ابو عمر یہ ابوزید ہیں جو کہ جامع قرآن تھے اور یہ اپنی کنیت سے ہی زیادہ مشہور ہوئے ان کے نام کے بارے میں بہت زیادہ اختلاف ہے۔"],[8039,"§۸۰۵۹ ۔ معان بن عمرو النہرانی(1)\nابو فتح ازدی نے اسماء المفردۃ من الصحابہ میں ان کا تذکرہ کیا ہے اور ابو موسیٰ نے بھی اپنی مستدرک میں ان کا ذکر کیا ہے اور ابن اثیر(2) فرماتے ہیں کہ مجھے معلوم نہیں کہ ان کے نام کے آخر میں زاء ہے یا نون ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۶۸) تجرید (۸۲/۲)\n(2) اسد الغابہ (۱۵۱/۴)"}],[8040,"§۸۰۶۰ ۔ معافی بن زید الجرشی(1)\nابن مندہ نے عبدالعزیز بن قیس کے طریق سے ان کا ذکر کیا ہے حمید سے اور وہ سیدنا انس سے نقل کرتے ہیں کہ نبی علیہ السلام کے پاس تہامہ کے لوگوں میں سے ایک آدمی لایا گیا جس کو معافی بن زید جرشی کہا جاتا تھا اس نے آتے ہی سوال کیا کہ آپ نبیذ کے بارے میں کیا ارشاد فرماتے ہیں ... الخ۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۶۹) تجرید (۸۲/۲)"}],[8041,"§۸۰۶۱ ۔ معاویہ بن انس السلمی\nسیف نے فتوح میں ان کا تذکرہ کیا ہے سہل بن یوسف قاسم بن محمد سے نقل کرتے ہیں کہ یہ ان لوگوں میں سے ہیں جنہوں نے نبی علیہ السلام کی زندگی میں اسود عنسی کے ساتھ جنگ کی تھی۔"],[8042,"§۸۰۶۲ ۔ معاویہ بن ثور(1)\nنسب: معاویہ بن ثور بن عبادہ بن بکاء عامری، بکائی۔ ان کے بیٹے بشر بن معاویہ کے حالات میں اسی طرح عمرو بن کعب کے غلام کے حالات میں نیز ان کے دادا عبادہ کے حالات میں ان کا تذکرہ ہو چکا ہے (ابو عمر(2) اور عقیلی کے ہاں یہ عبادہ عین کے زیر کے ساتھ ہے)۔ اور ابن مندہ نے گزشتہ سند کے ساتھ بشر کے حالات میں ان کا تذکرہ کرتے ہوئے فرمایا کہ نبی علیہ السلام نے سیدنا معاویہ رضی اللہ عنہ کے نام کچھ زمین لکھ کر دی اور ان کو ایک سال کی زکوۃ میں بطور امداد کے مال عطا فرمایا۔ لیکن سیدنا معاویہ جب گھر لوٹے تو کہنے لگے میں نے تو آج یا کل مر کر مٹی ہو جانا ہے اور میرے پاس اتنا زیادہ مال ہے جبکہ میرے صرف دو بیٹے ہیں تو اسی وقت نبی علیہ السلام کے پاس گئے اور عرض کیا اے اللہ کے رسول! مجھ سے کچھ مال واپس لے لیجئے، اور دشمن کے مقابلے میں خرچ فرمائیے۔ میں تو بہت مالدار ہو گیا ہوں۔ تو آقا علیہ السلام نے فرمایا: اے معاویہ(3) تمہیں آزمایا گیا تھا پھر آپ نے اس میں سے کچھ رکھ لیا۔ ابن الکلبی فرماتے ہیں: محمد بن بشر بن معاویہ اپنے دادا کے کارناموں پر ان الفاظ میں فخر کرتا ہے:\n۱۔ میرا باپ تو وہ تھا جس کے سر پر نبی علیہ السلام نے ہاتھ پھیرا اور ان کے لیے خیر و برکت کی دُعا فرمائی۔\n۲۔ جبکہ ان کو نبی علیہ السلام نے خاکستری رنگ کے بوجھل قسم کے نیزے تھمائے جو کہ میدانِ جنگ میں شور و غل کرنے والے تھے۔\n۳۔ جو ہر شام، قبیلے کے بڑے پیالے کو بھر دیتے ہیں اور صبح کے وقت پھر دوبارہ بھرنے کے لیے لوٹ آتے ہیں۔\n۴۔ استعمال کے لیے دودھیا جانور میں بھی برکت ہو اور وہ جانور دینے والے میں بھی اور میری طرف سے جب تک میں زندہ ہوں تمہیں دعائیں ملتی رہیں۔\nمجمع عامری کے حالات میں بھی ان کا تذکرہ گزر چکا ہے اور ان کا ایک بھائی عبداللہ بن ثور تھا جس کا ذکر پہلے ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۷۰) استیعاب (ت: ۲۴۵۹) تجرید (۸۲/۲)\n(2) استیعاب (۴۶۸/۳)\n(3) کنز العمال (الحدیث: ۳۶۸۶۰) تاریخ کبیر (۸۳/۲) جامع المسانید (۲۸۰/۲)"}],[8043,"§۸۰۶۳ ۔ معاویہ بن جاہمہ(1)\nنسب: معاویہ بن جاہمہ بن عباس بن مرداس سلمی۔ امام بغوی رحمہ اللہ وغیرہ نے ان کو صحابہ رضی اللہ عنہم میں شمار کیا ہے۔ اور ان کی روایت کردہ حدیث کی سند میں اختلاف ہے جو جاہمہ کے حالات میں جیم کی تختی میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۷۳) استیعاب (ت: ۲۴۶۱) تجرید (۸۲/۲)"}],[8044,"§۸۰۶۴ ۔ معاویہ بن حارث\nمعاویہ بن حارث بن مطلب بن عبد مناف۔ ابن اسحاق نے سیرۃ کبریٰ میں ان کا تذکرہ کرتے ہوئے کتاب مکہ میں اپنے طریق سے ان کا ایک دلچسپ واقعہ لکھا ہے کہ یہ معاویہ بن حارث اپنی تلوار لٹکائے ہوئے نبی علیہ السلام سے کہتے تھے کہ آپ نماز پڑھیے جو بھی آپ کو تنگ کرے گا میں اس کی گردن اڑا دوں گا لیکن جب ان کا انتقال ہو گیا تو ابو طالب نے ان کے بارے میں یہ شعر کہا۔\nمعاویہ نے رُلا دیا اس جیسا کوئی اور معاویہ نہیں ہے۔ وہ بہترین نوجوان تھا نیکی و بھلائی میں نہ کہ برائی میں۔\nمیں کہتا ہوں: زبیر کے بیان کردہ نسب ناموں میں نے ان کا تذکرہ نہیں دیکھا، ہاں البتہ ان کے بھائی عبیدہ، طفیل اور حصین کا ذکر ہے اور یہ بھی مذکور ہے کہ عبیدہ اور ان کے دوسرے بھائی اسلام لے آئے تھے۔ میرا ذاتی خیال یہ ہے کہ چونکہ ان کی نسل نہ رہی لہذا ان کے اپنے حالات بھی مخفی رہے۔"],[8045,"§۸۰۶۵ ۔ معاویہ بن حدیج(1)\nمعاویہ بن حدیج بن جفنہ بن تجیب کنیت ابو نعیم۔ ان کو ابو عبد الرحمن السکونی بھی کہتے ہیں بقول امام بخاری یہ خولانی ہیں امام زہری نے ان کا نسب بیان کرتے ہوئے ان کو مصر کے رہنے والوں میں شمار کیا ہے۔ اور بقول امام بغوی یہ سیدنا معاویہ کی طرف سے مصر کے گورنر تھے۔\nمیں کہتا ہوں: سیدنا معاویہ رضی اللہ عنہ نے ان کو اس لشکر کا امیر بنایا تھا جس کو مصر کی طرف جانے کے لیے تیار کیا اور ان میں سیدنا ابو بکر صدیق رضی اللہ عنہ کے بیٹے محمد بھی تھے پھر جب لوگوں نے ان کو قتل کر دیا تو اس کے بعد سیدنا معاویہ کے ہاتھ پر بیعت کی اس کے بعد پھر مصر کی امارت و حکومت کی باگ ڈور یزید نے سنبھال لی۔\nابن سعد نے مصر کے گورنر صحابہ رضی اللہ عنہم میں ان کا بھی ذکر کیا ہے۔\nابن یونس فرماتے ہیں کہ ان کی کنیت ابونعیم ہے، یہ نبی علیہ السلام کی خدمت میں حاضر ہوئے تھے اور مصر کی فتح میں شریک تھے، پھر اسکندریہ کی فتح کے موقع پر سیدنا عمر رضی اللہ عنہ کے پاس آئے اس وقت ان کی ایک آنکھ۔ ابن ابی سرح کی ہمراہی میں جنگ نوبہ میں شہید ہو چکی تھی۔ اس طرح مغرب کے تمام غزوات میں شریک رہے، سب سے آخری جنگ ۵۰ھ میں ہوئی اور ان کی وفات ۵۲ھ میں ہوئی۔\nابو داؤد اور نسائی نے نماز کے اندر بھول جانے کے بارے میں ایک حدیث ان کی ذکر کی جبکہ امام نسائی رحمہ اللہ نے اس کے علاوہ پچھنے لگوانے سے علاج اور غسل کے بارے میں بھی ان کی حدیث تخریج کی ہے۔ امام بغوی رحمہ اللہ ان کی حدیث میں یہ الفاظ بیان کرتے ہیں کہ انہوں نے فرمایا کہ میں نے خود نبی علیہ السلام کو یہ ارشاد فرماتے ہوئے سنا ہے: اللہ کے راستے میں ایک صبح یا ایک شام دنیا اور جو کچھ اس دنیا میں ہے، سب کچھ سے بہتر ہے۔(2) امام احمد رحمہ اللہ(3) نے تینوں احادیث کی یزید بن ابی حبیب کے طریق سے تخریج فرمائی ہے۔ کہ سوید بن قیس معاویہ سے نقل کرتے ہیں۔ اسی طرح امام احمد رحمہ اللہ نے ثابت بنانی کے طریق سے بھی تخریج کی ہے کہ صالح بن جبیر ان سے میت کے دفن کے بارے میں مرفوعاً حدیث نقل کرتے ہیں۔ اور ابن لہیعہ کے طریق سے حارث بن یزید سے روایت ہے کہ علی بن رباح معاویہ سے نقل کرتے ہیں کہ انہوں نے فرمایا کہ ہم نے سیدنا ابو بکر رضی اللہ عنہ کے دور میں ہجرت کی اس اثناء میں کہ ہم ان کے پاس تھے۔۔۔۔ پھر آب زمزم والا پورا واقعہ بیان کیا۔\nبقول اثرم امام احمد رحمہ اللہ سے نقل کرتے ہیں کہ ان کو نبی علیہ السلام کی صحبت کا شرف نہیں ملا اور یعقوب بن سفیان اور ابن حبان نے ان کو تابعین میں شمار کیا ہے۔ لیکن ابن حبان نے صحابہ رضی اللہ عنہم میں بھی ان کا تذکرہ کیا ہے۔ وفات: بقول امام بخاری رحمہ اللہ(4) تمام ابو عمرو سے پہلے ان کا انتقال ہو گیا۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۷۳) استیعاب (ت: ۲۴۶۱) تجرید (۸۲/۲)\n(2) ابو داؤد کتاب الصلاۃ باب السہو فی السجدتین (الحدیث: ۱۰۱۰) نسائی کتاب السہو باب ما یفعل من سلم من رکعتین (الحدیث: ۱۲۲۴) مسند احمد (الحدیث: ۴۰۱/۶) معجم الکبیر (الحدیث: ۴۳۱/۱۹) جامع المسانید (۵۳۲/۱۱)\n(3) مسند احمد (الحدیث: ۴۰۲/۴)\n(4) تاریخ کبیر (۳۲۸/۴)"}],[8046,"§۸۰۶۶ ۔ معاویہ بن حزن القشیری\nمیں نے خطیب کی تحریر کو پڑھا کتاب المؤتلف میں عقیل کے حالات میں لکھتے ہیں اور بڑی سند۔ عبدالرحمن بن محمد بن عقیل نیشاپوری۔ پھر اپنے طریقے سے حدیث بیان کی۔ ابوحامد حسنوی کہ وہ احمد بن یونس سے اور وہ عمر بن عبد اللہ سے اور وہ سفیان حسین سے اور وہ داؤد وراق سے اور وہ سعید بن حکیم سے اور وہ اپنے والد سے اور وہ ان کے دادا معاویہ بن حزن قشیری سے روایت نقل کرتے ہیں کہ انہوں نے فرمایا کہ میں جب نبی علیہ السلام کی خدمت میں حاضر ہو کر آپ کے پاس آکر کھڑا ہوا تو آپ نے ارشاد فرمایا کہ بہر حال میں نے اللہ سے یہ دعا مانگی ہے کہ وہ تمہارے خلاف میری مدد کرے، پھر لمبی حدیث ذکر کی۔\nمیرا خیال یہ ہے کہ یہ حیدہ کے بیٹے ہیں جن کا ذکر اس کے بعد آئے گا۔ خلاصہ کلام یہ کہ یہاں میں نے احتمال کے ساتھ لکھ دیا ہے لیکن آخری قسم میں میں نے خبر دار کیا ہے۔"],[8047,"§۸۰۶۷ ۔ معاویہ بن الحکم السلمی(1)\nبقول ابو عمر یہ قبیلہ بنو سلیم میں رہتے تھے۔ انہوں نے مدینہ کو اپنا مسکن بنایا تھا۔ بقول امام بخاری رحمہ اللہ(2) ان کو نبی علیہ السلام کی صحبت کا شرف حاصل ہوا اور یہ اہل حجاز میں شمار کیے جاتے ہیں۔ بقول امام بغوی: مدینہ کے رہائشی تھے اور نبی علیہ السلام سے حدیث بھی نقل کی ہے۔\nمیں کہتا ہوں: ان کا تذکرہ اور عطاء بن یسار کے طریق سے ان کی حدیث صحیح مسلم(3) میں موجود ہے۔ فرماتے ہیں کہ میں نے نبی علیہ السلام کے پیچھے نماز پڑھی تو ایک آدمی کو دورانِ نماز چھینک آئی تو میں نے کہہ دیا ((یرحمک اللہ))۔۔۔ الخ۔ اس حدیث میں یہ بھی الفاظ ہیں کہ بے شک یہ نماز ایسی عبادت ہے کہ اس میں لوگوں کی گفتگو اور بات چیت کی بالکل اجازت نہیں۔ امام بغوی رحمہ اللہ فرماتے ہیں کہ یہ ایک لمبی حدیث ہے جس میں نماز کے متعلق پیش آنے والے واقعات ہیں۔ امام زہری رحمہ اللہ نے ابو سلمہ بن عبد الرحمن سے اور انہوں نے معاویہ بن حکم سے فال نکالنے اور غیب کی خبریں بتانے کے بارے میں حدیث روایت کی۔ امام مالک رحمہ اللہ(4) نے عطاء بن یسار کے طریق سے اس باندی کا واقعہ ذکر کیا ہے جس کو انہوں نے تھپڑ مارا تھا۔ لیکن امام مالک رحمہ اللہ نے معاویہ بن حکم کے بجائے عمر بن حکم لکھا ہے۔ اکثر علماء نے اس کے بارے میں ان سے اختلاف کیا ہے کہ یہ معاویہ ہیں نہ کہ عمر۔ امام بغوی رحمہ اللہ نے یعقوب بن محمد زہری کے طریق سے اسد بن موسیٰ سے تخریج کیا ہے۔ وہ ضفار بن حمید سے اور وہ معاویہ بن حکم کے بیٹے کثیر سے نقل کرتے ہیں کہ ان کے والد معاویہ نے فرمایا کہ ہم نبی علیہ السلام کے ساتھ تھے تو میرے بھائی علی بن حکم نے جندف پر اپنا گھوڑا چڑھا دیا۔ پھر پوری حدیث بیان کی جو کہ ابن الحکم کے حالات میں میم کی تختی میں گزر چکی ہے۔\nابن عبدالبر(5) فرماتے ہیں: معاویہ بن حکم کی حدیث کو سب سے اچھے طریقے سے بیان کرنے والے یحیی بن ابی کثیر ہیں۔ ان کے علاوہ باقی سب نے ان کی احادیث کو ٹکڑے ٹکڑے کر دیا ہے۔ میں کہتا ہوں: لیکن ان کے بھائی علی کا واقعہ یحیی کی روایت میں داخل نہیں ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۷۴) استیعاب (ت: ۲۴۶۲) تجرید (۸۲/۲)\n(2) تاریخ کبیر (۳۲۸/۴)\n(3) مسلم کتاب المساجد باب تحریم الکلام فی الصلاۃ (الحدیث: ۱۱۹۹)\n(4) مؤطا امام مالک کتاب العتق والولاء باب ما یجوز من العتق (الحدیث: ۱۵۳۴)\n(5) استیعاب (۴۶۹/۳)"}],[8048,"§۸۰۶۸ ۔ معاویہ بن حیدہ(1)\nنسب: معاویہ بن حیدہ بن معاویہ بن قشیر بن کعب بن ربیعہ بن عامر بن صعصعہ قشیری۔ یہ بہز بن حکیم کے دادا ہیں۔ بقول امام بغوی انہوں نے بصرہ کو اپنا مسکن بنایا اور بقول ابن کلبی میرے والد نے مجھے بتایا کہ خراسان میں دیکھے گئے ہیں۔ اور وہیں ان کا انتقال ہوا۔ بقول ابن سعد(2) ان کا نبی علیہ السلام کے پاس آنا اور صحبت میں بیٹھنا دونوں ثابت ہیں۔ اور بقول امام بخاری رحمہ اللہ(3) انہوں نے نبی علیہ السلام کے ارشادات خود سنے ہیں جبکہ حاکم کا خیال یہ ہے کہ ان سے صرف ان کے بیٹے نے روایت لی ہے حالانکہ عروہ بن رویم نے بھی ان سے روایت بیان کی ہے، اور مزی فرماتے ہیں کہ حمید یزنی نے بھی ان سے روایت بیان کی ہے۔\nاور ان کا تذکرہ ان کے والد حیدہ کے حالات میں گزر چکا ہے اور امام بخاری رحمہ اللہ نے کتاب الطہارۃ اور کتاب النکاح میں ان کی روایت بطور تعلیق ذکر کی ہے اور کتاب الغسل میں یوں سند بیان کی ہے۔ بہز بن حکیم اپنے والد سے اور وہ ان کے دادا سے نقل کرتے ہیں اور اصحاب السنن(4) نے ان کی حدیث کی تخریج اور تصحیح فرمائی ہے۔\nامام بغوی رحمہ اللہ نے زبیر بن بکار کے حوالہ سے تخریج کیا ہے کہ عبدالمجید بن ابی رواد معمر سے اور وہ زہری سے نقل کرتے ہیں کہ بنو قشیر کے آدمی بہز بن حکیم اپنے والد سے اور وہ ان کے دادا سے نقل کرتے ہیں کہ نبی علیہ السلام نے ارشاد فرمایا: باہر چرنے والے ہر چالیس اونٹوں میں زکوۃ واجب ہے۔ بقول بغوی(5) صرف امام زہری نے یہ حدیث نقل کی ہے۔ میرا خیال ہے کہ یہ معمر کی روایت ہے، محمد بن حکیم سے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۷۵) استیعاب (ت: ۲۴۹۳) تجرید (۸۲/۲)\n(2) الطبقات (۳۵/۷)\n(3) تاریخ کبیر (۳۲۹/۴)\n(4) ابو داؤد کتاب النکاح باب فی حق المرأۃ علی زوجہا (الحدیث: ۲۱۴۲) ابن ماجہ کتاب النکاح باب حق المرأۃ علی زوجہا (الحدیث: ۱۸۵۰) مسند احمد (الحدیث: ۴۴۷/۴) مستدرک حاکم (الحدیث: ۱۸۷/۲) سنن کبریٰ (الحدیث: ۳۰۵/۷) صحیح ابن حبان کتاب النکاح باب معاشرۃ الزوجین (الحدیث: ۴۱۷۵) معجم الکبیر (الحدیث: ۱۰۳۵/۱۹)\n(5) تاریخ بغداد (۴۶۷/۸)"}],[8049,"§۸۰۶۹ ۔ معاویہ بن ابی ربیعہ الجرمی\nمحمد بن معلی ازدی نے کتاب الترخیص میں ان کا ذکر کیا ہے۔ پھر ابوبکر بن درید کی طرف اپنی سند کو منسوب کیا ہے جو کہ ابن کلبی تک پہنچتی ہے کہ ابوبشر جرمی اپنے شیوخ سے نقل کرتے ہیں کہ بنو عقیل، بنو جرم اور بنو جعدہ کی پانی کے بارے میں لڑائی ہوگئی، صلح نبی علیہ السلام کے پاس لایا گیا۔ آپ علیہ السلام نے بنو جرم کے حق میں فیصلہ فرمایا تو ان کے ایک شاعر معاویہ بن ابی ربیعہ نے یہ اشعار کہے:\n(۱) جیسا کہ تم جانتے ہو میں جرم قبیلے سے تعلق رکھتا ہوں، جب نبی علیہ السلام کے پاس تمام جماعتیں پہنچیں۔\n(۲) پس اگر تم نبی علیہ السلام کے فیصلے پر قناعت نہ کرو، بیشک میں تو آقا علیہ السلام کے فرمان پر قناعت کر چکا ہوں۔\nچند اشعار ہیں۔"],[8050,"§۸۰۷۰ ۔ معاویہ بن سفیان\nمعاویہ بن سفیان بن عبد الاسد مخزومی۔ یہ ابو سلمہ بن اسد کا بیٹا ہے، ان کا والد حالت کفر میں مارا گیا اور ان کے چچا نبی علیہ السلام کے ساتھ جنگ میں شہید ہوئے۔ اور رہا ان کا اپنا تذکرہ تو وہ زبیر بن بکار نے کیا ہے۔"],[8051,"§۸۰۷۱ ۔ معاویہ بن ابی سفیان(1)\nنسب: معاویہ بن ابی سفیان بن صحر بن حرب بن امیہ بن عبد شمس بن عبد مناف قرشی، اموی، امیر المومنین۔ حضور علیہ السلام کی بعثت سے پانچ یا سات یا تیرہ سال پہلے پیدا ہوئے۔ پہلا قول زیادہ مشہور ہے۔ امام واقدی رحمہ اللہ(2) نے نقل کیا ہے کہ یہ صلح حدیبیہ کے بعد مسلمان ہو گئے تھے لیکن انہوں نے اپنے اسلام لانے کو چھپائے رکھا، یہاں تک کہ فتح مکہ کے موقع پر اس کا برملا اظہار فرمایا۔ نیز یہ کہ یہ عمرۃ القضا کے موقع پر مسلمان تھے۔ یہ حدیث بخاری میں موجود حدیث کے مخالف ہے اس لیے کہ اس میں ہے کہ سعد بن ابی وقاص رضی اللہ عنہ نے حج کے مہینوں میں عمرہ کے بارے میں ارشاد فرمایا کہ ہاں ہم نے عمرہ کیا تھا اور معاویہ رضی اللہ عنہ اس وقت حالت کفر میں تھے۔ اگر پہلی حدیث کو بھی صحیح تسلیم کریں تو یہ ہو سکتا ہے کہ سیدنا سعد نے ان کی گزشتہ حالت پر حکم لگا دیا ہے اس لیے کہ ابھی تک ان کو یہ نہیں معلوم تھا کہ یہ اسلام لا چکے ہیں کیونکہ انہوں نے خود اسلام لانے کو چھپائے رکھا۔ امام احمد رحمہ اللہ نے محمد بن علی بن حسین کے طریق سے تخریج کیا کہ سیدنا ابن عباس رضی اللہ عنہما سے روایت ہے کہ سیدنا معاویہ رضی اللہ عنہ نے کہا کہ میں نے مروہ پہاڑی کے پاس نبی علیہ السلام کے بال مبارک کاٹے تھے۔ اصل حدیث بخاری میں ہے طاؤس کے طریق سے ابن عباس رضی اللہ عنہما سے روایت ہے ان الفاظ میں کہ قَصُّرْتُ بِمِشْقَصٍ۔ میں نے استرے سے بال کاٹے۔ یہاں مروہ پہاڑی کا بھی ذکر نہیں ہے۔ لیکن مروہ پہاڑی کے ذکر سے یہ بات معلوم ہوتی ہے کہ یہ واقعہ عمرے کا ہے اس لیے کہ حجۃ الوداع کے موقع پر تو آپ نے حلق کروایا تھا اور وہ بھی منی میں جیسا کہ بخاری و مسلم میں سیدنا انس رضی اللہ عنہ کی روایت موجود ہے۔ امام بغوی رحمہ اللہ نے محمد بن سلام کے طریق سے تخریج کیا ہے کہ ابان بن عثمان فرماتے ہیں کہ معاویہ رضی اللہ عنہ اپنی والدہ کے ساتھ ایک لڑکے سے تھے جب کبھی ان سے کوئی لغزش ہو جاتی تو ان کی والدہ کہتی: یہاں سے کھڑے ہو جاؤ، اللہ تمہیں بلندیاں نہ دے۔ تو قریب میں موجود ایک دیہاتی نے ان کی والدہ سے کہا: آپ ایسے کیوں کہہ رہی ہیں؟ حالانکہ میرا خیال یہ ہے کہ آپ کے اس بیٹے کو لوگ اپنا سردار بنائیں گے۔ تو اس نے جواب دیا کہ ہاں ہاں اور کوئی بلند مرتبہ نہیں ملے گا، صرف اپنی ہی قوم کا سردار بن جائے گا۔\nابونعیم فرماتے ہیں کہ سیدنا معاویہ رضی اللہ عنہ حساب و کتاب کے بڑے ماہر تھے اور فصیح اللسان تھے، بردبار اور باوقار آدمی تھے۔ خالد بن معدان کہتے ہیں کہ لمبے قد والے سفید گورا رنگ انتہائی نرم مزاج(3) حلیم آدمی تھے اور نبی علیہ السلام کی صحبت کا شرف بھی حاصل ہوا اور آپ کے کاتب بھی تھے۔ سیدنا عمر رضی اللہ عنہ نے ان کے بھائی یزید بن ابی سفیان کے بعد ان کو شام کا گورنر بنایا تھا۔ پھر سیدنا عثمان رضی اللہ عنہ نے بھی انہی کو گورنر باقی رکھا۔ سیدنا علی رضی اللہ عنہ کے دور تک یہ گورنر رہے لیکن پھر انہوں نے سیدنا علی رضی اللہ عنہ کے پر بیعت نہ کی بلکہ غلط فہمی کی بناء پر ان سے جنگ تک نوبت پہنچی تو انہوں نے ملک شام پر اپنی خود مختار حکومت قائم کی بلکہ مصر کو بھی کے ساتھ ملا لیا اور اس کو خلافت کا نام دے دیا گیا جب حکمین سے فیصلہ کرایا جا چکا۔ پھر یہ خود مختار امیر رہے یہاں تک کہ سیدنا کے ساتھ ان کی صلح ہوگئی اور تمام لوگ انہی کے ہاتھ بیعت کرنے پر متفق ہو گئے۔ اس سال کو عام الجماعۃ یعنی اکٹھے ہونے کا لقب قرار دیا گیا۔(4)\nامام بغوی مبارک بن فضالہ کے طریق سے تخریج کرتے ہیں کہ ان کے والد نے علی بن عبد اللہ سے اور انہوں نے عبد الملک بن مروان کا قول نقل کیا کہ ابن ہند یعنی سیدنا معاویہ بیس سال امیر رہے اور بیس سال خلیفہ رہے۔ محمد بن اسحاق نے تو اسی حدیث پر ان کر لیا لیکن حقیقت یہ ہے کہ اس حدیث میں کچھ وسعت سے کام لیا گیا ہے۔ کیونکہ سیدنا معاویہ رضی اللہ عنہ نے خلافت کے بیس سال مکمل نہیں کیے بلکہ اگر سیدنا علی رضی اللہ عنہ کی شہادت والا سال اور سیدنا حسن رضی اللہ عنہ سے صلح والا سال بھی شمار کیا جائے تو بھی انیس سال کچھ کم بنتے ہیں۔\nصحیح بخاری میں سیدنا عکرمہ کی روایت ہے، فرماتے ہیں کہ میں نے سیدنا ابن عباس رضی اللہ عنہما سے عرض کیا کہ سیدنا معاویہ کی ایک رکعت پڑھتے ہیں تو آپ نے فرمایا کہ وہ خود فقیہ ہیں اور ایک روایت میں ہے کہ وہ صحابی رسول ہیں (تم ان کے بارے کوئی بات نہ کرو)۔\nابن سعد(5) نے نقل کیا ہے کہ سیدنا معاویہ رضی اللہ عنہ خود فرمایا کرتے تھے کہ میں عمرۃ القضا سے پہلے مسلمان ہو چکا تھا لیکن اس بات سے ڈرتا تھا کہ مجھے مدینہ ہجرت کرنی پڑے گی اور میری والدہ نے کہہ رکھا تھا کہ اگر تو مدینہ گیا تو ہم تیرا خرچہ پانی بند کر دیں گے۔\nابن شاہین ابن ابی داؤد سے بسندہ سیدنا معاویہ تک یہ حدیث تخریج کرتے ہیں کہ بھلائی انسانی عادت ہے اور برائی ضد و چڑچڑا پن ہے۔ ہندہ نے کہا: صرف اپنی قوم کا؟ ناس ہو اس کا اگر یہ سارے عرب کا سردار نہ بنے۔ مدائنی کہتے ہیں کہ زید بن ثابت وحی لکھا کرتے تھے اور سیدنا معاویہ نبی علیہ السلام اور دیگر عرب کے مابین باقی معاملات لکھا کرتے تھے۔ مسند احمد میں اور اصل حدیث مسلم میں ابن عباس رضی اللہ عنہما سے روایت ہے کہ نبی علیہ السلام نے مجھے فرمایا کہ معاویہ کو میرے بلاؤ۔(6) اور یہ معاویہ حضور علیہ السلام کے کاتب تھے۔\nروایت: سیدنا معاویہ رضی اللہ عنہ نے مندرجہ ذیل صحابہ اور صحابیات سے روایت بیان کی ہے:(۱) ابو بکر صدیق(۲) سیدنا عمر(۳) سیدنا عثمان(۴) اپنی بہن ام المومنین ام حبیبہ بنت ابی سفیان رضی اللہ عنہا۔ اور خود ان سے روایت لینے والے مندرجہ ذیل صحابہ و تابعین ہیں:(۱) ابن عباس رضی اللہ عنہما(۲) جریر بجلی(۳) معاویہ بن حدیج(۴) سائب بن یزید(۵) عبداللہ بن زبیر(۶) نعمان بن بشیر وغیرہم رضی اللہ عنہم اجمعین کبار تابعین میں سے۔(۱) مروان بن حکم(۲) عبداللہ بن حارث بن نوفل(۳) قیس بن ابی حازم(۴) سعید بن مسیب(۵) ابو ادریس خولانی اور ان کے بعد کے(۶) عیسی بن طلحہ(۷) محمد بن جبیر بن مطعم(۸) حمید بن عبدالرحمن بن عوف(۹) ابو مجلز(۱۰) جبیر بن نفیر(۱۱) حمران مولی عثمان(۱۲) عبداللہ بن محیریز(۱۳) علقمہ بن وقاص(۱۴) عمیر بن ہانی(۱۵) ہمام بن منبہ(۱۶) ابو عریان نخعی(۱۷) مطرف بن عبداللہ بن شخیر اور ان کے علاوہ بھی کچھ دیگر حضرات ہیں جو ان سے روایت بیان کرتے ہیں۔\nابن ابی داؤد فرماتے ہیں کہ اس حدیث کو صرف سیدنا معاویہ نے ہی نبی علیہ السلام سے بیان کیا ہے۔ مسند ابی یعلی(7) میں ہے سوید بن شعبہ عمرو بن یحیی بن سعید سے نقل کرتے ہیں اور وہ اپنے دادا سعید سے (اور یہ سعید عمرو بن سعید بن عاص کے بیٹے ہیں) کہ سیدنا معاویہ نے فرمایا کہ میں نبی علیہ السلام کے پیچھے پیچھے وضو کر رہا تھا جب آپ نے وضو مکمل فرما لیا تو میری طرف دیکھ کر ارشاد فرمایا: اے معاویہ! اگر کوئی معاملہ (امارت و حکومت) تیرے سپرد کیا جائے تو اللہ سے ڈرتے رہنا اور انصاف سے کام لینا۔ فرماتے ہیں کہ بس اسی وقت سے مجھے یقین ہو گیا کہ مجھے کسی کام میں آزمایا اور مبتلا کیا جائے گا (اس حدیث کے راوی سوید کے بارے میں علماء نے کلام کیا ہے)۔\nامام بیہقی رحمہ اللہ نے بھی اسی حدیث کو اپنی کتاب دلائل میں دوسرے طریق سے تخریج کیا ہے۔ اور امام بخاری رحمہ اللہ کی کتاب(8) تاریخ کبیر میں معمر ہمام بن منبہ سے روایت کرتے ہیں کہ ابن عباس رضی اللہ عنہما نے ارشاد فرمایا کہ میں نے معاویہ سے زیادہ حکومت کا لائق و حقدار کوئی نہیں دیکھا۔ امام بغوی رحمہ اللہ فرماتے ہیں کہ میرے چچا نے زبیر سے روایت کرتے ہوئے ہمیں بتایا کہ محمد بن علی نے کہا کہ سیدنا عمر رضی اللہ عنہ جب بھی سیدنا معاویہ کو دیکھتے تو فرماتے کہ یہ عرب کا کسری ہے (یعنی اہل عرب میں سے کسری بادشاہ جیسی شان رکھتا ہے)۔ ابن سعد مدائنی سے نقل کرتے ہیں کہ انہوں نے فرمایا کہ ابوسفیان نے معاویہ کی طرف دیکھا جبکہ وہ لڑکے سے تھے تو کہنے لگے کہ میرا یہ بیٹا بڑا سردار ہوگا اور یہ اس لائق ہے کہ لوگ اس کو اپنا سردار بنائیں۔\nابن مبارک کتاب الزہد میں فرماتے ہیں: ابن ابی ذئب نے مسلم بن جندب سے روایت کرتے ہوئے ہمیں بتایا کہ سیدنا عمر رضی اللہ عنہ کے غلام اسلم نے کہا کہ سیدنا معاویہ رضی اللہ عنہ ہمارے پاس آئے اور سیدنا معاویہ انتہائی خوبصورت اور بھرے ہوئے ملائم جسامت والے تھے۔ تو یہ سیدنا عمر رضی اللہ عنہ کے ساتھ حج کرنے کے لیے نکلے۔ سیدنا عمر رضی اللہ عنہ جب بھی سیدنا معاویہ کی طرف دیکھتے تو ان کی خوبصورتی پر تعجب و حیرانگی کا اظہار فرماتے۔ پھر سیدنا عمر رضی اللہ عنہ اپنی انگلی ان کی پیشانی پر رکھتے جب اٹھاتے تو یوں محسوس ہوتا جیسے گھاس کی خوبصورت لائن بنی ہو۔ پھر خوش ہو کر فرماتے: واہ واہ! اس وقت ہم لوگوں میں سے سب سے بہتر ہیں کہ ہمارے لیے دنیا و آخرت کی بھلائیوں کو جمع کر دیا گیا ہے۔ پھر سیدنا معاویہ رضی اللہ عنہ نے فرمایا: اے امیر المومنین! میں آپ کو بتاتا ہوں کہ ہم حماموں والی اور سرسبز و شاداب زمین میں رہتے ہیں تو سیدنا عمر رضی اللہ عنہ نے فرمایا میں تجھے بتاتا ہوں تمہاری پسندیدہ چیزیں کیا ہیں۔ بہترین کھانا، دن چڑھے تک صبح کے وقت سونا اور حاجت مند لوگوں کا دروازے پر آنا۔ راوی کہتا ہے: جب ہم ایک کنویں کے پاس پہنچے تو سیدنا معاویہ رضی اللہ عنہ نے ایک بہترین جوڑا نکالا اور پہن لیا تو سیدنا عمر رضی اللہ عنہ نے بڑی عمدہ قسم کی خوشبو محسوس کی اور فرمایا کہ جو بھی حج کا ارادہ رکھتا ہے وہ پراگندہ حالت میں حج کرنے جائے۔ لیکن جب مکہ مکرمہ اللہ تعالیٰ کے محترم ترین شہر میں پہنچے تو انتہائی خوشبودار کپڑوں کو پہنے۔ تو سیدنا معاویہ رضی اللہ عنہ نے سیدنا عمر رضی اللہ عنہ سے کہا کہ میں نے تو اہل خانہ کے پاس جانے کے لیے یہ لباس زیب تن کیا ہے اور مجھے آپ کی طرف سے کوفت ہوئی ہے یہاں بھی اور شام میں بھی۔ اللہ جانتا ہے کہ میں نے سیدنا عمر رضی اللہ عنہ میں کتنی حیاء دیکھی ہے۔ پھر سیدنا معاویہ رضی اللہ عنہ نے وہ لباس اتار دیا اور وہ کپڑے پہن لیے جس میں انہوں نے احرام باندھنا تھا اور یہ بڑی مضبوط سند ہے۔\nابن سعد احمد بن محمد ازرقی سے تخریج کرتے ہیں کہ عمر بن یحیی بن سعید اپنے دادا سے نقل کرتے ہیں کہ سیدنا معاویہ رضی اللہ عنہ سیدنا عمر رضی اللہ عنہ کے پاس آئے، انہوں نے ایک سبز رنگ کا جبہ زیب تن کیا ہوا تھا۔ تمام صحابہ رضی اللہ عنہم نے دیکھا، لیکن جب سیدنا عمر رضی اللہ عنہ کی نظر پڑی تو اپنا درہ (کوڑا) لے کر کھڑے ہو گئے اور سیدنا معاویہ رضی اللہ عنہ کو مارنے لگے اور سیدنا معاویہ رضی اللہ عنہ بار بار کہہ رہے تھے: اللہ سے ڈریے اے امیر المومنین! میرا کیا قصور ہے؟ کیوں مجھے مار رہے ہیں؟ سیدنا عمر رضی اللہ عنہ نے کوئی جواب نہیں دیا، بلکہ اپنی جگہ جا کر بیٹھ گئے۔ دیگر صحابہ رضی اللہ عنہم نے پوچھا آپ نے اس نوجوان کو کیوں مارا، حالانکہ اس جیسا لوگوں میں اور کوئی نہیں؟ تو ارشاد فرمایا کہ میں نے اس میں کوئی برائی نہیں دیکھی اور نہ مجھے کسی نے اس کے متعلق کوئی ایسی بات کی ہے، مجھے تو اس میں تکبر کا خدشہ ہوا جسے میں ختم کرنا چاہتا تھا۔\nابن ابی الدنیا فرماتے ہیں: محمد بن عباد نے ہمیں بتایا کہ سفیان اپنے شیخ سے نقل کرتے ہیں کہ سیدنا عمر رضی اللہ عنہ نے فرمایا: میرے بعد تفرقہ بازی سے بچتے رہنا اگر تم نے تفرقہ بازی کی تو خوب اچھی طرح سمجھ لو کہ معاویہ شام کے امیر ہوں گے لہذا جب تمہیں تمہاری مرضی پر چھوڑ دیا جائے گا تو وہ کیسے اس کو تم سے زبردستی جدا کر سکے گا۔\nوفات: سیدنا معاویہ رضی اللہ عنہ کی وفات رجب ۶۰ھ میں ہوئی، صحیح قول یہ ہی ہے۔(9)","",{"fn":"(1) اسد الغابہ (ت: ۴۹۷۷) استیعاب (ت: ۲۴۶۴)\n(2) مختصر تاریخ دمشق (۴۰۲/۲۴)\n(3) معجم الکبیر (الحدیث: ۳۰۵/۱۹) مجمع الزوائد (الحدیث: ۳۵۵/۹) مختصر تاریخ دمشق (۴۰۲/۲۴)\n(4) اسد الغابہ (۱۵۶/۴)\n(5) طبقات کبریٰ (۱۶۳/۳)\n(6) مسلم کتاب البر والصلۃ باب من لعنہ النبی صلی اللہ علیہ وسلم او سبہ او دعا علیہ (الحدیث: ۹۶) دلائل النبوۃ للبیہقی (۲۴۳/۶)\n(7) مسند ابویعلی (الحدیث: ۷۳۸۰/۱۳)\n(8) تاریخ کبیر (۳۲۶/۴)\n(9) معجم الکبیر (الحدیث: ۳۰۵/۱۹) مصنف ابن ابی شیبہ (الحدیث: ۷۱/۱۳) آحاد والمثانی (الحدیث: ۳۷۳)"}],[8052,"§۸۰۷۲ ۔ معاویہ بن سوید(1)\nمعاویہ بن سوید بن مقرن مُزنی کنیت ابوسوید کوفی۔ ان کے والد کا تذکرہ سین کی تختی میں گزر چکا ہے اور کچھ تذکرہ نعمان بن مقرن کے حالات میں آئے گا۔ یہ مشہور تابعی ہیں اور اپنے والد کے علاوہ براء بن عازب سے بھی ان کی روایت صحیح مسلم(2) وغیرہ میں موجود ہے۔\nابو یعلی، حسن بن سفیان اور امام بغوی نے ان کا تذکرہ کیا ہے جبکہ ابن السکن نے ان کو صحابہ رضی اللہ عنہم میں شمار کیا ہے۔ اور ان سب حضرات نے ابوزبید کے طریق سے مطرف سے روایت کیا کہ امام شعبی معاویہ سے روایت کرتے ہیں کہ انہوں نے فرمایا کہ نبی علیہ السلام کا ارشاد ہے: جب کوئی بندہ اپنے بھائی کو کافر کہتا ہے تو یہ کفر ان دونوں میں سے کسی ایک کی طرف ضرور منسوب ہوتا ہے۔(3) امام بغوی رحمہ اللہ نے مطرف کے طریق سے ابوسفر سے تخریج کیا ہے کہ معاویہ بن سوید نے فرمایا کہ ہمارا یعنی بنو مقرن کا ایک غلام تھا تو کسی نے اس کے منہ پر طمانچہ مارا تو اس نے نبی علیہ السلام سے شکایت کی تو آپ علیہ السلام نے اس کو آزاد فرما دیا۔ پھر کسی نے نبی علیہ السلام سے عرض کیا کہ اس کے علاوہ ان کا اور کوئی خادم نہیں ہے تو آپ علیہ السلام نے ارشاد فرمایا کہ ہاں! یہ ان کی خدمت میں رہے جب تک کہ یہ لوگ اپنا اور کوئی انتظام نہیں کر لیتے۔(4) اسی طرح امام نسائی رحمہ اللہ نے اسی طریق سے اس کو تخریج کیا ہے۔ امام مسلم رحمہ اللہ نے بھی اس حدیث کی تخریج کی ہے۔ اور اصحاب سنن ہلال بن یساف اور سلمہ بن کہیل وغیرہ کی روایت سے بیان کرتے ہیں کہ معاویہ بن سوید اپنے والد سے روایت کرتے ہیں کہ ہم بنو مقرن۔۔۔۔ پھر پورا واقعہ بیان کیا۔ گویا مذکورہ حدیث میں بعض راویوں سے کچھ کوتاہی ہوئی ہے۔ امام نسائی رحمہ اللہ نے بھی اس حدیث کی تخریج فرمائی ہے اور اختلاف کو فقط ذکر کر دیا ہے۔ اس پر کوئی تنبیہ نہیں فرمائی جیسے کہ ان کی عادت ہے۔ اور اختلاف مطرف اور معاویہ بن سوید کے درمیان واسطہ ہے یا نہیں تو فرمایا جو ابوسفر کے واسطہ کے قائل ہیں یہ زیادہ درست لگتا ہے۔\nابن ابوحاتم رازی نے فرمایا کہ ان کی حدیث مرسل ہے۔ اور بقول احمد عسکری ان کے نبی علیہ السلام سے خود حدیث سننے کے بارے میں اکثر حضرات صحت کے قائل نہیں ہیں اور ان کی روایت مرسل ہے۔\nابن حبان نے ان کا تذکرہ فرمایا جبکہ عجلی نے ان کو معتمد اور ثقہ تابعین میں شمار کیا ہے اور ان سے روایت لینے والے سلمہ بن کہیل، عمرو بن مرہ اور اشعث بن ابی الشعثاء وغیرہ ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۷۶) تجرید (۸۳/۲)\n(2) مسلم کتاب الایمان باب بیان حال الایمان من قال لاخیہ المسلم یا کافر (الحدیث: ۲۱۲)\n(3) بخاری کتاب الادب باب من اکفر اخاہ (الحدیث: ۶۱۰۳) مسند احمد (الحدیث: ۱۰۵/۲) معجم الکبیر (الحدیث: ۱۹۴/۱۸) جامع المسانید (۵۶۱/۱۱)\n(4) مسلم کتاب الایمان باب صحبۃ الممالیک (الحدیث: ۱۲۳) ابوداؤد فی کتاب الادب باب من حق المملوک (الحدیث: ۵۱۶۷) مسند احمد (الحدیث: ۴۴۴/۵)"}],[8053,"§۸۰۷۳ ۔ معاویہ بن صعصعہ تیمی(1)\nبنو تمیم کے اس وفد میں سے ہیں جنہوں نے نبی علیہ السلام کو حجرے کے باہر سے پکارا تھا۔ ابو عمر ان کا تذکرہ کرتے ہوئے فرماتے ہیں: مجھے ان کی کوئی روایت نہیں ملی اور مشہور یہ ہے کہ یہ صعصعہ بن مقرن ہیں۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (ت: ۴۹۷۸) استیعاب (ت: ۲۴۶۵) تجرید (۸۳/۲)"}],[8054,"§۸۰۷۴ ۔ معاویہ بن عبادہ(1)\nبن عقیل۔ یہ کعب بن اخیل بن رحال کے والد ہیں۔ نبی علیہ السلام کے پاس آنا ثابت ہے۔","",{"fn":"(1) تجرید (۸۳/۲)"}],[8055,"§۸۰۷۵ ۔ معاویہ بن عبداللہ(1)\nامام بغوی و اسماعیلی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کرتے ہوئے جعفر بن ربیعہ کے طریق سے اعرج سے تخریج کیا ہے کہ معاویہ بن عبد اللہ نے ان کو بتایا کہ نبی علیہ السلام نے مغرب کی نماز میں سورہ دخان کی تلاوت فرمائی۔(2) ابن فتحون نے اپنی مستدرک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۸۰) تجرید (۸۳/۲)\n(2) جامع المسانید (۶۶۳/۱۱)"}],[8056,"§۸۰۷۶ ۔ معاویہ بن عروہ الدئلی\nیہ نوفل کے والد ہیں، معاویہ نامی شخصیات کے آخر میں ان کا تذکرہ آنے والا ہے۔"],[8057,"§۸۰۷۷ ۔ معاویہ بن عفیف المزنی\nابن عساکر نے اپنی کتاب تاریخ میں ان کا ذکر کیا ہے اور ابوالحسن رازی جو کہ تمام کے والد ہیں، ان کے واسطہ سے روایت لاتے ہیں کہ بعض لوگوں کا کہنا ہے کہ دجاجیہ نامی جگہ میں جنگ سقیفہ کے موقع پر جو گھر تھا وہ ابو قحافہ اور معاویہ کے گھر کا ایک حصہ تھا اور یہ دونوں عفیف مزنی کے بیٹے ہیں اور ان کو نبی علیہ السلام کی صحبت کا شرف بھی حاصل ہوا۔"],[8058,"§۸۰۷۸ ۔ معاویہ بن عمرو\nیہ ذوالکلاع کے بھائی ہیں۔ بقول رشاطی: یہ سکون نامی جگہ میں رہتے تھے پھر مدینہ ہجرت کر گئے اور وہاں دین کا علم حاصل کر کے اپنی قوم کے پاس واپس چلے گئے۔\nوثیمہ نے مرتدین کے خلاف ہونے والی جنگوں میں ذکر کیا ہے کہ یہ معاویہ کندہ کے بادشاہوں کی طرف جہاد کے لیے کھڑے ہوئے جبکہ وہ مرتد ہو رہے تھے اور انہوں نے زیاد بن لبید سے زکوۃ کی اونٹنی چھین لی تھی تو سیدنا معاویہ بن عمرو نے کہا کہ اے کندہ کے لوگو! اگر چہ میں غلطی میں تمہارے ساتھ شریک نہیں ہوں لیکن مصیبت میں مجھے بہر حال تمہارے ساتھ شریک ہونا پڑے گا، لہذا تم زیاد کو واپس بلاؤ اور اپنا کام کرنے دو اور سیدنا ابوبکر صدیق رضی اللہ عنہ کو اپنی طرف سے معذرت نامہ بھی لکھ کر بھیجو۔ ورنہ اس ردت پر اللہ کی قسم بہت سارے خون بہا دیئے جائیں گے لیکن انہوں نے سیدنا معاویہ رضی اللہ عنہ کی ایک نہ مانی تو یہ ان سے ناراض ہو کر واپس چلے گئے اور اس بارے میں بڑے خوبصورت اشعار کہے۔ ابن فتحون نے اپنی مستدرک میں ان کا ذکر کیا ہے۔"],[8059,"§۸۰۷۹ ۔ معاویہ بن عمرو الدئلی\nبعض نے کہا: یہ معاویہ بن عروہ ہیں، اس پر کچھ تنبیہ پیچھے گزر چکی ہے۔"],[8060,"§۸۰۸۰ ۔ معاویہ بن قرمل محاربی(1)\nان کے والد کا نام یا تو فَرْمَلُ تھا یا قُرْمُل۔ بقول ابو عمر(2) صحابہ رضی اللہ عنہم میں ان کا بھی تذکرہ ہے اور بقول ابن سکن اور ابن مندہ ان کو نبی علیہ السلام کی صحبت بھی حاصل ہوئی اور یعلی بن حارث نے فرمایا کہ میں نے مورع بن حبان محاربی سے سنا کہ معاویہ بن قرمل محاربی نے فرمایا کہ میں ملک شام کی جنگ میں خالد بن ولید رضی اللہ عنہ کے ساتھ تھا، تو ہمارے سامنے ایک کنیسہ (راہب خانہ) کا تذکرہ کیا گیا تو ہم نے اس کے پاس آکر السلام علیکم کہا۔ اتنے میں اندر سے ایک راہب نکلا، اس نے پوچھا یہ بہترین بات کہنے والے کون ہیں؟۔۔۔ الخ۔ معاویہ بن قرمل کے ساتھیوں کا خیال یہ ہے کہ ان کو نبی علیہ السلام کی صحبت کا شرف حاصل ہوا۔\nبقول ابن السکن ابوالعلاء معاویہ بن قرمل کے بارے میں کہتے ہیں کہ انہوں نے فرمایا: میں سیدنا عمر رضی اللہ عنہ کے دور خلافت میں مدینہ آیا۔ ابن السکن کہتے ہیں: اب مجھے نہیں معلوم کہ یہ وہی ہیں یا کوئی اور۔\nمیں کہتا ہوں: امام بخاری اور ابن حبان رحمہما اللہ وغیرہ نے ان کا تذکرہ تابعین میں کیا ہے اور سب نے یہی کہا کہ ان کے والد کا نام حرمل حا کے ساتھ ہے، جبکہ یہاں قرمل قاف کے ساتھ ذکر کیا ہے اور عنقریب تیسری قسم میں ذکر آئے گا کہ وہ حنفی تھے اور یہ محاربی ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۸۲) استیعاب (ت: ۲۴۶۶) تجرید (۸۳/۲)\n(2) استیعاب (۴۷۵/۳)"}],[8061,"§۸۰۸۱ ۔ معاویہ بن مُحَصَّن(1)\nبن علس کندی کنیت: ابوشجرہ۔ بقول ابن کلبی ان کو بھی نبی علیہ السلام کی صحبت کا شرف حاصل ہوا۔ ابن اثیر(2) نے اپنی مستدرک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۸۴) تجرید (۸۳/۲)\n(2) اسد الغابہ (ت: ۱۵۸/۴)"}],[8062,"§۸۰۸۲ ۔ معاویہ بن مرداس\nنسب: معاویہ بن مرداس بن ابی عامر بن سنان بن حارثہ بن عبس بن رفاعہ بن حارث بن بہثہ بن سلیم سلمی۔ ابن کلبی وغیرہ نے ان کا تذکرہ کیا ہے۔ ابوبکر بن درید اخبار منثورہ میں ابن کلبی سے ذکر کرتے ہیں کہ ابو مسکین نے کہا کہ درید بن صمہ جشمی عمرو بن حارث بن شرید کے پاس آیا تو اس کی نظر ان کی بہن خنساء پر پڑ گئی جس کا نام تماضر تھا اس نے اپنے اونٹ کو تارکول ملا اور پھر کپڑے اتار کر نہانے لگی اور درید اس کی طرف دیکھ رہا تھا تو اس کو ان کی کوئی چیز اچھی لگی۔۔۔۔ پھر واقعہ ذکر کیا اور ان کو نکاح کا پیغام بھیجا لیکن انہوں نے انکار کر دیا۔ پھر عبداللہ بن رواحہ بن عصیہ سلمی سے ان کی شادی ہوئی اور ابو شجرہ پیدا ہوئے۔ پھر مرداس بن ابی عامر سے ان کی شادی ہوئی جس سے معاویہ، یزید، حرب اور عمیرہ پیدا ہوئے۔ پھر معاویہ سیدنا عمر رضی اللہ عنہ کے زمانہ میں وفات پاگئے تو سیدنا عمر رضی اللہ عنہ نے فرمایا: مرداس کا سردار بیٹا فوت ہو گیا، اللہ کی قسم! اگر وہ زندہ رہتا تو میں اس کا ضرور اکرام کرتا۔ محدثین کا کہنا ہے کہ یہ خنساء رضی اللہ عنہا صحابیہ ہیں اور جنگ قادسیہ میں اپنے چار بیٹوں سمیت شریک ہوئیں اور سب بیٹے شہید ہو گئے اور یہ ان کے بعد رہ گئیں۔"],[8063,"§۸۰۸۳ ۔ معاویہ بن معاویہ المزنی(1)\nامام بغوی رحمہ اللہ نے ان کا تذکرہ کیا ہے۔ محدثین کی ایک کثیر جماعت نے ان کے تذکرہ میں فرمایا کہ یہ نبی علیہ السلام کے زمانہ میں ہی وفات پا گئے تھے۔ ابو امامہ اور انس کی حدیث میں مسند اور سعید بن مسیب اور حسن بصری کے طریق سے مرسلاً ان کا واقعہ آیا ہے۔ امام طبرانی(2) اور محمد بن ایوب بن ضریس نے فضائل قرآن میں اور سمویہ نے فوائد قرآن میں جبکہ ابن مندہ اور بیہقی نے دلائل میں اس کی تخریج کی ہے۔ یہ سب حضرات محبوب بن ہلال کے طریق سے عطاء بن ابی میمونہ سے روایت کرتے ہیں کہ سیدنا انس بن مالک رضی اللہ عنہ نے ارشاد فرمایا کہ حضرت جبرائیل علیہ السلام نبی علیہ السلام کی خدمت میں آئے اور کہنے لگے: اے محمد (صلی اللہ علیہ وسلم)! معاویہ بن معاویہ مزنی کا انتقال ہو گیا، آپ ان کی نماز جنازہ پڑھنا چاہتے ہیں تو آپ علیہ السلام نے ارشاد فرمایا: ’ہاں!‘ حضرت جبرائیل علیہ السلام نے اپنے دونوں پر زمین پر مارے جس کی وجہ سے تمام پردے اور درخت درمیان سے ہٹ گئے۔ پھر سیدنا معاویہ رضی اللہ عنہ کی چار پائی کو اتنا قریب لایا گیا کہ آپ علیہ السلام نے ان کو دیکھ لیا اور ان پر نماز جنازہ پڑھی جبکہ آپ کے پیچھے فرشتوں کی دو صفیں تھیں۔(3) اور ہر ایک صف میں ستر ہزار فرشتے تھے۔ جنازہ کے بعد نبی علیہ السلام نے حضرت جبرائیل علیہ السلام سے پوچھا کہ معاویہ کو اتنا مقام کیوں اور کیسے ملا؟ تو انہوں نے جواب دیا کہ سورہ اخلاص (قُلْ هُوَ اللَّهُ أَحَدٌ) سے محبت کی وجہ سے کہ یہ اس کو ہر وقت اور ہر حالت میں (گھٹنوں کے بل) آتے جاتے، کھڑے بیٹھے غرضیکہ ہر وقت اس کی تلاوت کرتے تھے۔ ابن ضریس کی حدیث کے شروع میں ہے کہ نبی علیہ السلام اور محبوب بن ہلال اس وقت شام میں تھے۔ ابوحاتم کہتے ہیں کہ یہ بات مشہور نہیں۔\nابن حبان نے با اعتماد لوگوں میں ان کا ذکر کیا ہے۔ ابن سنجر نے اپنی مسند میں اسی طرح ابن الاعرابی، ابن عبدالبر(4) نے اس کی تخریج کی ہے اور ہم نے بھی اس کو حاجب طوسی کے فوائد میں عالی سند کے ساتھ ذکر کیا ہے یہ سب تخریجات یزید بن ہارون کے طریق سے ہیں۔ وہ فرماتے ہیں: علامہ ابو محمد ثقفی نے ہمیں بتایا کہ میں نے انس بن مالک رضی اللہ عنہ کو یہ فرماتے ہوئے سنا کہ ہم نبی علیہ السلام کے ساتھ غزوہ تبوک میں تھے کہ ایک دن سورج اپنی خلاف عادت انتہائی روشن، چمکدار کرنوں کے ساتھ طلوع ہوا۔ ایسا ہم نے پہلے کبھی نہیں دیکھا تھا۔ تو نبی علیہ السلام بھی حیران ہوئے کہ آج کیا ماجرا ہے؟ تو اچانک جبرائیل علیہ السلام تشریف لائے اور فرمایا کہ معاویہ بن معاویہ لیثی کا انتقال ہو گیا ہے اور اللہ تعالیٰ نے ستر ہزار فرشتوں کو ان کا نماز جنازہ پڑھنے کے لیے بھیجا ہے۔ تو نبی علیہ السلام نے پوچھا کہ اس کی کیا وجہ ہے؟(5) تو جبرائیل علیہ السلام نے بتایا کہ اس لیے کہ وہ قل ھو اللہ احد کی کثرت سے تلاوت کیا کرتے تھے۔ پھر پہلے جیسی حدیث نقل کی اور اس میں یہ بھی ہے کہ کیا آپ ان کی نماز جنازہ پڑھنا چاہتے ہیں تا کہ میں آپ کے لیے زمین کو سمیٹ دوں؟ تو فرمایا: ”ہاں!“ تو پھر آپ علیہ السلام نے ان پر نماز جنازہ پڑھی۔ اور علاء ابو محمد یہ یزید ثقفی کے بیٹے ہیں اور یہ کمزور راوی ہیں۔ لیثی کے قول میں ان سے غلطی سرزد ہوگئی۔\nیہ حدیث ایک تیسرے طریق سے بھی مروی ہے جو کہ سیدنا انس رضی اللہ عنہ سے ابن مندہ نے ابو عتاب کی روایت سے دلائل میں ذکر کیا ہے کہ یحیی بن ابی محمد نے ان سے روایت کیا ہے اور نوح بن عمرو نے باقیوں سے روایت کیا ہے اور انہوں نے محمد بن زیاد سے اور وہ ابو امامہ سے اسی طرح روایت کرتے ہیں۔\nمیں کہتا ہوں: ابو احمد حاکم نے اپنے فوائد میں، طبرانی نے سورۃ اخلاص کے فضائل میں اور ابن عبدالبر نے ان تمام نوح کے طریق سے تخریج کیا۔ اور اس حدیث کا مفہوم ذکر کیا ہے اور اس میں یہ بھی ہے: جبرئیل علیہ السلام نے اپنا دایاں پر پہاڑوں پر رکھا جس سے وہ نیچے ہو گئے یہاں تک کہ ہم نے مدینہ دیکھا۔ ابن حبان نے علاء ثقفی کے حالات میں لکھا ہے کہ یہ ضعیف راوی ہیں۔ حالانکہ وہ پہلے ان کی اس حدیث کو لکھ چکے تھے کہ ان کو اہل شام کے ایک شیخ نے چرایا۔ پھر اس کو باقیوں سے روایت کیا اور پھر اس کو ذکر کیا۔\nمیں کہتا ہوں: مجھے نہیں پتا چلا کہ ان کی مراد نوح ہیں یا کوئی اور اس لیے کہ نوح کو تو ضعیف راویوں میں ذکر نہیں کیا گیا۔ اور باقی رہا سعید بن مسیب والا طریق جو کہ مرسل ہے تو اس کو ہم نے قرآن کے فضائل میں ذکر کیا ہے جو کہ ابن ضریس سے مروی ہیں کہ علی بن زید بن جدعان ان سے روایت کرتے ہیں۔\nباقی رہا حسن بصری کا طریق تو اس کو امام بغوی اور ابن مندہ نے صدقہ بن ابی سہل کے طریق سے تخریج کیا کہ یونس بن عبید سے انہوں نے حسن بصری سے اور انہوں نے معاویہ بن معاویہ مزنی کے بارے میں کہ نبی علیہ السلام جنگ تبوک میں تھے کہ جبرائیل علیہ السلام آئے اور عرض کیا کیا آپ معاویہ بن معاویہ مزنی کا جنازہ پڑھنا چاہتے ہیں۔۔۔۔ پوری حدیث۔\nابن عبدالبر کہتے ہیں کہ اس حدیث کی سندیں مضبوط و قوی نہیں اور احکام میں تو اس کو بطور دلیل پیش کیا ہی نہیں جاسکتا۔ اور فرمایا کہ معاویہ بن مقرن مزنی تو مشہور ہیں خود بھی اور ان کے بھائی بھی لیکن معاویہ بن معاویہ کون ہیں مجھے کچھ معلوم نہیں۔\nمیں کہتا ہوں: غائبانہ نماز جنازہ کے قائلین اس حدیث کو دلیل بناتے ہیں، ان کا رد خود اس حدیث میں موجود ہے کہ یہ غائبانہ نہیں بلکہ حاضرانہ تھا کیونکہ تمام پردے ہٹا دیئے گئے تھے۔ اس کا تعلق احکام سے ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (ت: ۴۹۸۵) استیعاب (ت: ۲۴۶۷) تجرید (۸۲/۲)\n(2) معجم الکبیر (الحدیث: ۱۰۴۰/۱۹)\n(3) سنن کبریٰ (الحدیث: ۵۱/۴) مجمع الزوائد (الحدیث: ۳۸/۳) مسند ابویعلی (الحدیث: ۱۹۷/۲) و (الحدیث: ۲۵۸/۷)\n(4) استیعاب (۴۷۶/۳)\n(5) معجم الکبیر (الحدیث: ۴۲۹/۱۹) مجمع الزوائد (الحدیث: ۳۸/۳)"}],[8064,"§۸۰۸۴ ۔ معاویہ بن مغیرہ\nبن ابوالعاص بن امیہ اموی۔ مروان بن حکم کے چچا زاد بھائی ہیں۔ اور یہ عبد الملک بن مروان کے نانا ہیں۔ اور ان کی والدہ بسرہ بنت صفوان مشہور صحابیہ ہیں ان کے والد زمانہ جاہلیت میں فوت ہو گئے تھے۔ ابن فتحون نے اپنی مستدرک میں ان کا ذکر کیا۔"],[8065,"§۸۰۸۵ ۔ معاویہ بن مقرن المزنی(1)\nابن عبدالبر کا قول معاویہ بن معاویہ کے حالات میں ابھی گزرا ہے۔ ابن شاہین ان کا تذکرہ کرتے ہوئے ایک حدیث لائے جس کے شروع میں یہ ہے کہ نبی علیہ السلام نے ایک لشکر بھیجا اور ان کے امیر کو وصیت فرمائی۔۔۔۔ الخ۔ ابن فتحون نے اپنی مستدرک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۸۴/۲)"}],[8066,"§۸۰۸۶ ۔ معاویہ بن نفیع(1)\nابن مندہ ان کے تذکرہ میں فرماتے ہیں کہ محمد بن جابر نے ان کی حدیث کو روایت کیا ہے اشعث بن ابی الشعثاء سے اور انہوں نے صلت بکری سے اور انہوں نے معاویہ بن نفیح سے۔ اور ان کو نبی علیہ السلام کی صحبت کا شرف حاصل ہوا۔ فرماتے ہیں کہ ہم نبی علیہ السلام کے پاس ایک بڑی جماعت کی شکل میں عید والے دن حاضر ہوئے، آپ علیہ السلام نے ہمیں نماز پڑھائی۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۸۶) تجرید (۸۴/۲)"}],[8067,"§۸۰۸۷ ۔ معاویہ الثقفی\nقبیلہ ثقیف کے اتحادیوں میں سے ہیں اور امام طبرانی رحمہ اللہ نے ان کے تذکرہ میں لکھا ہے کہ یہ بنو عقیل کے سربراہ تھے جبکہ انہوں نے سیدنا ابو بکر صدیق رضی اللہ عنہ کے زمانہ میں فیروز دیلمی کی مدد کی تھی اس لیے کہ مرتدین نے ان کے اہل و عیال کو چھین لیا تھا تو ان کو چھڑانے کے لیے یہ سب نکلے۔ سیف نے بھی ان کا تذکرہ کیا ہے اور فرمایا کہ انہوں نے ہی ان کے اہل و عیال کو اسود عنسی کے قتل سے پہلے قیس بن عبد یغوث سے چھڑایا تھا۔ ان کی نسبت عقیلی بھی ہے تو گویا کہ یہ بنو عقیل کے ثقیف یعنی ذہین و سمجھ دار آدمی ہیں۔\nاور پہلے یہ بات گزر چکی ہے کہ قریش و ثقیف کے جو لوگ سیدنا ابو بکر صدیق رضی اللہ عنہ کے دور خلافت یا اس کے قریب قریب کی جنگوں میں شریک رہے وہ صحابہ رضی اللہ عنہم میں شمار ہوتے ہیں کیونکہ یہ سب لوگ حجۃ الوداع کے موقع پر حاضر تھے۔"],[8068,"§۸۰۸۸ ۔ معاویہ العذری\nسیف نے کتاب الردۃ میں ذکر کیا کہ سیدنا ابو بکر صدیق رضی اللہ عنہ نے ان کو بذریعہ خط حکم دیا کہ مرتدین کے قتال کے بارے میں سنجیدہ رہیں۔ اور پہلے ہم کئی بار ذکر کر چکے ہیں کہ اس زمانہ میں صرف صحابہ رضی اللہ عنہم کو ہی امارت سپرد کی جاتی تھی۔"],[8069,"§۸۰۸۹ ۔ معاویہ اللیثی(1)\nامام بخاری رحمہ اللہ وغیرہ نے صحابہ میں ان کا ذکر کیا ہے۔ ابن مندہ کا کہنا ہے کہ بصرہ کے رہنے والوں میں ان کا شمار ہوتا ہے۔ امام بخاری، ابن ابی خیثمہ، امام بغوی، اور طبرانی وغیرہ عمران بن قطان کے طریق سے تخریج کیا ہے کہ قتادہ نصر بن عاصم سے نقل کرتے ہیں کہ معاویہ لیثی نے کہا کہ نبی علیہ السلام کا ارشاد ہے کہ لوگ قحط سالی اور خشک سالی میں مبتلاء ہوتے ہیں۔ پھر اللہ تعالیٰ ان کو اپنی طرف سے رزق عطا فرما دیتے ہیں لیکن پھر یہ لوگ شرک کرنے لگ جاتے ہیں کہ ہمیں تو یہ بارش فلاں کے فضل و عطیہ و بخشش سے ملی ہے۔ طیالسی نے اپنی مسند میں انہی سے تخریج کی ہے۔\nابو عمر کا کہنا ہے کہ اس کی سند میں لوگوں کا اضطراب و اختلاف ہے اور امام بخاری رحمہ اللہ نے معاویہ بن حیدہ اور معاویہ لیثی کو ایک ہی شخص قرار دیا ہے، جبکہ ابو حاکم نے ان کی تردید کی ہے۔\nمیں کہتا ہوں: امام بخاری رحمہ اللہ کی کتاب تاریخ کے نسخے تو مختلف ہیں لیکن مجھے تو ایسا کوئی اختلاف نہیں ملا جیسا کہ ابو عمر نے دعوی کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۸۳) استیعاب (ت: ۲۴۶۸) تجرید (۸۳/۲)"}],[8070,"§۸۰۹۰ ۔ معاویہ الہذلی(1)\nامام بخاری رحمہ اللہ(2) نے صحابہ رضی اللہ عنہم میں ان کا تذکرہ کیا ہے اور بقول ابن مندہ یہ حمص کے رہنے والوں میں سے ہیں۔ امام بغوی اور جعفر فریابی نے کتاب صفۃ المنافق میں اور ابن مندہ نے حریز بن عثمان کے طریق سے تخریج کیا ہے کہ سلیم بن عامر معاویہ ہذلی صحابی رسول سے روایت کرتے ہیں کہ انہوں نے فرمایا کہ بیشک منافق روزہ رکھتا ہے لیکن اللہ تعالیٰ اس کو تسلیم نہیں کرتے بلکہ اس کو جھٹلا دیتے ہیں اور وہ نماز پڑھتا ہے لیکن اللہ تعالیٰ اس کو جھٹلا دیتے ہیں۔ اسی طرح وہ صدقہ دیتا ہے اللہ تعالیٰ اس کو بھی جھٹلا دیتے ہیں وہ تہجد پڑھتا ہے اس کو بھی اللہ تعالیٰ جھٹلا دیتے ہیں۔ پھر وہ جہاد میں شریک ہوتا ہے لیکن اللہ تعالیٰ اس کو بھی جھٹلا دیتے ہیں، یہاں تک کہ وہ لڑتے لڑتے قتل ہو جاتا ہے اللہ تعالیٰ اس کو جہنم میں ڈال دیتے ہیں۔(3)\nیزید بن ہارون کے طریق سے جعفر کی روایت میں ہے کہ حریز نے اس حدیث کو مرفوعاً بیان کیا۔ لیکن زیادہ مضبوط بات یہ ہے کہ یہ موقوف ہے بشر بن بکر، علی بن عیاش، ابوالیمان وغیرہ نے حریز سے اسی طرح نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۸۸) استیعاب (ت: ۲۴۶۹) تجرید (۸۴/۲)\n(2) تاریخ کبیر (۳۳۱/۴)\n(3) کنز العمال (الحدیث: ۱۶۲۰) طبقات کبریٰ (۱۳۹/۷) جامع المسانید (۶۶۶/۱۱)"}],[8071,"§۸۰۹۱ ۔ معاویہ(1)\nنوفل کے والد ہیں۔ امام طبری رحمہ اللہ نے ان کا تذکرہ کیا ہے۔ ابن ابی سبرہ کے طریق سے محمد بن عبدالرحمن سے تخریج کیا ہے نوفل بن معاویہ اپنے والد سے نقل کرتے ہیں کہ نبی علیہ السلام نے ارشاد فرمایا کہ تم میں سے کسی کے اہل و عیال کو چھین لیا جائے یہ بہتر ہے اس بات سے کہ اس کی عصر کی نماز قضا ہو جائے۔\nعبدالرزاق(2) نے اپنی کتاب میں ابن ابی سبرہ سے ہی اس کی تخریج کی ہے اور فرمایا کہ یہ ضعیف ہے۔\nسب سے زیادہ حفاظت شدہ اس حدیث میں وہ روایت ہے جس کو امام نسائی رحمہ اللہ نے جعفر بن ربیعہ اور یزید بن ابی حبیب کے طریق سے تخریج کیا ہے۔ دونوں کو الگ عراک بن مالک سے کہ انہوں نے نوفل بن معاویہ سے یہ حدیث سنی ہے کہ میں نے نبی علیہ السلام سے سنا ہے ارشاد فرمایا: جس شخص کی نماز فوت ہو جائے گویا کہ اس کا مال اور اہل و عیال سب چھن گئے۔(3) اور نوفل کا سلسلہ نسب نون کی سختی میں آئے گا۔ اگر یہ ابو سبرہ کے بیٹے ہیں تو ان کے حفظ سے یہ بات معلوم ہوتی ہے کہ ان کو اور ان کے بیٹے دونوں کو نبی علیہ السلام کی صحبت نصیب ہوئی۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۸۷) تجرید (۸۴/۲)\n(2) مصنف عبدالرزاق (الحدیث: ۲۲۲۰/۲)\n(3) معجم الکبیر (الحدیث: ۴۲۹/۱۹) مصنف عبدالرزاق (الحدیث: ۲۲۲۰) مجمع الزوائد (الحدیث: ۳۰۸/۱) جامع المسانید (۶۶۴/۱۱)"}],[8072,"§۸۰۹۲ ۔ معبد بن اکثم الخزاعی(1)\nان کا تذکرہ اکثم بن ابی الجون کے حالات میں الف کی سختی میں گزر گیا ہے۔ ابن کلبی کا کہنا ہے کہ معبد کی والدہ وہی ہیں جس کے پاس سے نبی علیہ السلام ہجرت کے دوران گزرے تھے۔ یہ اکثر بن ابی الجون کی بیوی ہیں، ان کی اولاد میں معبد، نصرہ، اور ایک بیٹی جلد یہ ہیں۔","",{"fn":"(1) تجرید (۸۴/۲)"}],[8073,"§۸۰۹۳ ۔ معبد بن امیہ\nبن خلف تجھی ان کا تذکرہ ان کے بھائی سلمہ کے احوال میں گزر چکا ہے۔"],[8074,"§۸۰۹۴ ۔ معبد بن حمید\nبن زہیر بن حارث بن اسد بن عبد العزی۔ زبیر بن بکار ان کے تذکرہ میں لکھتے ہیں: ان کا بیٹا عبداللہ بن معبد جنگ جمل میں شہید ہوا اور یہ بیٹا ناجیہ بنت حکیم بن حزام سے تھا۔\nمیں کہتا ہوں: معبد کے والد حمید اسلام کے زمانہ سے پہلے ہی فوت ہو گئے۔ اس کا تقاضا یہ ہے کہ معبد کو نبی علیہ السلام کی صحبت حاصل ہوئی کیونکہ محدثین کا یہ فیصلہ ہے کہ مکہ اور طائف میں جو بھی نبی علیہ السلام کے زمانہ میں موجود تھا اور سیدنا ابو بکر رضی اللہ عنہ کے زمانہ تک رہا یا اس کے بعد تک تو وہ صحابہ رضی اللہ عنہم میں شمار ہوگا اس لیے کہ یہ سب لوگ حجۃ الوداع میں شریک تھے۔"],[8075,"§۸۰۹۵ ۔ معبد بن خالد الجہنی(1)\nکنیت: ابو روعہ۔ بقول واقدی(2): یہ شروع میں ہی مسلمان ہو گئے تھے اور یہ ان چار لوگوں میں سے تھے جنہوں نے فتح مکہ کے دن قبیلہ جہینہ کے جھنڈے اٹھائے ہوئے تھے۔ اور یہ دیہات میں رہتے تھے۔ ان کی وفات ۷۲ھ میں ہوئی۔ انہوں نے اپنی زندگی کی تقریباً ۸۰ بہاریں دیکھیں۔\nبقول ابن ابی حاتم،(3) ابو احمد حاکم اور ابن حبان ان کو نبی علیہ السلام کی صحبت کا شرف حاصل ہونے کے ساتھ سیدنا ابوبکر و عمر رضی اللہ عنہما سے روایت بھی حاصل ہے۔\nابو عمر(4) کا کہنا ہے کہ یہ وہ معبد نہیں ہیں جو تقدیر کے بارے میں گفتگو اور بحث کیا کرتے تھے جیسا کہ بعض لوگوں کا کہنا ہے کہ یہ وہی ہیں۔\nمیں کہتا ہوں: کہ یہ دوسری بات غلط ہے کہ یہ وہی قدری معبد ہیں اس لیے کہ وہ تو ان صحابی کے والد کے نام و نسب میں موافقت رکھتا ہے حالانکہ ان کے والد کے نام کے بارے میں اختلاف ہے۔ ایک قول یہ ہے کہ خالد ہے۔ دوسرا قول یہ ہے کہ عبداللہ بن عویم۔ تیسرا قول یہ ہے کہ عبد بن حکیم ہے۔ اسی وجہ سے بعض لوگوں کا یہ خیال ہے کہ یہ اس راوی کے بیٹے ہیں جنہوں نے یہ حدیث روایت کی:\n((لا تنتفعوا من الميتة باهاب ولا عصب))۔\nتم مردار کے کچے چھڑے اور پٹھے سے کوئی نفع و فائدہ نہ حاصل کرو۔\nامام بخاری رحمہ اللہ(5) نے تاریخ صغیر میں فرمایا یہ معبد بن عبدالرحمن ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۹۱) استیعاب (ت: ۲۴۷۱) تجرید (۸۴/۲)\n(2) المغازی (۸۹۶)\n(3) الجرح والتعدیل (۲۷۹/۸)\n(4) استیعاب (۴۷۸/۳)\n(5) تاریخ کبیر (۴۰۰/۴)"}],[8076,"§۸۰۹۶ ۔ معبد بن زہیر(1)\nابن فتحون نے تنبیہ علی اوہام الاستیعاب میں ان کا تذکرہ کرتے ہوئے مغازی اموی سے نقل کیا ہے کہ ابن اسحاق سے روایت ہے کہ جنگ یمامہ کے شہداء میں ان کا بھی ذکر ہے اور ابن فتحون نے ذیل میں ان کا تذکرہ نہیں کیا حالانکہ یہ ان کی شرائط پر ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۹۳) استیعاب (ت: ۲۴۷۲) تجرید اسماء الصحابہ (۸۴/۲)"}],[8077,"§۸۰۹۷ ۔ معبد بن عباد(1)\nبن قشیر بن قدم بن سالم بن مالک بن سالم (المعروف مختلی) بن غنم بن عوف بن خزرج انصاری۔ ابن اسحاق(2) وغیرہ نے شہداء بدر میں ان کا ذکر کیا ہے۔\nکنیت: ابو حمیضہ۔ اسی کنیت سے یہ مشہور ہیں۔ حمیضہ کا لفظ حا کے ساتھ بھی ہے اور جیم کے ساتھ بھی اکثر نے کہا ہے۔ ابو عمر(3) واقدی کی پیروی کرتے ہوئے کہتے ہیں کہ یہ خاء کے ساتھ ہے اور ضاد کے بجائے صاد وزن بھی بڑا عجیب بنتا ہے۔\nابو معشر سے منقول ہے عمیمہ یعنی عین اور صاد کے ساتھ۔ یہ ان کی غلطی ہے۔ ابن قداح نے ان کے والد کا نام عمارہ بتایا ہے۔ اسی نے ابن ماکولا کو وہم میں ڈالا تھا۔(4)","",{"fn":"(1) اسد الغابہ (ت: ۴۹۹۶) استیعاب (ت: ۲۴۷۵) تجرید (۸۵/۲)\n(2) سیرۃ النبویہ (۲۵۴/۲)\n(3) استیعاب (۴۷۹/۳)\n(4) الاکمال (۵۳۸/۲)"}],[8078,"§۸۰۹۸ ۔ معبد بن عبد(1)\nسعد بن عامر بن عدی بن مجدعہ بن حارثہ بن حارث انصاری، حارثی۔ ابن عبدالبر(2) ان کے تذکرہ میں فرماتے ہیں کہ یہ خود اور ان کا بیٹا تمیم بن معبد دونوں غزوہ اُحد میں شریک تھے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۹۸) استیعاب (ت: ۲۴۷۷) تجرید (۸۵/۲)\n(2) استیعاب (۴۸۰/۳)"}],[8079,"§۸۰۹۹ ۔ معبد بن عمرو تمیمی\nسعید بن عمرو کے حالات میں گزر چکا ہے۔"],[8080,"§۸۱۰۰ ۔ معبد بن عمرو\nقریش کے اتحادی ہیں۔ عبداللہ بن محمد قدامی اور ابو خف نے ان کا ذکر کیا ہے کہ یہ سیدنا ابوبکر صدیق رضی اللہ عنہ کے دور خلافت میں جنگ محل میں شہید ہو گئے تھے۔"],[8081,"§۸۱۰۱ ۔ معبد بن عمرو التمیمی(1)\nبقول ابن عساکر ابو مخنف اور قدامی کا کہنا ہے کہ یہ مخل نامی جگہ میں شہید ہوئے ان کے علاوہ باقی حضرات کا کہنا ہے کہ اجنادین میں شہید ہوئے۔ بقول ابن اسحاق حبشہ کی طرف ہجرت کرنے والوں میں ایک معبد بن عمرو تمیمی بھی تھے۔ ابوالاسود عروہ سے روایت کرتے ہوئے فرماتے ہیں کہ اجنادین میں تمیم بن حارث اور ان کا ماں شریک بھائی معبد بن عمرو تیمی شہید ہوئے۔","",{"fn":"(1) تجرید (۸۵/۲)"}],[8082,"§۸۱۰۲ ۔ معبد بن عمرو الانصاری\nامام واقدی رحمہ اللہ نے لکھا ہے کہ ابوسفیان بن حرب نے قسم کھالی کہ جب تک میں مسلمانوں سے اپنا بدلہ نہ لے لوں میرے سر کو پانی نہیں چھوئے گا۔ پھر یہ دوسو شہسواروں کو لے کر نکل پڑا تو انصار کے ایک آدمی معبد بن عمرو اور ان کے ساتھ ایک مزدور تھا ان کے پاس پہنچے اور ان دونوں کو قتل کر دیا۔ پھر اس نے دیکھا کہ اب میری قسم پوری ہوگئی لہذا واپس چلا گیا۔\nابن اسحاق نے بھی واقعہ لکھا ہے، لیکن انہوں نے مزدور کے بجائے حلیف اتحادی کا ذکر کیا ہے اور دونوں حضرات کا نام بھی نہیں لکھا۔"],[8083,"§۸۱۰۳ ۔ معبد بن عوسجہ\nبن حرملہ بن سبرہ بن خدیج بن مالک جھنی یہ سہرہ کے والد ہیں سبرہ بن ابی سبرہ کے حالات میں ان کا تذکرہ ہو چکا۔ ابن قانع کا خیال ہے کہ ابو سبرہ جن کا یہاں ذکر ہے وہ یہی معبد ہیں۔ جبکہ ذہبی نے لکھا ہے ابو سبرہ یہ عیسی بن سبرہ بن ابی سہرہ کے دادا ہیں جو کہ اپنے والد اور اپنے دادا سے روایت نقل کرتے ہیں۔ ان کے علاوہ حضرات کا کہنا ہے کہ وہ تو جعفی ہیں اور یہی بات زیادہ واضح ہے۔"],[8084,"§۸۱۰۴ ۔ معبد بن قیس العبدی\nابن وہب کے حالات میں ان کا ذکر آئے گا۔"],[8085,"§۸۱۰۵ ۔ معبد بن قیس(1)\nابوعلی بن سکن نے صحابہ رضی اللہ عنہم میں ان کا تذکرہ کیا ہے اور فرمایا کہ احمد بن سنان واسطی نے اپنی مسند میں ان کا ذکر کرتے ہوئے سماک بن حرب کی روایت سے تخریج کیا ہے کہ معبد بن قیس نے فرمایا کہ جب میں نے شادی کر لی تو نبی علیہ السلام ہمارے پاس آئے اور پوچھا کہ کچھ کھیل شغل بھی کیا ہے؟(2)","",{"fn":"(1) اسد الغابہ (ت: ۵۰۰۰) استیعاب (ت: ۲۴۷۸) تجرید (۸۵/۲)\n(2) معجم الکبیر (الحدیث: ۲۵۸/۲۴) مجمع الزوائد (الحدیث: ۲۸۹/۴) کنز العمال (الحدیث: ۴۰۶۲۶)"}],[8086,"§۸۱۰۶ ۔ معبد بن قیس بن صخر\nبعض حضرات کا کہنا ہے کہ ان کا نسب یوں ہے کہ ابن صیفی بن صخر بن حرام بن عبید بن عدی بن غنم بن کعب بن سلمہ انصاری سلمی۔ موسیٰ بن عقبہ نے شہداء بدر میں ان کا ذکر کیا ہے اسی طرح ابن اسحاق(1) وغیرہ نے بھی ان کا تذکرہ کیا ہے۔","",{"fn":"(1) السیرۃ النبویہ (۲۵۸/۲) اسد الغابہ (۱۶۳/۴)"}],[8087,"§۸۱۰۷ ۔ معبد بن مخرمہ(1)\nبن قلع بن حریش بن عبدالا شبل انصاری، اہلی۔ ابن عبدالبر(2) ان کے تذکرہ میں فرماتے ہیں کہ یہ غزوہ اُحد میں شریک تھے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۰۱) استیعاب (ت: ۲۴۷۹) تجرید (۸۵/۲)\n(2) استیعاب (۴۸۰/۳)"}],[8088,"§۸۱۰۸ ۔ معبد بن مسعود السلمی(1)\nیہ مجالد اور مجاشع کے بھائی ہیں۔ امام بخاری،(2) اور بزار اور ابن حبان کا کہنا ہے کہ ان کو نبی علیہ السلام کی صحبت حاصل ہوئی۔\nامام بغوی اور اسماعیلی نے زہیر بن معاویہ کے طریق سے عاصم احول سے تخریج کیا ہے کہ ابو عثمان نہدی نے کہا مجاشع بن مسعود نے مجھے بتایا کہ میں اپنے بھائی معبد کو فتح مکہ کے بعد نبی علیہ السلام کی خدمت میں لے کر آیا تا کہ ہم آپ علیہ السلام کے ہاتھ پر بیعت ہجرت کریں لیکن آپ علیہ السلام نے ارشاد فرمایا کہ مہاجرین نے ہجرت کا ثواب حاصل کر لیا بس اب ہجرت ختم تو میں نے عرض کیا کہ پھر کس چیز پر ہم آپ کی بیعت کریں؟ تو فرمایا کہ ایمان اور جہاد پر بیعت کر لو۔(3) راوی کہتے ہیں کہ بعد میں میں معبد سے ملا جو کہ مجاشع سے بڑے تھے تو میں نے اس حدیث کے بارے میں پوچھا تو انہوں نے کہا کہ مجاشع نے صحیح کہا ہے اور اس حدیث کے تمام راوی ثقہ و با اعتماد ہیں۔\nامام بخاری رحمہ اللہ کے ہاں یہ روایت اکثر حضرات نے فربری سے نقل کی ہے اور وہ مجاشع سے نقل کرتے ہیں، اسی طرح کہا ہے لیکن شمیپنی کے ہاں ہم ابو معبد سے ملے“ یہ الفاظ ہیں۔ ابوعوانہ، جوزقی اور طبرانی نے اس کو اکثر حضرات کی طرح زہیر سے(4) ہی مختلف طرق سے تخریج کیا ہے۔ ابوعوانہ کی سند ہے کہ عمر بن ابی قیس نے عاصم سے روایت کیا، لیکن انہوں نے معبد کا نام نہیں لیا۔ امام بخاری رحمہ اللہ نے خالد حذاء کے طریق سے ابو عثمان سے تخریج کیا ہے اور مجالد نام ذکر کیا ہے۔\nفضیل بن سلیمان کے طریق سے عاصم سے روایت ہے کہ ”میں ابو معبد کو لے کر گیا“ اس سے معلوم ہوتا ہے کہ مجاشع کے دو بھائی تھے: مجالد اور معبد۔ جس کو نبی علیہ السلام کے پاس لے کر آیا تھا۔ وہ معبد تھا اور جس کو ابو عثمان بعد میں ملے ہیں وہ مجالد تھا جس کی کنیت ابو معبد تھی۔\nعلی بن مسہر اور عاصم احول کی روایت جو امام مسلم رحمہ اللہ کے ہاں ہے اس میں یہ ہے کہ ماقد برشدالی ڈ لک۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (ت: ۵۰۰۲) استیعاب (ت: ۲۴۸۰) تجرید (۸۵/۲)\n(2) تاریخ کبیر (۳۹۸/۴)\n(3) بخاری کتاب المغازی باب (۵۳) الحدیث (۴۳۰۵، ۴۳۰۶) مسند احمد (الحدیث: ۴۶۹/۳) مستدرک حاکم (الحدیث: ۶۱۶/۳) مشکل الآثار للطحاوی (الحدیث: ۵۲/۳)\n(4) معجم الکبیر (الحدیث: ۷۶۵/۲۰) و (الحدیث: ۷۶۹/۲۰)"}],[8089,"§۸۱۰۹ ۔ معبد بن ابی معبد خزاعی\nابن مندہ ان کے تذکرہ میں یعقوب بن محمد زہری کے طریق سے تخریج کرتے ہیں کہ عبدالرحمن بن عقبہ اپنے والد سے روایت کرتے ہیں کہ جابر رضی اللہ عنہ نے فرمایا کہ سیدنا ابو بکر صدیق رضی اللہ عنہ اور نبی علیہ السلام جب ہجرت فرما گئے تو راستے میں ام معبد کی جھونپڑی کے پاس سے گزرے تو نبی علیہ السلام نے معبد کو بھیجا، اس وقت یہ چھوٹے سے تھے اور فرمایا کہ اس بکری کو لے آؤ۔ اور ایک مشکیزہ بھی لے آؤ۔ سیدہ ام معبد رضی اللہ عنہا نے پیغام بھیجا کہ اس بکری کا دودھ نہیں ہے آپ علیہ السلام نے فرمایا کوئی بات نہیں آپ لے آؤ۔ پھر آپ نے اس بکری کی پشت پر ہاتھ پھیرا ہاتھ پھیرنے کی دیر تھی کہ وہ دودھ دینے لگ گئی آپ نے خود دودھ دوہا اور خود بھی پیا اور سیدنا ابوبکر، عامر اور معبد کو بھی پلایا پھر بکری کو واپس کر دیا۔\nسیف نے فتوح میں اور طبری نے ابن مثنی بن حارثہ کے طریق سے تخریج کیا ہے کہ جب سیدنا خالد بن ولید رضی اللہ عنہ شام کی طرف نکلے تو آپ لشکر کو تقسیم کر دیا تو معبد بن ابی معبد شنی بن حارثہ کے ساتھ رہا دیگر صحابہ رضی اللہ عنہم کی طرح۔\nابو عبید بکری ضبجنان پر بات کرتے ہوئے غزوہ ذات الرقاع میں ان کی اونٹنی کی طرف اشارہ کرتے ہوئے یہ اشعار کہتے ہیں:\n(۱) محمد کے ساتھیوں کی دونوں جماعتوں سے وہ بھاگ نکلی مدینہ کی بہت سی عمدہ کھجوریں خراب منگنے کی طرح ہوتی ہیں۔\n(۲) اور میں نے قدید کے پانی کو اپنے لیے مقررہ جگہ قرار دیا ہے، اور ضبجنان کے پانی کے لیے کل صبح چاشت کا وقت ہے۔\nمیں کہتا ہوں: یہ معبد، ام معبد کے بیٹے کے علاوہ کوئی اور شخصیت ہیں۔ اس لیے کہ سیرۃ نبویہ میں ہے کہ معبد خزاعی نے ابوسفیان کو میدان احد میں دوبارہ جانے سے روکا تھا، جبکہ وہ اپنے گمان کے مطابق مسلمانوں کو سرے سے ہی ختم کرنے جارہا تھا، اس بارے میں انہوں نے شعر بھی کہے۔ لہذا معبد بن ام معبد تو کم عمر تھے وہ یہ کیسے کر سکتے تھے۔"],[8090,"§۸۱۱۰ ۔ معبد بن مقداد\nبن اسود۔ ان کا نسب ان کے والد کے حالات میں آئے گا اور ان کے اپنے حالات دوسری قسم میں آئیں گے۔"],[8091,"§۸۱۱۱ ۔ معبد بن میسرہ السلمی(1)\nابن عبدالبر(2) ان کا تذکرہ کرتے ہوئے فرماتے ہیں ان کے بارے میں کچھ غور و فکر کی ضرورت ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۰۳) استیعاب (ت: ۲۴۸۱) تجرید (۸۵/۲)\n(2) استیعاب (۴۸۰/۳)"}],[8092,"§۸۱۱۲ ۔ معبد بن نباتہ\nابن منقذ کے حالات میں ان کا ذکر آئے گا۔"],[8093,"§۸۱۱۳ ۔ معبد بن ھوذہ(1)\nنسب: معبد بن ھوذہ بن قیس بن عبادہ بن دُہیم بن عطیہ بن زید بن قیس بن عامر بن مالک بن اوس، انصاری، اوسی۔ ابوداؤد(2) نے ان کی حدیث کو عبدالرحمن بن نعمان بن معبد کے طریق سے روایت کیا ہے کہ وہ اپنے والد اور اپنے دادا سے نقل کرتے ہیں کہ نبی علیہ السلام نے رات کو سونے کے وقت خوشبودار اثمد سرمہ لگانے کا حکم دیا اور فرمایا کہ روزے دار کو اس سے بچنا چاہیے۔ ابو داؤد فرماتے ہیں کہ یحیی بن معین نے مجھے بتایا کہ یہ حدیث منکر ہے۔\nامام بغوی نے کنیتوں میں ان کا تذکرہ کرتے ہوئے فرمایا ابو نعمان انصاری عبدالرحمن بن نعمان کے دادا ہیں۔ اور انہوں نے یہ مجھے نہیں بتایا کہ ان کا نام معبد تھا۔\nنکتہ: بعض لوگوں کا کہنا ہے کہ ((عن جدہ)) کی ضمیر اگر عبدالرحمن کی طرف لوٹے تو مطلب یہ ہوگا کہ ھوذہ صحابی ہیں۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (ت: ۵۰۰۶) استیعاب (ت: ۲۴۸۲) تجرید (۸۶/۲)\n(2) ابوداؤد کتاب الصوم باب فی الکحل عند النوم (الحدیث: ۲۳۷۷)"}],[8094,"§۸۱۱۴ ۔ معبد بن وہب العبدی العصری(1)\nابن ابی حاتم نے صحابہ رضی اللہ عنہم میں ان کا تذکرہ کیا ہے۔ اور امام بغوی نے طالب بن جیر کے طریق سے عود عصری سے تخریج کیا ہے کہ معبد بن وہب بن عبد قیس غزوہ بدر میں شریک تھے اور انہوں نے دو تلواروں سے لڑائی کی تو نبی علیہ السلام نے ارشاد فرمایا: عبد القیس کے نوجوانوں پر افسوس! یہ تو یقیناً اللہ کی زمین پر اس کے شیر ہیں۔(2)\nابن السکن نے اسی سند سے اس کو تخریج کرتے ہوئے، فرمایا کہ عبد القیس کے ایک آدمی کے بارے میں روایت ہے کہ وہ بہت زیادہ حج کرنے والا تھا۔ زمانہ جاہلیت میں اس کا نام معبد بن وہب تھا۔ اس نے قریش کی ایک عورت سے شادی کی جس کا نام صویرہ بنت زمعہ تھا جو کہ ام المومنین سیدہ سودہ کی بہن ہیں۔ یہ غزوہ بدر میں شریک تھے۔ پھر ان کا تذکرہ کیا لیکن ان کے ہاں روایت کچھ یوں ہے کہ آقائے مدنی نے پوچھا یہ کون ہے؟ تو لوگوں نے کہا: یہ معبد بن قیس ہے۔\nاس سے معلوم ہوتا ہے کہ شاید قیس ان کے دادوں میں سے کوئی تھا۔\nابویعلی موصلی، ابوجعفر طبری، ابن قانع ابن شاہین اور مستغفری نے اس روایت کو تخریج کیا ہے اور سب نے محمد بن صدران سے روایت کیا ہے اور وہ ایک طالب سے نقل کرتے ہیں۔ ابن مندہ کی رائے یہ ہے کہ یہ معبد بن قیس انصاری ہی ہیں جن کا تذکرہ ابھی ابھی گزر گیا ہے، لیکن ان کا یہ خیال صحیح نہیں ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۰۵) استیعاب (ت: ۲۴۸۳) تجرید (۸۶/۲)\n(2) اسد الغابہ (۱۶۴/۴)"}],[8095,"§۸۱۱۵ ۔ معبد ابن فلان الجزامی(1)\nطبرانی(2) وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا تذکرہ کیا ہے اور اموی نے مغازی میں ابن اسحاق(3) سے تخریج کیا ہے عمیر بن معبد بن فلان جذامی سے کہ وہ اپنے والد سے نقل کرتے ہیں کہ انہوں نے فرمایا رفاعہ بن زید جذامی نبی علیہ السلام کی خدمت میں حاضر ہوئے تو آپ علیہ السلام نے ان کو ایک خط لکھ کر دیا جس میں یہ تھا: بسم اللہ الرحمن الرحیم محمد رسول اللہ صلی اللہ علیہ وسلم کی طرف سے رفاعہ بن زید کی طرف کہ میں نے ان کو ان کی قوم اور اس میں داخل ہونے والے لوگوں کی طرف بھیجا ہے کہ یہ لوگوں کو اللہ و رسول کی طرف بلائیں۔ پھر پورا لمبا واقعہ ذکر کیا اور اس میں یہ بھی ہے کہ حیان بن ملہ اس وقت دحیہ کلبی کے ساتھ تھے جبکہ وہ نبی علیہ السلام کا خط مبارک قیصر کے پاس لے کر جارہے تھے پھر واپسی پر ہنید بن عریض جذامی نے ان کا پیچھا اور تعاقب کر کے ان کا تمام مال و متاع لے لیا پھر نعمان بن ابی جھال نے اپنی ایک جماعت لے کر ان کی مدد کی اور جو کچھ انہوں نے لیا تھا سب کچھ چھڑوا لیا۔ اور وہ دحیہ اور ان کے معاون حیان بن ملہ کو واپس کیا۔ حیان نے دحیہ سے سورہ فاتحہ سیکھی تھی۔ پس یہی وہ چیز ہے جس نے اسی وجہ سے زید بن حارثہ کو بنو جذام کی طرف جانے کے لیے بھڑکایا تو انہوں نے ہنید اور اس کے باپ کو قتل کر دیا۔\nامام طبرانی رحمہ اللہ نے بڑا لمبا قصہ نقل کیا ہے اور ہم نے بھی اس کو امالی المحاملی میں عالی سند کے ساتھ نقل کیا ہے۔ اس میں سے کچھ حیان بن ملہ کے حالات میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۹۰)\n(2) معجم الکبیر (الحدیث: ۸۰۱/۲۰)\n(3) سیرۃ النبویہ (۱۸۵/۴)"}],[8096,"§۸۱۱۶ ۔ معبد الخزاعی\nابو عمر نے معبد بن خزاعی اور معبد بن ابی معبد (جن کا ذکر ابھی گزرا) کو الگ الگ شخصیات قرار دیا حالانکہ یہ ایک ہی شخصیت ہیں۔ اس لیے کہ ان کا واقعہ ایک ہی ہے۔"],[8097,"§۸۱۱۷ ۔ معبد الخزاعی(1)\nابو عمر(2) ان کے تذکرہ میں فرماتے ہیں کہ یہ وہی معبد ہیں جنہوں نے ابوسفیان کو جنگ اُحد میں مدینہ واپس جانے سے روک دیا تھا۔ اس واقعہ کو ابو اسحاق نقل کرتے ہوئے فرماتے ہیں کہ عبداللہ بن ابی بکر بن محمد بن عمرو بن حزم نے مجھے بتایا کہ معبد خزاعی نبی علیہ السلام کے پاس سے گزرا جبکہ آپ علیہ السلام حمراء الاسد نامی جگہ میں موجود تھے اور ادھر دوسری طرف ابوسفیان بمع اپنے لشکر کے اُحد سے روحاء نامی جگہ پر پہنچا اور مسلمانوں کو مکمل طور پر ختم کیے بغیر واپس آنے پر بہت نادم و شرمندہ ہوئے اور کہا کہ ہم ان کی قیادت تک پہنچ گئے تھے لیکن افسوس کہ ہم مکمل طور پر مسلمانوں کو ختم نہ کر سکے۔ اچانک ابوسفیان کی نظر معبد پر پڑی اور معبد غزوہ اُحد سے واپسی پر حضور علیہ السلام سے ملا اور اپنے آپ کو مصیبت زدہ صحابہ میں سے قرار دیا حالانکہ حقیقت میں وہ مشرک تھا، اب جب یہ ابوسفیان سے ملا تو اس نے پوچھا کہ تم نے اپنے پیچھے مسلمانوں کو کس حال میں دیکھا ہے؟ معبد نے کہا: میں نے محمد (صلی اللہ علیہ وسلم) کو بمع ان کے صحابہ کے دیکھا ہے کہ وہ تمہیں تلاش کر رہے ہیں اور ان کے ساتھ صحابہ کی اتنی بڑی تعداد ہے کہ میں نے اس سے پہلے ایسا نہیں دیکھا اور وہ تم پر بہت زیادہ غصے کی آگ میں جلے ہوئے ہیں۔ اور ان کے جو ساتھی پیچھے رہ گئے تھے وہ سب جمع ہو گئے ہیں۔ میں نے ان کا اتنا غصہ کبھی نہیں دیکھا جو آج تم پر دیکھا ہے۔ ابوسفیان ساری باتیں سننے کے بعد بولا ہلاکت ہو تیرے لیے ذرا دیکھ تو سہی تو کیسی باتیں کر رہا ہے۔ معبد نے پھر کہا: اللہ کی قسم! میرا خیال تو یہ ہے کہ آپ ذرا سوار ہو کر دیکھیں تو آپ کو گھوڑے آتے دکھائی دیں گے۔(3)(4) اور میں تو ان کے حالات دیکھ کر بیہ شعر کہنے پر مجبور ہو گیا ہے، پھر اس نے یہ شعر پڑھا:\n”قریب تھا کہ آواز میں میری سواری کو ہلا کر رکھ دیتیں جب زمین سفید لشکر سے بہہ پڑی تھی۔“\nپھر اشعار کو ذکر کیا۔ تو ابوسفیان کا مدینہ پر دوبارہ حملہ کرنے کا ارادہ ختم ہو گیا اور وہ اپنے لشکریوں سمیت واپس ہو گیا۔\nمیں کہتا ہوں: بعض لوگوں کا خیال ہے کہ یہ وہی ام معبد خزاعیہ کے بیٹے ہیں جن کے پاس سے نبی علیہ السلام دوران ہجرت لے گئے۔ لیکن میرے علم و معلومات کے مطابق یہ اور ہیں۔ اور پہلے یہ بات گزر چکی ہے کہ وہ ہجرت کے زمانہ میں بہت ہی چھوٹے تھے اور اُحد کی لڑائی ہجرت کے تین سال یا اس کے بعد ہوئی ہے۔ تو اتنے چھوٹے بچے کے بارے میں یہ کہنا کہ وہ اپنی قوم کا سردار بھی تھا اور اس نے ابوسفیان سے اتنی باتیں کیں یہ بعید از عقل ہے۔\nاور ام معبد کے واقعہ میں یہ بھی بات معلوم نہیں ہوتی کہ ابو معبد کا کوئی اتنا مقام و مرتبہ ہو۔ اور ان کے حالات کنیتوں کے بیان میں آئیں گے۔ اور میرے نزدیک ان اشعار کا کہنے والا معبد وہی ہے جو ابوسفیان سے مخاطب ہوا۔ اور یہ اشعار معبد بن ابی معبد کے حالات میں گزر چکے ہیں۔ والعلم عند اللہ تعالی۔","",{"fn":"(1) اسد الغابہ (ت: ۴۹۹۲) استیعاب (ت: ۲۴۸۴) تجرید (۸۶/۲)\n(2) استیعاب (۴۸۱/۳)\n(3) سیرۃ النبویہ (۸۲، ۸۱/۳)\n(4) اسد الغابہ (۱۶۱/۴)"}],[8098,"§۸۱۱۸ ۔ معتب\nیہ عوف کے بیٹے ہیں اور ان کی والدہ کا نام حمراء تھا، ان کا تذکرہ بھی آگے آئے گا۔"],[8099,"§۸۱۱۹ ۔ معتب بن عبید(1)\nبعض لوگوں کا کہنا ہے کہ یہ عبدہ بن ایاس بلوی پھر ظفری ہیں جو کہ انصار کے قبیلہ بنو ظفر کے اتحادی ہیں۔ ابن اسحاق(2) اور موسیٰ بن عقبہ نے شرکاء بدر میں ان کا تذکرہ کیا ہے۔\nابن سعد(3) کا کہنا ہے کہ جو لوگ بنو ظفر میں ان کے نسب کو نہیں جانتے وہ صرف اتنا کہتے ہیں کہ یہ بلوی ہیں۔ اور اس کے علاوہ باقی لوگوں کا کہنا ہے کہ یہ عبداللہ بن طارق بن عمرو بن مالک کے ماں شریک بھائی ہیں۔ اور بعض کا کہنا ہے کہ ایاس بن تمیم بن شعبہ بن سعد اللہ بن فران بن بلی ان کے دادا ہیں۔ ان کے دادے کے نام کے بارے میں دوسرا قول یہ ہے کہ سوید بن ہیثم بن ظفر ہے۔\nابو عمر(4) نے ابن عمارہ سے نقل کیا ہے اور ابن سعد نے بھی ان کی موافقت کی ہے کہ ان کا نام غین کے ساتھ ہے اور اس کے آخر میں تا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۰۹) استیعاب (ت: ۲۴۸۷) تجرید (۸۶/۲)\n(2) سیرۃ النبویہ (۶۸۷/۱)\n(3) طبقات کبریٰ (۲۸/۳)\n(4) استیعاب (۴۸۲/۳)"}],[8100,"§۸۱۲۰ ۔ معتب بن عمرو الاسلمی\nکنیت: ابو مروان۔ اپنی کنیت سے ہی زیادہ مشہور ہیں۔ ان کے نام کے بارے میں اختلاف ہے۔ ایک قول تو یہی ہے جو کہ یہاں مذکور ہے، دوسرا قول: عین ساکن ہے اور تاء کے نیچے زیر ہے۔ تیسرا قول: جو کہ ابن عمارہ کے حوالہ سے اوپر والے نمبر میں گزر گیا۔\nامام واقدی رحمہ اللہ فرماتے ہیں کہ عطاء بن ابی مروان نے اپنے والد سے نقل کرتے ہوئے ہمیں بتایا کہ ان کے دادا معتب اسلمی نے فرمایا کہ میں نبی علیہ السلام کی خدمت میں بیٹھا ہوا تھا کہ ماعز بن مالک آئے۔۔۔۔ پھر ان کے سنگسار کرنے(1) کا واقعہ نقل کیا۔ اس میں یہ بھی ہے کہ ان سے پوچھا گیا کہ تم نے اس عورت سے زنا کیا ہے؟ کیا تمہارا عضو اس کے اندر ایسے غائب ہو گیا تھا جیسا کہ سرمچو سرمہ دانی میں یا ڈول کی رسی کنویں میں غائب ہو جاتی ہے؟ تو انہوں نے جواب دیا: جی ہاں۔\nان کی ایک اور حدیث بھی ہے جو ابو معتب کے حالات میں کنیتوں کے تحت آئے گی۔ ان شاء اللہ","",{"fn":"(1) جامع المسانید (۶۷۵/۱۱) الاکمال (۲۱۶/۷)"}],[8101,"§۸۱۲۱ ۔ معتب بن عوف\nابن الحمراء الخزاعی کے نام سے مشہور ہیں۔ ابن اسحاق نے مہاجرین حبشہ اور شرکاء بدر میں ان کا ذکر کیا ہے۔ ابن برقی فرماتے ہیں کہ ان کو ابن الحمراء بھی کہا جاتا ہے اور بیعانہ بھی۔"],[8102,"§۸۱۲۲ ۔ معتب بن قشیر(1)\nنسب: ابن ملیک بن زید بن عطاف بن ضبیعہ بن زید بن مالک بن عوف بن عمرو بن عوف بن اوس انصاری، اوسی۔ محدثین نے بیعت عقبہ کے شرکاء میں ان کا ذکر کیا ہے۔ اور بعض کا کہنا ہے: یہ منافق تھے جنہوں نے جنگ احد میں یہ کہا تھا: ((لو كان لنا من الامر شي ما قتلنا لهنا))۔(2)\nدوسرا قول یہ ہے کہ انہوں نے توبہ کر لی تھی۔ اور ابن اسحاق(3) نے شرکاء بدر میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۱۰) استیعاب (ت: ۲۴۸۵) تجرید (۸۶/۲)\n(2) تفسیر ابن کثیر (۱۲۶/۲) آیۃ سورۃ آل عمران آیۃ (۱۵۴)\n(3) سیرۃ النبویہ (۲۴۹/۲)"}],[8103,"§۸۱۲۳ ۔ معتب بن ابی لہب(1)\nبن عبد المطلب بن ہاشم بن عبد مناف، ہاشمی۔ نبی علیہ السلام کے چچا کے بیٹے ہیں۔ زبیر بن بکار نے ان کے تذکرہ میں لکھا ہے کہ یہ اور ان کے بھائی غزوہ حنین میں شریک تھے اور یہ دونوں حضرات دیگر صحابہ رضی اللہ عنہم کی طرح ثابت قدم رہے اور یہ دونوں مکہ کے رہائشی تھے۔\nابن سعد(2) نے اپنی سند سے تخریج کیا ہے کہ عباس بن فضل نے فرمایا کہ جب نبی علیہ السلام فتح مکہ کے موقع پر مکہ میں تشریف لائے تو مجھ سے پوچھا: اے عباس! تیرے بھتیجے عتبہ اور معتب کہاں ہیں؟ میں ان کو دیکھنا چاہتا ہوں۔ میں نے عرض کیا کہ قریش کے مشرکین کے ساتھ وہ دونوں بھی کہیں الگ ہو گئے ہیں۔ تو آپ علیہ السلام نے ارشاد فرمایا: ان دونوں کو میرے پاس لے آؤ۔ تو میں سوار ہو کر عرفہ کی طرف گیا اور ان دونوں کو کہا کہ رسول اللہ صلی اللہ علیہ وسلم دونوں کو بلا رہے ہیں۔ وہ دونوں جلدی سے سوار ہو کر نبی علیہ السلام کی خدمت میں حاضر ہو گئے۔ آقا علیہ السلام نے ان کو اسلام لانے کی دعوت دی تو وہ دونوں مسلمان ہو گئے اور بیعت کر لی۔ پھر نبی علیہ السلام نے فرمایا کہ میں نے اپنے ان دونوں چچا کے بیٹوں کو اپنے رب سے مانگا تھا تو اللہ نے مجھے عطا فرما دیے۔\nامام طبرانی رحمہ اللہ نے ایک اور سند سے سیدنا علی رضی اللہ عنہ سے روایت کیا ہے کہ نبی علیہ السلام فتح مکہ کے دن عتبہ اور معتب کے درمیان کھڑے ہو کر فرما رہے تھے یہ دونوں میرے چچا زاد بھائی ہیں۔ میں نے ان کو اللہ سے مانگا تھا تو اللہ تعالیٰ نے عطا فرما دیے۔ گویا کہ نبی علیہ السلام ان کے اسلام لانے سے خوشی کا اظہار فرما رہے تھے پھر آپ اسی طرح ان کے درمیان چلتے ہوئے مسجد میں داخل ہو گئے۔ یہ واقعہ سیدنا عباس رضی اللہ عنہ کے ان کو لانے کے بعد کا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۱۱) استیعاب (ت: ۲۴۸۸) تجرید (۸۶/۲)\n(2) طبقات کبریٰ (۶۰/۴)"}],[8104,"§۸۱۲۴ ۔ معتکد بن مہلہل\nبن دثار جیتی۔ یہ جنوں میں سے مسلمان ہوئے تھے اور ان کا واقعہ امام خراکی نے کتاب الہواتف میں ذکر کیا ہے۔ اور میں نے رافع بن عمیر کے حالات میں ذکر کیا ہے۔"],[8105,"§۸۱۲۵ ۔ معتمر الکنانی(1)\nیہ حنش کے والد ہیں۔ امام طبرانی(2) وابن السکن صحابہ کرام میں ان کا تذکرہ کرتے ہوئے صالح بن عمر واسطی کے طریق سے تخریج کرتے ہیں کہ اسماعیل بن ابی خالد معتمر کے بیٹے حنش سے نقل کرتے ہیں کہ ان کے والد معتمر نے فرمایا نبی علیہ السلام ایک میت پر نماز جنازہ پڑھا رہے تھے کہ ایک عورت آگ کی انگیٹھی لے کر جنازہ کی طرف آ رہی تھی تو اس کو آواز دی، یہاں تک کہ وہ مدینہ کی جھاڑیوں میں داخل ہوگئی۔ بقول ابن السکن معتمر کی اس کے علاوہ کوئی روایت مجھے نہیں ملی اور یہ مشہور صحابہ رضی اللہ عنہم میں سے بھی نہیں ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۱۲) تجرید (۸۶/۲)\n(2) معجم الکبیر (الحدیث: ۳۲۱/۲۰)"}],[8106,"§۸۱۲۶ ۔ معدان بن ربیعہ(1)\nبن سلمہ بن ابوالخیر بن وہب بن معاویہ کندی۔ بقول ابن کلبی، ابن سعد اور طبرانی ان کا نبی علیہ السلام کی خدمت میں حاضر ہونا ثابت ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۱۴) تجرید (۸۷/۲)"}],[8107,"§۸۱۲۷ ۔ معدان\nکنیت: ابوالخیر۔ ان کا نام جفشیش ہے جو کہ جیم کی تختی میں گزر چکا ہے۔"],[8108,"§۸۱۲۸ ۔ معدان الکلاعی(1)\nیہ خالد کے والد ہیں۔ ابوعلی بن سکن اور ابن قانع نے صحابہ کرام رضی اللہ عنہم میں ان کا تذکرہ کیا ہے اور بقول ابن السکن نبی علیہ السلام کی صحبت کا شرف بھی حاصل ہوا۔ پھر دونوں نے ابن عجلان کے طریق سے ابان بن صالح سے تخریج کیا ہے کہ خالد بن معدان اپنے والد سے نقل کرتے ہیں کہ نبی علیہ السلام کا ارشاد گرامی ہے کہ بیشک اللہ تعالیٰ مہربان ہیں اور مہربانی و نرمی کو پسند فرماتے ہیں۔ اور ابن السکن فرماتے ہیں کہ یہ حدیث صرف اسی سند سے مجھے ملی، اور اس میں کوئی ذکر نہیں کہ انہوں نے نبی علیہ السلام کی زیارت کی ہو یا آپ سے کوئی حدیث سنی ہو۔\nمیں کہتا ہوں: طبرانی(2) نے ابن جریج کے طریق سے اس کو تخریج کیا ہے اور انہوں نے زیاد سے اور وہ خالد بن معدان سے اور وہ اپنے معدان سے روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۱۵) تجرید (۸۷/۲)\n(2) معجم الکبیر (الحدیث: ۸۳۲/۲۰)"}],[8109,"§۸۱۲۹ ۔ معد بن ذہل(1)\nان کا نبی علیہ السلام کے پاس آنا ثابت ہے اور ان کا بیٹا لاحق ان سے روایت نقل کرتا ہے۔ ابوموسیٰ کہتے ہیں کہ یحییٰ بن مندہ نے اپنی مستدرک میں ان کا ذکر کیا ہے، لیکن ان کی کوئی حدیث تخریج نہیں کی۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۱۳) تجرید (۸۶/۲)"}],[8110,"§۸۱۳۰ ۔ معديکرب بن الحارث(1)\nبن شرحبیل بن حارث کندی۔ بقول ابن کلبی یہ نبی علیہ السلام کی خدمت میں آئے تھے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۱۶) تجرید (۸۷/۲)"}],[8111,"§۸۱۳۱ ۔ معديکرب بن رفاعہ\nکنیت: ابورمنہ۔ اس کنیت سے مشہور ہیں۔ آگے کنیتوں کے بیان میں ان کا ذکر آئے گا۔"],[8112,"§۸۱۳۲ ۔ معديکرب بن شراحیل(1)\nبن شیطان بن خدیج بن امرأ القیس بن حارث بن معاویہ کندی۔ بقول ابن کلبی یہ نبی علیہ السلام کے پاس آئے تھے۔ اگر ان کے حالات محفوظ ہیں تو یہ گزشتہ معديكرب جن کا ذکر اس سے پچھلے نمبر میں ہیں ان کے چچا ہیں۔ لیکن میرے خیال کے مطابق پہلے جمہور میں سے نہیں ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۱۸) تجرید (۸۷/۲)"}],[8113,"§۸۱۳۳ ۔ معديکرب بن قيس الكندى\nبعض حضرات کا کہنا ہے کہ ان کا نام اشعث ہے حالانکہ اشعث تو لقب ہے۔"],[8114,"§۸۱۳۴ ۔ معديکرب الهمدانی(1)\nابواحمد عسکری صحابہ رضی اللہ عنہم میں ان کا تذکرہ کرتے ہوئے فضل بن علاء کوفی کے طریق سے ان کی حدیث تخریج کرتے ہیں۔ ثور بن یزید خالد بن معدان سے اور وہ معديكرب سے جو کہ نبی علیہ السلام کے صحابہ رضی اللہ عنہم میں سے ہیں فرمایا کہ ایک آدمی نے نبی علیہ السلام سے شکایت کی کہ جب میں اپنے گھر میں داخل ہوتا ہوں تو مجھے وحشت محسوس ہوتی ہے۔ تو نبی علیہ السلام نے اس کو حکم دیا کہ تم کبوتر کا ایک جوڑا اپنے پاس رکھو۔ تو اس شخص نے ایسا ہی کیا تو وحشت جاتی رہی۔\nحسن بن سفیان اور مستغفری اور علی بن سعید عسکری، یہ سب کے سب عمر بن موسیٰ کی روایت سے تخریج کرتے ہیں کہ خالد بن معدان معديكرب سے نقل کرتے ہیں کہ نبی علیہ السلام نے ارشاد فرمایا کہ جو شخص غلام کو آزاد کرے یا اپنی بیوی کو طلاق دے اور اس میں سے کچھ استثناء کرے(2) تو وہ اس کے لیے جائز ہوگا۔\nابواحمد عسکری کہتے ہیں کہ انہوں نے نبی علیہ السلام سے خود حدیث نہیں سنی اگر چہ بعض حضرات نے مسند میں ان کی حدیث تخریج کی ہے۔\nمیں کہتا ہوں: یہ بڑی عجیب بات ہے حالانکہ وہ روایت میں کہتے ہیں کہ یہ صحابہ رضی اللہ عنہم میں سے تھے۔ اور ابن الا شیر نے ان دونوں حدیثوں کے راویوں کو الگ الگ کیا ہے۔ میرے نزدیک دونوں ایک ہی ہیں کیونکہ دونوں سے روایت لینے والا راوی ایک ہے۔\nباقی رہا ان کا ہمدانی کہنا تو یہ ان کے اس حدیث کے راوی ہونے سے مانع اور روکنے والا نہیں، اس لیے کہ ایک دفعہ ان کی نسبت علاقہ کی طرف کی گئی ہے اور دوسری دفعہ ان کے قبیلہ کی طرف۔ اس کے باوجود یہ دونوں سندیں ضعیف ہیں۔ ابن حبان کے ہاں معتمد تابعین میں معديكرب ہمدانی ہیں اور وہ ابن مسعود رضی اللہ عنہ اور سیدنا خباب سے روایت نقل کرتے ہیں۔ اور ان سے روایت لینے والے ابو اسحق سبیعی ہیں اور ان کی روایت مذکورہ دونوں روایتوں کے علاوہ ہے۔ اور میں نے خطیب کی کتاب مؤتلف میں کچھ ایسی چیزیں دیکھی ہیں جس سے یہ معلوم ہو رہا تھا کہ ابو اسحق سبیعی نے ان سے جو روایت نقل کی ہے وہ اور ہے اور جو خالد بن معدان نے نقل کی ہے وہ اور ہے۔\nوکیع کے طریق سے تخریج کیا ہے کہ وہ اپنے والد سے اور وہ ابو اسحاق سے اور وہ معديكرب سے روایت نقل کرتے ہیں کہ ہم ابن مسعود رضی اللہ عنہ کے پاس آئے اور ان سے عرض کیا کہ ہمیں سورۂ شعراء پڑھ کر سنائیے تو آپ نے ان کو کتاب کے پاس بھیجا۔۔۔ الخ۔\nپس یہ ہے وہ جو ابن حبان نے ذکر کیا ہے اور ان کی صحبت بارگاہ رسالت کی کوئی صراحت نہیں کی۔ اور خطیب نے ان کو مشرق کی طرف منسوب کیا ہے اور یہ بھی لکھا ہے کہ انہوں نے ابو اسحاق والی روایت سیدنا علی رضی اللہ عنہ سے نقل کی ہے۔ یعقوب بن شیبہ بھی یہی کہتے ہیں اور مزید یہ کہ یہ مشرق (میم کے نیچے زیر) یمن کے ایک علاقے کے رہنے والے تھے اور یعقوب نے ان کو با اعتماد قرار دیا ہے اور یہ بھی کہا کہ عبد اللہ سے ان کی ایک اور حدیث بھی ہے۔ اور سیدنا علی رضی اللہ عنہ سے ایک موقوف حدیث ہے۔ خطیب کہتے ہیں کہ راویوں میں ایک معديكرب مشرقی ہیں جو ان سے بڑے ہیں اور سیدنا ابو بکر صدیق رضی اللہ عنہ سے روایت نقل کرتے ہیں۔ اور یہ بھی فرمایا کہ بعض لوگوں نے دونوں کو خلط ملط کر دیا ہے اور ان کو وہم ہوا ہے۔ تیسری قسم میں تفصیل سے آئے گا۔ ان شاء اللہ","",{"fn":"(1) تجرید (۸۷/۲)\n(2) جامع المسانید (۶۷۸/۱۱) اسد الغابہ (۱۶۸/۴)"}],[8115,"§۸۱۳۵ ۔ معرض بن علاط السلمی(1)\nحجاج کے بھائی ہیں۔ ابو عمر(2) نے کہا: مؤرخین و محدثین کا کہنا ہے یہ جنگ جمل میں شہید ہوئے اور ان کے بھائی حجاج نے ان کا مرثیہ کہا۔ اور حجاج کے حالات میں گزر چکا ہے۔ لیکن دارقطنی اس بات کی تردید کرتے ہیں اور کہتے ہیں کہ جنگ جمل میں مرنے والے تو معرض بن حجاج بن علاط ہیں اور ان کے جس بھائی نے مرثیہ پڑھا تھا وہ نصر بن حجاج تھا۔","",{"fn":"(1) اسد الغابہ (۵۰۲۲) استیعاب (ت: ۲۵۸۸) تجرید (۸۷/۲)\n(2) استیعاب (۴۰/۴)"}],[8116,"§۸۱۳۶ ۔ معرض بن معیقیب الیمامی(1)\nمعجزات کے بارے میں ان کی حدیث موجود ہے جو صرف ان کا بیٹا ہی ان سے روایت کرتا ہے۔ ابن السکن فرماتے ہیں کہ علامات نبوت کے بارے میں بھی ان کی ایک حدیث ہے لیکن وہ صرف کندیمی کے ہاں میں نے دیکھی ہے جو کہ ایک غیر معروف شیخ سے مروی ہے۔ اسی لیے میں نے بھی اس کی تخریج میں کوئی دلچسپی نہیں لی جبکہ ابن قانع نے کریمی سے اس کو تخریج کیا ہے کہ شاصویہ بن عبید کہتے ہیں کہ معرض بن عبداللہ بن معرض بن معیقیب اپنے والد سے اور وہ ان کے دادا معرض بن معیقیب سے نقل کرتے ہیں فرمایا کہ میں حجتہ الوداع کے موقع پر حج کرنے گیا تو مکہ میں داخل ہو کر نبی علیہ السلام کی زیارت کی آپ کا چہرہ چاند کی طرح چمک رہا تھا اور میں نے آپ سے بڑی عجیب بات سنی کہ یمامہ کا ایک آدمی دودھ پیتے بچے کو لے کر آیا جو سفید کپڑے میں لپٹا ہوا تھا۔ آپ علیہ السلام نے اس معصوم بچے سے پوچھا: ((من انا؟)) ”میں کون ہوں؟“ تو اس نے کہا: انت رسول اللہ ”آپ اللہ کے رسول ہیں“۔ تو آپ علیہ السلام نے فرمایا: تم نے سچ کہا ہے: اللہ تعالیٰ تمہیں برکت(2) عطا فرمائے۔ پھر اس بچے نے اس کے بعد اپنے بڑے ہونے تک کوئی بات نہیں کی۔\nمعرض فرماتے ہیں ہم نے اس بچے کا نام ہی نبی علیہ السلام کی اس دعا کی وجہ سے مبارک الیمامہ رکھ دیا۔\nامام بیہقی رحمہ اللہ نے کندیمی کے طریق سے اس کو ذکر کیا ہے۔ لیکن معرض اور اس کا استاذ اور شاصویہ یہ سب غیر معروف و غیر معروف ہیں۔ اسی لیے سب حضرات نے اس حدیث سے ناواقفی کا اظہار کیا ہے، اور کندیمی پر تردید کی ہے۔ لیکن ابوالحسن عقیقی نے اپنے فوائد میں ذکر کیا کہ میں نے شاہین کے بیٹے عبداللہ الحیلی مستملی سے خود سنا ہے کہ وہ فرماتے ہیں کہ میں نے اپنے مشائخ سے سنا ہے کہ جب کندیمی نے یہ حدیث لوگوں کو لکھوائی تو لوگوں نے اس کا انکار کیا اور کہا کہ یہ جھوٹ ہے۔ یہ شاصویہ کون آدمی ہے؟ پھر ایک طویل عرصہ گزرنے کے بعد عدن کے لوگوں کا ایک مسافر قافلہ آیا تو انہوں نے بتایا کہ ہم ایک کڑدہ نامی بستی میں داخل ہوئے تو وہاں ایک شیخ سے ملاقات ہوئی ہم نے اس سے پوچھا آپ کے پاس کوئی حدیث ہے؟ تو انہوں نے کہا: جی ہاں۔ ہم نے پوچھا آپ کا نام کیا ہے؟ تو انہوں نے بتایا: محمد بن شاصویہ۔ اور انہوں نے ہمیں وہ حدیث لکھوائی جو انہوں نے اپنے والد سے لکھی تھی۔\nابوالحسین بن جمیع اپنی معجم میں اس حدیث کی تخریج کرتے ہیں عباس بن محمد بن شاصویہ بن عبید اپنے والد سے اور وہ ان کے دادا سے نقل کرتے ہیں۔ اور خطیب نے صوری سے اور انہوں نے ابن جمیع سے اس کی تخریج کی ہے۔ اور اسی طرح امام بیہقی نے بھی اپنے طریق سے اس کی تخریج کی ہے۔\nحاکم نے اکلیل میں ایک اور سند سے عباس بن محمد بن شاصویہ سے اس کی تخریج کی ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۲۳) تجرید (۸۷/۲)\n(2) دلائل النبوۃ (الحدیث: ۵۹/۶، ۶۰) کنز العمال (الحدیث: ۳۵۴۰۱)"}],[8117,"§۸۱۳۷ ۔ معروف\nابن شاہین ان کے تذکرہ میں شیبہ بن زید کے طریق سے عکرمہ سے روایت تخریج کرتے ہیں کہ ابن عباس رضی اللہ عنہ نے فرمایا: نبی علیہ السلام کے پاس ایک آدمی لایا گیا جس سے آپ نے پوچھا: تیرا کیا نام ہے؟ تو اس نے جواب دیا: نکرہ۔ تو آپ نے فرمایا: نہیں! بلکہ آج سے تمہارا نام معروف ہے۔"],[8118,"§۸۱۳۸ ۔ معقل بن خویلد(1)\nبن واثلہ بن عمرو بن عبدیالیل ہذلی۔ رشاطی فرماتے ہیں: یہ شاعر تھا اور اس کے والد عبدالمطلب کے ساتھی تھے، جبکہ وہ ابرہہ کے پاس جا رہے تھے۔\nمیں کہتا ہوں: ابن اسحاق اور ابن قانع نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ ابن قانع وابن مندہ نے ابن ابی ذئب کے طریق سے عبداللہ بن یزید ہذلی سے روایت کیا ہے فرماتے ہیں کہ ابوسفیان اور معقل بن خویلد کے مابین قریش کے ایک آدمی کے چھینے ہوئے سامان کے بارے میں کچھ اختلاف تھا (جبکہ معقل اپنی قوم کا سردار تھا) تو نبی علیہ السلام نے ارشاد فرمایا: ”اے معقل بن خویلد! قریش کے ساتھ مقابلہ کرنے سے ڈرو۔(2)\nمیں کہتا ہوں: مرزبانی نے منجم الشعراء میں ان کا ذکر کیا ہے اور لکھا ہے کہ مخضرم اپنی قوم کا سردار تھا۔ خالد بن زہیر جو کہ ابوذویب کا بھانجا ہے اس کے پاس زمانہ جاہلیت میں ایک عورت اور اس کی بیٹی آئی تو معقل نے اس کی مذمت و ہجو کی تو پھر خالد نے اس کو جواب دیا۔ پھر ابوذویب نے ان کے درمیان صلح کروائی، اور اس نے ان کے آپس کے مباحثہ کا جواب بھی دیا۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۲۵) تجرید (۸۷/۲)\n(2) کنز العمال (الحدیث: ۳۳۸۸۴) تہذیب تاریخ دمشق (۴۰۷/۶)"}],[8119,"§۸۱۳۹ ۔ معقل بن سنان(1)\nبن مظہر بن عرکی بن فتیان بن سریع بن بکر بن امجمع بن ریث بن غطفان اشجعی۔ ابن الکلبي اور ابوعبیدہ نے ذکر کیا ہے کہ یہ نبی علیہ السلام کے پاس آئے تھے تو آپ علیہ السلام نے ان کے لیے کچھ جاگیر مقرر فرمائی تھی۔\nوفات: امام بغوی ہارون حمال سے نقل کرتے ہیں ابوستان معقل بن سنان اشجعی نے ذوالحجہ ۶۳ھ میں وفات پائی۔ ان کی کنیت کے بارے میں اختلاف ہے، چند اقوال ہیں:(۱) ابومحمد(۲) ابو عبد الرحمن(۳) ابوزید(۴) ابوعیسی(۵) ابوستان۔ انہوں نے نبی علیہ السلام سے روایت کی ہے۔ اور ان سے روایت لینے والے مسروق اور تابعین کی ایک جماعت ہے جن میں سرفہرست شعبی اور حسن بصری بھی کیا ہیں۔ بعض لوگوں کا کہنا ہے کہ ان سب حضرات نے جو ان سے روایت کی ہے وہ مرسل ہے۔\nعسکری فرماتے ہیں کہ کوفہ ان کا مسکن تھا اور یہ انتہائی خوبصورت تھے، حتی کہ سیدنا عمر رضی اللہ عنہ کے دور خلافت میں مدینہ آئے تو ان کی خوبصورتی کی وجہ سے یہ شعر کہا گیا:\n”میں معقل کے شر سے پناہ مانگتا ہوں لوگوں کے رب کی جبکہ معقل بالوں میں کنگھی کر کے بقیع کی طرف چلتا ہے۔“\nجب سیدنا عمر رضی اللہ عنہ کو اس بات کا پتہ چلا تو آپ نے ان کو مدینہ سے بصرہ منتقل کر دیا۔\nمدائنی نے اپنی سند سے ذکر کیا ہے کہ سیدنا عمر رضی اللہ عنہ نے ایک عورت کو یہ شعر پڑھتے ہوئے سنا تھا۔ واقدی کی مغازی میں ہے کہ ان کے پاس غزوہ حنین میں قبیلہ امجمع کا جھنڈا تھا جبکہ نعیم بن مسعود کے پاس ایک دوسرا جھنڈا تھا۔ اور اس میں یہ بھی ہے کہ نبی علیہ السلام نے قبلہ اشجع کو مدینہ کی طرف بھیجا تھا۔\nامام واقدی رحمہ اللہ نے زیاد بن عثمان اشجعی کے طریق سے نقل کرتے ہوئے فرمایا ہے کہ معقل نے فتح مکہ کے دن اپنی قوم کا جھنڈا اٹھایا ہوا تھا۔ پھر یہ زندہ رہے یہاں تک کہ ولید بن عقبہ نے ان کو مدینہ والوں سے یزید بن معاویہ کے حق میں بیعت لینے کے لیے بھیجا تو یہ مسلم بن عقبہ المری سے ملے اور اس سے مانوس ہو گئے اور آپس میں گفتگو شروع ہو گئی۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۲۶) استیعاب (ت: ۲۴۸۹) تجرید (۸۷/۲)"}],[8120,"§۸۱۴۰ ۔ معقل(1)\nام معقل کے بیٹے ہیں۔ ابو معقل کے حالات میں ایک حدیث کے تحت ان کا ذکر ہوا ہے۔ وہ یہ کہ رمضان المبارک میں عمرہ کرنا حج کرنے کے برابر ثواب رکھتا ہے۔\nابن مندہ نے ہشام دستوائی کے طریق سے اس کو تخریج کیا ہے کہ یحییٰ بن ابی کثیر فرماتے ہیں ام معقل اسدیہ کے بیٹے معقل نے ہمیں بتایا کہ میری والدہ نے حج کرنے کا ارادہ کیا لیکن ان کی سواری انتہائی کمزور و لاغر تھی تو میں نے نبی علیہ السلام کو بتایا تو آپ نے ارشاد فرمایا: وہ رمضان میں عمرہ کرلے اس لیے کہ رمضان میں عمرہ کرنا حج کی طرح ہے۔(2) عبدالرزاق نے اوزاعی سے تخریج کیا ہے یحییٰ بن ابی کثیر سے کہ ابو سلمہ بن عبد الرحمن معقل بن ابی معقل سے روایت کرتے ہیں کہ ام معقل نے نبی علیہ السلام کا ارشاد نقل کیا ہے۔ رمضان میں عمرہ کرنا حج کے برابر ہے۔","",{"fn":"(1) جامع المسانید (۶۸۰/۱۱)\n(2) ابوداؤد کتاب المناسک باب العمرۃ (الحدیث: ۱۹۸۸) سنن دارمی (الحدیث: ۵۱/۲) مسند احمد (الحدیث: ۴۰۵/۶)"}],[8121,"§۸۱۴۱ ۔ معقل بن ابی معقل(1)\nان کو ابن ام معقل بھی کہا جاتا ہے۔ اور یہ معقل بن ہیثم ہیں۔ ایک قول کے مطابق ابو نعیم اسدی کے بیٹے ہیں۔ اور یہ ان کے اتحادیوں میں سے ہیں۔ بقول ابن سعد(2) ان کو نبی علیہ السلام کی صحبت کا شرف حاصل ہوا ہے۔ اور ابوزید بن ثعلبہ کے آزاد کردہ غلام نے ان سے روایت کی ہے اور ابو سلمہ بن عبد الرحمن نے بھی روایت کی ہے لیکن انہوں نے نام نہیں لیا۔\nدارقطنی نے فرمایا کہ صحیح یہ ہے کہ یہ معقل بن ابی الہیم ہیں۔ اور امام ترمذی فرماتے ہیں کہ معقل بن ابی معقل یہ معقل بن ابی الہیثم ہی ہیں۔\nمیں کہتا ہوں: سنن میں ان کی دو حدیثیں ہیں ایک قول کے مطابق یہ سیدنا معاویہ کے دور خلافت میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۳۰) استیعاب (ت: ۲۴۹۲)\n(2) طبقات کبریٰ (۲۹۱/۶)"}],[8122,"§۸۱۴۲ ۔ معقل بن مقرن المزنی(1)\nکنیت ابو عمرہ۔ ابن حبان فرماتے ہیں ان کو نبی علیہ السلام کی صحبت حاصل تھی اور انہوں نے نبی علیہ السلام سے کئی احادیث روایت کی ہیں۔ امام واقدی اور ابن نمیر فرماتے ہیں کہ بنو مقرن سات آدمی تھے، سب کو صحبت نبوت کا شرف حاصل ہوا۔ اور ابوعمر(2) کا کہنا ہے کہ عربوں میں سے یہ شرف ان کے علاوہ کسی اور کو حاصل نہیں۔\nہند بن حارثہ اسلمی کے حالات میں ان کا تذکرہ ہوا ہے وہ اس بات کے خلاف ہے۔\nطبری نے بختری کے طریق سے تخریج کیا ہے۔ مختار بن عبد الرحمن بن معقل بن مقرن سے روایت کیا ہے کہ بنو مقرن کل دس آدمی تھے جن کے بارے میں یہ آیت نازل ہوئی: ﴿و من الاعراب من یومن باللہ والیوم الآخر... الخ﴾(3)\nامام بغوی رحمہ اللہ نے ابو اسحق سبیعی کے طریق سے ہمام بن حارث سے معقل بن مقرن کا ابو مسعود کے ساتھ پیش آنے والا واقعہ تخریج کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۲۸) استیعاب (ت: ۲۴۹۰) تجرید (۸۸/۲)\n(2) استیعاب (۴۸۴/۳)\n(3) سورۃ التوبہ، الآیۃ (۹۹)"}],[8123,"§۸۱۴۳ ۔ معقل بن منذر(1)\nنسب: معقل بن منذر بن سرح بن حناس بن سنان بن عبید بن عدی بن غنم انصاری، سلمی۔ ابن اسحاق(2) نے شرکاء بدر میں ان کا تذکرہ کیا۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۲۹) استیعاب (ت: ۲۴۹۱) تجرید (۸۸/۲)\n(2) السیرۃ النبویہ (۲۵۷/۲)"}],[8124,"§۸۱۴۴ ۔ معقل بن الہیثم\nیا ابوالہیثم ہیں۔ معقل بن ابی معقل کے حالات میں گزر چکا ہے۔ ابن شاہین کہتے ہیں ابن صاعد نے محمد بن یعقوب سے نقل کرتے ہوئے ہمیں بتایا کہ محمد بن فلیح نے عمرو بن یحییٰ سے روایت کیا ہے کہ معقل بن ابی الہیثم اسدی جو کہ ان کے اتحادی تھے اور نبی علیہ السلام کی صحبت بھی ان کو حاصل ہوئی (پھر حدیث ذکر کی)۔"],[8125,"§۸۱۴۵ ۔ معقل بن یسار\n(1) بن عبداللہ بن معبر بن حراق بن ابی بن کعب بن عبد ثور بن ہدمہ بن لاطم بن عثمان بن عمرو المزنی۔ اور مزینہ یہ عثمان بن عمرو کی والدہ ہیں یہ قبیلہ اسی طرف منسوب ہے۔ معقل کی کنیت کے بارے میں چند اقوال ہیں:(۱) ابوعلی(۲) ابوعبداللہ(۳) ابو یسار۔ صلح حدیبیہ سے پہلے مسلمان ہو چکے تھے اور بیعت رضوان میں شریک تھے۔ امام بغوی رحمہ اللہ فرماتے ہیں: یہی وہ معقل ہیں جن کے نام پر بصرہ میں سیدنا عمر رضی اللہ عنہ کے حکم سے ایک نہر کھودی گئی۔ یہ بصرہ کے رہائشی تھے۔ وہیں انہوں نے اپنا گھر بنایا اور سیدنا معاویہ کے دور خلافت میں وہیں انتقال فرما گئے۔(2) یونس بن عبید کے طریق سے بیان کرتے ہوئے فرماتے ہیں کہ یہاں بصرہ میں سیدنا معقل سے زیادہ اچھا اور کوئی صحابی نہیں تھا۔ احمد نے معاویہ بن قرہ کے طریق سے تخریج کیا ہے کہ معقل بن یسار نے فرمایا: شراب کی حرمت نازل ہو رہی تھی اور ہم انگور کا شربت پی رہے تھے تو میں پی بھی رہا تھا اور ساتھ ساتھ کہہ بھی رہا تھا یہ شراب کا آخری دور ہے پھر یہ مستقل حرام کر دی جائے گی۔ امام بغوی رحمہ اللہ نے ابوالاشہب کے طریق سے حسن سے روایت کی کہ عبیداللہ بن زیاد نے معقل بن یسار کی بیمار پرسی اور عیادت کی جبکہ وہ مرض الوفات میں تھے۔(3) پھر وہ حدیث ذکر کی جس میں اس حاکم و امام کی مذمت بیان کی گئی ہے جو اپنی رعایا سے خیانت و بددیانتی کرے۔ انہوں نے نبی علیہ السلام کے علاوہ نعمان بن مقرن سے بھی روایت نقل کی ہے۔ اور ان سے روایت لینے والے عمران بن حصین، عمرو بن میمون اودی، ابو عثمان نہدی، حسن بصری اور دیگر حضرات ہیں۔ بجلی کہتے ہیں ان کی کنیت ابوعلی ہے اور ان کے علاوہ کسی اور صحابی کی کنیت ابوعلی نہیں ہے۔ اور ان کی تردید اس بات سے ہوتی ہے کہ قیس بن عاصم کی کنیت ابوعلی ہے اور اسی طرح طلحہ بن عبیداللہ کی کنیت بھی ابوعلی ہے۔ یہ معقل بن یسار بصرہ میں رہتے تھے اور ان کی حدیث بخاری و مسلم کے علاوہ سنن اربعہ میں بھی موجود ہے۔\nوفات: سیدنا معاویہ کے دور خلافت کے آخر میں ان کی وفات ہوئی۔ ایک قول کے مطابق یزید کی امارت و حکومت تک زندہ رہے۔ امام بخاری نے اوسط میں ان لوگوں کی فضیلت بیان کرتے ہوئے (ان کا بھی ذکر کیا ہے) جو ۶۰ھ سے ۷۰ھ کے درمیان اس دنیا سے رخصت ہوئے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۳۱) استیعاب (ت: ۲۴۹۳) تجرید (۸۸/۲)\n(2) جامع المسانید (۶۷۸/۱۱) اسد الغابہ (۱۷۱/۶)\n(3) بخاری کتاب الاحکام باب استرعی رعیۃ (الحدیث: ۷۱۵۰) مسلم کتاب الامارۃ باب فضیلۃ الامام العادل (الحدیث: ۳۶۱) مسند احمد (الحدیث: ۷۵/۵) سنن دارمی (الحدیث: ۳۲۴/۲) دلائل النبوۃ (الحدیث: ۴۱/۹)"}],[8126,"§۸۱۴۶ ۔ معلی بن لوذان\n(1) بن زید بن حارثہ بن ثعلبہ بن عدی بن مالک۔ انصاری، خزرجی۔ ابن الاثیر(2) نے لکھا کہ ابن الکلبی نے ان کا تذکرہ کرتے ہوئے اس بات کی کوئی تصریح نہیں کہ یہ صحابی تھے یا نہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۳۲) تجرید (۸۸/۲)\n(2) اسد الغابہ (۱۷۲/۴)"}],[8127,"§۸۱۴۷ ۔ معمر بن الحارث\n(1) بن قیس بن عدی بن سہم۔ قرشی سہمی۔ ابن اسحاق(2) نے مہاجرین حبشہ میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۳۴) تجرید (۸۸/۲)\n(2) سیرۃ النبویہ (۳۲۸/۱)"}],[8128,"§۸۱۴۸ ۔ معمر بن الحارث\n(1) بن معمر بن حبیب بن وہب بن حذافہ بن جمح۔ قرشی۔ جمحی حاطب کے بھائی ہیں۔ ابن اسحاق کہتے ہیں یہ نبی علیہ السلام کے دار ارقم تشریف لانے سے پہلے ہی مسلمان ہو چکے تھے اور غزوہ بدر میں بھی شریک تھے۔(2) یہ بھی کہا جاتا ہے کہ یہ جمیل بن معمر کے والد ہیں جن کے بارے میں یہ شعر کہا گیا۔ \"میں کیسے مدینہ میں رہ سکتا ہوں۔ جبکہ جمیل بن معمر نے اس سے بدلہ لینے کا فیصلہ کر لیا ہے۔\" ایک قول یہ ہے کہ یہ جمیل، فہری کے بیٹے ہیں جن کا ذکر ان سے پہلے ہو چکا۔ اور جمحی کا انتقال سیدنا عمر رضی اللہ عنہ کے دور خلافت میں ہوا۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۳۵) استیعاب (ت: ۲۴۹۵) تجرید (۸۸/۲)\n(2) سیرۃ النبویہ (۶۸۴/۱)"}],[8129,"§۸۱۴۹ ۔ معمر بن حبیب\n(1) بن عبید بن حارث۔ انصاری۔ امام واقدی رحمہ اللہ نے شرکاء بدر میں ان کا ذکر کرتے ہوئے(2) عائشہ بنت قدامہ بن مظعون کے طریق سے تخریج کیا ہے، کہتی ہیں صفوان بن امیہ نے میرے والد سے کہا کہ بدر میں میرے والد کو تم نے پھنسایا ہے۔ تو میرے والد نے کہا: نہیں! اللہ کی قسم میں نے ایسا نہیں کیا اور اگر کیا بھی ہوتا تو میں کسی مشرک کے قتل پر عذر معذرت نہیں کرتا تو اس نے پوچھا کہ پھر وہ کون تھا؟ تو میرے والد نے بتایا کہ انصار کے نوجوان کی جماعت اس کی طرف بڑھی تھی جن میں معمر بن حبیب بن عبید بن حارث بھی تھا جو اپنی تلوار کو لہرا رہا تھا، کبھی اوپر کبھی نیچے۔ پھر واقعہ ذکر کیا۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۳۶) تجرید (۸۸/۲)\n(2) اسد الغابہ (۱۷۲/۴)"}],[8130,"§۸۱۵۰ ۔ معمر بن حزم\n(1) بن یزید بن لوذان بن عمرو بن عبد عوف بن غنم بن مالک بن نجار، انصاری۔ یہ ابو طوالہ عبداللہ بن عبد الرحمن بن حزم جو کہ مدینہ کے قاضی تھے ان کے دادا ہیں۔ لوگوں کا کہنا ہے کہ یہ عمرو بن حزم جو کہ مشہور صحابی ہیں ان کے بھائی ہیں۔ اور یہ ان دس افراد میں سے ہیں جن کو سیدنا عمر رضی اللہ عنہ نے ابو موسیٰ کے ساتھ بصرہ بھیجا تھا۔(2) بقول ابن السکن ان کو اور ان کے دو بھائی عمر اور عمارہ کو نبی علیہ السلام کی صحبت حاصل ہوئی اور اس معمر کی کوئی روایت نہیں ہے۔ ابن سعد(3) نے لکھا ہے کہ یہ بیعت رضوان اور اس کے بعد کے اہم مواقع میں شریک رہے۔ امام بغوی رحمہ اللہ نے محمد بن سعد سے یہی بات نقل کرتے ہوئے فرمایا ہے کہ میرا خیال ہے یہ عمرو بن حزم سے چھوٹے تھے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۳۷) تجرید (۸۹/۲)\n(2) اسد الغابہ (۱۷۲/۴)\n(3) طبقات کبریٰ (۲۹۳/۳)"}],[8131,"§۸۱۵۱ ۔ معمر بن رئاب\nبن حذیفہ ثقفی۔ ان کا تذکرہ وائل بن رئاب کے حالات میں آئے گا۔ ابن عساکر کہتے ہیں کہ یہ معمر بن رئاب بن حذیفہ بن مہیشم بن سعید بن سہم قرشی سہمی ہیں۔ یہ بھی کہا جاتا ہے کہ ان کے والد کا نام رائم تھا یا عتاب۔ یہ بعلبک اور دمشق کی فتح میں شریک تھے اور یہ ان لوگوں میں سے تھے جن کے نام صلح نامہ میں لکھے گئے۔ عمرو بن شعیب کہتے ہیں: رباب بن حذیفہ نے شادی کی... پھر واقعہ ذکر کیا جو وائل کے حالات میں آئے گا۔ اس بات سے معلوم ہوتا ہے کہ معمر اور ان کے بھائی صحابی ہیں۔ اس لیے کہ یہ قریش میں سے ہیں اور شام کی فتح کے موقع پر یہ کامل مرد بن چکے تھے۔"],[8132,"§۸۱۵۲ ۔ معمر بن ربیعہ\n(1) بن ہلال بن مالک، فہری۔ امام واقدی اور ابو معشر(2) نے شرکاء بدر میں ان کا ذکر کیا ہے اور ابن سعد(3) نے فرمایا: ۳۰ھ میں ان کی وفات ہوئی اور ابو عبیدہ بن جراح کی ہمشیرہ ان کے نکاح میں تھی۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۳۹) استیعاب (ت: ۲۴۹۶) تجرید (۸۹/۲)\n(2) المغازی (۱۵۷)\n(3) طبقات کبریٰ (۶۲۳/۳)"}],[8133,"§۸۱۵۳ ۔ معمر بن عبداللہ\n(1) بن ابی۔ محمد کے حالات میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۴۰) استیعاب (ت: ۲۴۹۷) تجرید (۸۹/۲)"}],[8134,"§۸۱۵۴ ۔ معمر بن عبداللہ\n(1) بن نضلہ بن نافع بن عوف بن عبید بن عویج بن عدی قرشی، عدوی۔ بہت پہلے اسلام لا چکے تھے اور حبشہ و مدینہ دونوں ہجرتوں میں شریک تھے۔ نبی کریم صلی اللہ علیہ وسلم کے ساتھ ساتھ سیدنا عمر رضی اللہ عنہ سے بھی روایت کی۔ اور ان سے روایت لینے والوں کے نام یہ ہیں۔ سعید بن مسیب، بشر بن سعید، عبد الرحمن بن جبیر، عبد الرحمن بن عقبہ جو کہ ان کا آزاد کردہ غلام تھا۔ امام احمد و حاکم نے ابن جحش کے آزاد کردہ غلام ابو کثیر کے طریق سے تخریج کیا ہے کہ محمد بن جحش سے روایت ہے کہ نبی علیہ السلام ایک دفعہ معمر کے پاس سے گزرے تو ان کی ران سے کپڑا ہٹا ہوا تھا تو نبی علیہ السلام نے ارشاد فرمایا: اے معمر اپنی ران کو ڈھانپ لو اس لیے کہ یہ ستر میں داخل ہے۔(2) امام حاکم رحمہ اللہ نے اس حدیث کو صحیح قرار دیا ہے اور ابن قانع نے ایک دوسرے طریق سے اعرج سے تخریج کیا ہے کہ معمر بن عبد اللہ بن نضلہ سے روایت ہے کہ نبی علیہ السلام ان کے پاس سے گزرے تو ان کی ران ننگی تھی۔ پھر پوری حدیث بیان کی۔ اور ابن سعد(3) فرماتے ہیں یہ بہت پہلے اسلام لا چکے تھے اور حبشہ کی طرف ہجرت کر گئے پھر مکہ واپس آگئے۔ کچھ عرصہ وہاں قیام کیا اور پھر بعد میں مدینہ کی طرف ہجرت فرمائی۔ امام مسلم رحمہ اللہ اور دیگر اصحاب سنن (سوائے امام نسائی رحمہ اللہ) نے سعید بن مسیب کے طریق سے معمر بن عبداللہ یا معمر بن عبداللہ بن نضلہ سے روایت کیا ہے فرماتے ہیں میں نے خود نبی علیہ السلام سے یہ ارشاد سنا ہے کہ گنہگار بندہ ہی ذخیرہ اندوزی کر سکتا ہے۔(4) بعض نے یہ بھی اضافہ کیا ہے کہ سعید سے کہا گیا کہ آپ بھی تو ذخیرہ اندوزی کرتے ہیں تو انہوں نے فرمایا: ابو معمر کا بیٹا ذخیرہ اندوزی کیا کرتا تھا۔ امام مسلم(5) نے بشر بن سعید کے طریق سے معمر بن عبد اللہ سے تخریج کیا ہے فرمایا کہ میں نبی علیہ السلام کا ارشاد سنتا رہتا تھا کہ غلہ غلے کے بدلہ میں برابر برابر بیچا جائے.... الخ۔ زبیر کہتے ہیں محمد بن یحییٰ نے مجھے بتایا کہ محمد بن طلحہ کہتے ہیں کہ نبی علیہ السلام نے معمر کو اس گھر میں رہنے کی اجازت دے دی جو بازار کے عامل اور متولی کے بیٹھنے کے لیے بازار میں ہوتا ہے۔ میں کہتا ہوں: یہ بھی ہو سکتا ہے یہ معمر وہی ہوں جن کا ذکر ابھی آئندہ آنے والا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۴۰) استیعاب (ت: ۲۴۹۷) تجرید (۸۹/۲)\n(2) مسند احمد (الحدیث: ۲۹۰/۵) مستدرک حاکم (الحدیث: ۱۸۰/۴) معجم الکبیر (الحدیث: ۲۴۶/۱۹) کنز العمال (الحدیث: ۲۱۶۹۷)\n(3) طبقات کبریٰ (۱۰۲/۴)\n(4) مسلم کتاب المساقات باب تحریم الاحتکار (الحدیث: ۱۲۹) ابوداؤد کتاب الاجارہ باب فی النہی عن الحکرۃ (الحدیث: ۳۴۴۷) ترمذی کتاب البیوع باب ما جاء فی الاحتکار (الحدیث: ۱۲۶۷) ابن ماجہ، کتاب التجارات باب الحکرۃ (الحدیث: ۲۱۵۴) مسند احمد (الحدیث: ۴۵۴/۳)\n(5) مسلم کتاب المساقات باب بیع الطعام مثلا بمثل (الحدیث: ۹۳)"}],[8135,"§۸۱۵۵ ۔ معمر بن عبداللہ\nبن عامر بن ایاس بن ظرب بن حارث بن فہر۔ قرشی، فہری۔ عمر بن شبہ نے صحابہ میں ان کا ذکر کیا ہے اور فرمایا انہوں نے مدینہ کو اپنا مسکن بنایا اور اسی کو اپنا گھر قرار دیا۔ ابن فتحون نے اپنی مستدرک میں ان کا ذکر کیا ہے۔ میں نے اس کی طرف پچھلے نمبر میں اشارہ کر دیا ہے۔ واللہ اعلم"],[8136,"§۸۱۵۶ ۔ معمر بن عثمان\n(1) بن عمرو بن کعب بن سعد بن تیم بن مرہ۔ قرشی، تیمی۔ فتح مکہ کے دن خود بھی مسلمان ہوئے اور ان کا بیٹا عبداللہ بھی۔(2) ابو عمر نے ان کا تذکرہ کیا۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۴۱) استیعاب (ت: ۲۴۹۸) تجرید (۸۹/۲)\n(2) استیعاب (۴۸۷/۳)"}],[8137,"§۸۱۵۷ ۔ معمر بن نضلہ\nیعقوب بن محمد زہری فرماتے ہیں کہ بنو زہرہ کے آزاد کردہ غلام محمد بن ابراہیم نے ابن لہیعہ سے روایت کرتے ہوئے ہمیں بتایا کہ یزید بن ابی حبیب معمر بن نضلہ کے آزاد کردہ غلام سے نقل کرتے ہیں۔ فرمایا کہ میں نبی علیہ السلام کے سر مبارک کے قریب کھڑا تھا اور میرے پاس نبی علیہ السلام کے سر کا حلق کرنے کے لیے استرا تھا۔ آپ نے ارشاد فرمایا: اے معمر تجھے اللہ کے رسول نے اپنے کانوں کی لو پر قدرت و اختیار دیا ہے تو میں نے عرض کیا تو اللہ تعالیٰ کا مجھ پر بہت بڑا فضل و احسان ہے۔ آپ نے فرمایا ہاں، پھر میں نے آپ کے سر کا حلق کر دیا۔(1) امام بغوی رحمہ اللہ نے اسی حدیث کو معمر بن عبداللہ بن نضلہ کے حالات میں بھی تخریج کیا ہے گویا کہ یہ کہنا چاہتے ہیں کہ یہاں مذکورہ روایت میں یہ اپنے دادا کی طرف منسوب ہیں درمیان سے باپ کی نسبت کو ہٹا دیا گیا ہے۔ اور ایک دوسرے طریق سے ابن لہیعہ سے اس کو تخریج کیا ہے یزید بن ابی حبیب عبد الرحمن بن جبیر سے نقل کرتے ہیں۔ معمر بن عبداللہ عدوی نے کہا کہ مجھے نبی علیہ السلام نے بھیجا کہ منیٰ میں سب لوگوں میں اعلان کر دو کہ کوئی بھی ایام تشریق کا روزہ نہ رکھے۔ یہ روایت اس بات کی پرزور تائید کرتی ہے کہ یہ دونوں ایک ہی شخصیت ہیں۔","",{"fn":"(1) مسند احمد (الحدیث: ۲۷۲۳۸)"}],[8138,"§۸۱۵۸ ۔ معمر\nان کی کوئی نسبت نہیں ہے۔ ابوداؤد طیالسی نے اپنی مسند میں ان کی حدیث تخریج کی ہے اور ابن قانع نے صحابہ رضی اللہ عنہم میں ان کا ذکر کرتے ہوئے مجالد کی روایت بیان کی ہے شعبی سے اور وہ معمر سے نقل کرتے ہیں۔ اور طبرانی کی(1) کسی روایت میں ہے کہ معمر نے مجھے بتایا کہ میں نبی علیہ السلام کی خدمت میں حاضر ہوا اور آپ سے یہ ارشاد سنا۔ فرمایا: تم لوگ صرف قریش کو دیکھو اور ان کی بات سنو اور ان کے کاموں کو چھوڑ دو۔ اس متن کی یہ سند محفوظ ہے: عن الشعبي عن عامر بن شهر۔ اسی طرح امام احمد رحمہ اللہ وغیرہ نے بھی شعبی کے طریق سے تخریج کیا ہے۔","",{"fn":"(1) مسند ابوداؤد طیالسی (الحدیث: ۱۱۸۵)"}],[8139,"§۸۱۵۹ ۔ معن بن الاخنس السلمی\nمیں نے ثور بن معن کے حالات میں ان کا تذکرہ کیا ہے۔"],[8140,"§۸۱۶۰ ۔ معن بن حرملہ\n(1) بن جعشم ہذلی۔ ابن یونس ان کا تذکرہ کرتے ہوئے فرماتے ہیں کہ بعض لوگ حرملہ بن معن کہتے ہیں، لیکن پہلی بات زیادہ صحیح ہے۔ یہ بھی ایک صحابی رسول ہیں اور مصر کی فتح میں شریک تھے۔","",{"fn":"(1) تجرید (۸۹/۲)"}],[8141,"§۸۱۶۱ ۔ معن بن عدی\n(1) بن جد بن عجلان، بلوی۔ انصار کے حلیف و اتحادی تھے یہ عاصم بن عدی کے بھائی ہیں جن کا تذکرہ پہلے گزر چکا ہے۔ ابن اسحاق(2) نے شرکاء اُحد میں ان کا ذکر کرتے ہوئے سیدنا عمر کی وہ لمبی حدیث ذکر کی ہے جو سقیفہ کے حالات کے بارے میں ہے اور اس میں یہ بھی ہے کہ جب وہ ابو بکر صدیق اور ابو عبیدہ کے ساتھ گئے تو فرماتے ہیں کہ ہمیں دو نیک آدمی ملے۔ امام زہری فرماتے ہیں: بقول عروہ کے ان میں سے ایک عویم بن ساعدہ تھا اور برقانی نے اپنی روایت میں یہ بھی اضافہ کیا ہے کہ دوسرا معن بن عدی تھا۔ پھر ہمیں یہ خبر ملی کہ لوگ نبی علیہ السلام پر رو رہے ہیں اور کہہ رہے ہیں اے کاش کہ ہم نبی علیہ السلام سے پہلے مر چکے ہوتے تاکہ ہم آپ کے بعد میں آنے والے فتنوں میں نہ پڑ جائیں معن کہتے ہیں مجھے یہ پسند نہیں ہے کہ میں آپ سے پہلے مر جاتا تاکہ میں آپ کی وفات کے بعد بھی ایسے ہی آپ کو سچا مانوں جیسے کہ آپ کی زندگی میں آپ کی تصدیق کرتا رہا۔(3) معن بن عدی جنگ یمامہ میں شہید ہوئے۔ یہ حدیث امام زہری سے عروہ سے مرسلا محفوظ ہے۔ سعید بن ہاشم مخزومی نے اس حدیث کو متصلا بیان کیا ہے کہ امام مالک زہری سے اور وہ سالم بن عبداللہ بن عمر سے اور وہ اپنے والد سے نقل کرتے ہیں اور ابن ابی خیثمہ نے بھی انہی سے تخریج کی ہے۔ اور یہ عروہ کی مرسل روایت ہے یہی بات زیادہ یقینی ہے۔ امام واقدی نے کتاب الردۃ میں ذکر کیا ہے کہ یہ خالد بن ولید کے ساتھ مرتدین کے خلاف جہاد و قتال میں شریک تھے اور انہوں نے ہی ان کو ہر اول دستے کے طور پر دو سو شہسوار دے کر یمامہ کی طرف بھیجا تھا۔","",{"fn":"(1) اسد (ت: ۵۰۴۵) استیعاب (ت: ۲۵۰۰) تجرید (۹۰/۲)\n(2) سیرۃ النبویہ (۴۵۶/۱)\n(3) سیرۃ النبویہ (۲۳۱/۴) اسد الغابہ (۱۷۵/۴)"}],[8142,"§۸۱۶۲ ۔ معن بن فضالہ\n(1) بن عبید بن ناقد، انصاری۔ بقول ابن کلبی ان کو نبی علیہ السلام کی صحبت کا شرف حاصل ہوا اور یہ سیدنا معاویہ کی طرف سے یمن کے گورنر تھے۔ اور ان کے والد فضالہ بن عبید کا تذکرہ فا کی بحث میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۴۶) تجرید (۹۰/۲)"}],[8143,"§۸۱۶۳ ۔ معن بن نضلہ\nبن عمرو، غفاری۔ امام بغوی رحمہ اللہ نے صحابہ میں ان کا ذکر کیا ہے جبکہ ابن حبان نے تابعین میں ان کا ذکر کیا ہے۔ ان کے والد نضلہ بن عمرو کے حالات میں عنقریب ان کی حدیث آنے والی ہے۔"],[8144,"§۸۱۶۴ ۔ معن بن یزید\n(1) بن اخنس بن حبیب بن جرہ بن زغب بن مالک بن عویف بن عصبہ بن خفاف بن امری القیس بن بہثہ بن سلیم، سلمی۔ ان کا تذکرہ صحیح بخاری(2) شریف میں ابو الجویریہ جرمی کے طریق سے موجود ہے کہ معن بن یزید فرماتے ہیں کہ میں نے اور میرے والد و دادا نے نبی علیہ السلام کے ہاتھ پر بیعت کی۔ میں آپ کے پاس ایک جھگڑا لے کر گیا آپ نے میرے حق میں فیصلہ فرمایا اور آپ نے ہی میری منگنی کروائی اور پھر شادی بھی کروائی۔ ابن یونس نے ذکر کیا ہے کہ مصر میں گئے۔ اور ان سے روایت لینے والے یہ حضرات ہیں ابو الجویریہ جرمی، سہیل بن ذراع اور عتبہ بن رافع۔ یہ کوفہ کے رہنے والے تھے پھر مصر چلے گئے وہاں سے پھر دمشق کو اپنا مسکن بنایا۔ اور ۵۲ھ میں رابطہ کی چراغاہ کا جو واقعہ ضحاک بن قیس کے ساتھ ہوا اس میں یہ بھی شریک تھے۔ ایک قول کے مطابق یہ سیدنا معاویہ رضی اللہ عنہ کے ساتھ جنگوں میں شریک رہے۔ لیث کے طریق سے یزید بن ابی حبیب تخریج کیا ہے فرمایا کہ معن بن یزید اور ان کا والد اور دادا غزوہ بدر میں شریک تھے۔ یہ صرف ایک قول ہے اس پر دوسری تائیدی دلیل نہیں ہے۔ بقول ابن عساکر فتح دمشق میں شریک تھے اور سیدنا عمر رضی اللہ عنہ کے ہاں ان کا بڑا مقام تھا۔ خلیفہ بن خیاط کہتے ہیں: ان کی کنیت ابو یزید ہے اور یہ کوفہ کے رہنے والے تھے۔ ابو زرعہ دمشقی نے شام کے باسیوں میں ان کو شمار کیا ہے اور راہط کے چراغاہ والے واقعہ میں شہید ہوئے۔ محمد بن سلام جمعی نے ذکر کیا ہے کہ معن بن یزید نے سیدنا معاویہ سے کہا۔ کسی قریشی عورت نے آپ سے زیادہ برا آدمی نہیں جنا سیدنا معاویہ نے پوچھا وہ کیوں؟ تو انہوں نے کہا کہ اس لیے کہ آپ نے لوگوں کو ظلم(3) و بربادی کا ایسا عادی بنا دیا ہے کہ چاہے وہ راستوں میں پچھاڑے ہوئے ہوں۔ اور گویا کہ میں تو ان کے ساتھ آگ کی مانند تھا جو انہوں نے آپ کے علاوہ سے مانگ لی ہو۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۴۷) استیعاب (ت: ۲۵۰۱) (۴/۴) تجرید (۹۰/۲)\n(2) بخاری کتاب الزکاۃ باب اذان تصدیق علی ابنہ (الحدیث: ۱۴۲۲)\n(3) معجم الکبیر (الحدیث: ۴۴۰/۱۹) مجمع الزوائد (الحدیث: ۳۵۵/۹)"}],[8145,"§۸۱۶۵ ۔ معوذ بن الحارث الانصاری\n(1) یہ عفراء کے بیٹے ہیں صحیح بخاری میں ان کا ذکر موجود ہے۔ صالح بن عبد الرحمن بن عوف اپنے والد سے غزوہ بدر میں ابو جہل کا واقعہ نقل کرتے ہیں اور اس میں یہ بھی ہے کہ اس کو عفراء کے دو بیٹوں معوذ(2) و معاذ نے ایسی ضرب لگائی کہ وہ ٹھنڈا ہو گیا۔ ان کے بھائی کے حالات میں گزر چکا ہے۔ ابو مسلم کی کتاب السنن میں لکھتے ہیں کہ ابو عمر حوضی نے فرمایا کہ معوذ بن حارث کو جنگ بدر میں نبی علیہ السلام کے سامنے درست کر کے کھڑا کیا گیا۔ بقول ابن عبد البر(3) یہ ابو جہل کو قتل کرنے والوں میں سے ہیں۔ پھر اس کے قتل کے بعد یہ جہاد میں مصروف رہے۔ یہاں تک کہ شہادت کے بلند مرتبہ پر فائز ہوئے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۴۹) استیعاب (ت: ۲۵۰۲) تجرید (۹۰/۲)\n(2) سیرۃ النبویہ (۷۰۲/۱) (۷۱۰/۱)\n(3) استیعاب (۴/۴)"}],[8146,"§۸۱۶۶ ۔ معوذ بن عمرو\n(1) بن جموح بن زید بن حرام۔ انصاری، سلمی۔ موسیٰ بن عقبہ نے شرکاء بدر میں ان کا ذکر کیا ہے اسی طرح ابو معشر و واقدی نے بھی ذکر کیا ہے۔ لیکن ابن اسحاق(2) نے ان کا ذکر نہیں کیا۔ ابو عمر ان کے معتقد ہیں۔ میں کہتا ہوں: ان کے بھائی معاذ بن عمرو بن جموح کا تذکرہ پہلے ہو چکا اسی طرح ان کے والد عمرو کا بھی تذکرہ گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۵۰) استیعاب (ت: ۲۵۰۳) تجرید (۹۰/۲)\n(2) استیعاب (۴/۴)"}],[8147,"§۸۱۶۷ ۔ معیقیب\n(1) ان کا نام معیقیب ہے۔ یا بقول ابن شاہین بغیر دوسری یاء کے معقیب ہے۔ ابو فاطمہ دوسی کے بیٹے ہیں۔ بنو امیہ کے اتحادی تھے۔ بہت پہلے اسلام لے آئے تھے اور تمام جنگوں میں شریک رہے۔ بقول ابن شاہین: انہیں کوڑھی کا مرض تھا۔ ابن ابی داؤد سے نقل کیا گیا ہے کہ یہ ذوادج سے تعلق رکھتے تھے یا بنی سدوس سے۔ بیعت رضوان اور اس کے بعد کی تمام جنگوں میں شریک رہے۔ ابن سعد(2) فرماتے ہیں۔ معقیب بن ابی فاطمہ بنو عبد شمس کے اتحادی تھے اور مکہ میں مسلمان ہو گئے تھے کہا جاتا ہے کہ یہ مہاجرین حبشہ میں سے ہیں۔ سیدنا عمر رضی اللہ عنہ کی طرف سے بیت المال کے نگران تھے۔ اور سیدنا عثمان رضی اللہ عنہ کی انگوٹھی کی حفاظت بھی انہی کے ذمہ تھی اور سیدنا عثمان کے ہی دور خلافت فوت ہو گئے۔ کچھ لوگوں کا کہنا ہے کہ یہ چالیس ہجری کے بعد تک زندہ رہے۔ انہوں نے نبی علیہ السلام سے روایت کی اور ان سے روایت کرنے والے ان کے دو بیٹے محمد اور حارث۔ ان کے پوتے ایاس بن حارث اور ابو سلمہ بن عبد الرحمن بن عوف ہیں۔ ابو عمر کہتے ہیں ان کو کوڑھ یا برس کی بیماری تھی تو سیدنا عمر رضی اللہ عنہ کے حکم سے ان کا علاج کیا گیا یہاں تک کہ یہ ٹھیک ہو گئے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۵۱) استیعاب (ت: ۲۵۸۸) تجرید (۹۰/۲)\n(2) طبقات کبریٰ (۸۶/۴)"}],[8148,"§۸۱۶۸ ۔ معیقیب بن معرض الیمامی\n(1) معرض کے تحت گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۵۳) استیعاب (ت: ۲۵۸۹) تجرید (۹۰/۲)"}],[8149,"§۸۱۶۹ ۔ مغفل بن ضرار الغطفانی\nوہی الشماخ شاعر، جن کا تذکرہ حرف شین میں ہوا ہے۔"],[8150,"§۸۱۷۰ ۔ مغفل بن عبدنہم\n(1) بن عفیف المزنی۔ مشہور صحابی عبد اللہ بن مغفل کے والد۔ عبد اللہ ذی النجادین کے چچا، فتح مکہ کے سال مسلمانوں کے مکہ داخل ہونے سے پہلے فوت ہو گئے۔ ابو جعفر طبری نے یہ بات ذکر کی ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۵۴) تجرید (۹۰/۲)"}],[8151,"§۸۱۷۱ ۔ مغلس البکری\n(1) ابن مندہ نے ان کا ذکر کیا ہے اور طریق رکنہ بنت مغلس، بحوالہ اپنے والد روایت کی ہے کہ وہ نبی علیہ السلام کے پاس آئے۔ اس کی سند میں عبد الرحمن بن عمرو بن جبلہ انتہائی کمزور راوی ہے۔","",{"fn":"(1) اسد الغابہ (۱۷۸/۴)"}],[8152,"§۸۱۷۲ ۔ مغیث بن عبید البلوی\nمغیث میں ان کا ذکر ہوا ہے۔"],[8153,"§۸۱۷۳ ۔ مغیث بن عمرو السلمی\n(1) مغیث میں تذکرہ ہو چکا ہے۔","",{"fn":"(1) تجرید (۹۱/۲)"}],[8154,"§۸۱۷۴ ۔ مغیث الغنوی\n(1) ابن اسکن نے ان کا ذکر کیا ہے کہ ان کی حدیث عبداللہ بن محمد بن یزید بن البراء الغنوی نے عن ابن جدعان عن ابیہ مغیث کی سند سے نقل کی ہے کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا تو میں نے آپ کے لیے ایک اونٹنی کا دودھ دوہا، مجھ سے ایک مسکین نے پینے کے لیے مانگا مجھے اس پر رحم آ گیا تو وہ دودھ میں نے اسے پلا دیا پھر جو بچ گیا وہ آپ علیہ السلام کی خدمت میں لے آیا آپ نے خود بھی نوش فرمایا اور اپنے صحابہ رضی اللہ عنہم کو بھی پلایا۔ ابن مندہ کہتے ہیں: مغیث، بقول بعض: مغیث کو نبی صلی اللہ علیہ وسلم نے کسی مہم پر روانہ فرمایا تھا۔ ان کی حدیث محمد بن یزید غنوی نے نقل کی ہے ابن مندہ نے براء کا ذکر نہیں کیا۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۵۸) استیعاب (ت: ۲۵۰۷) تجرید (۹۱/۲)"}],[8155,"§۸۱۷۵ ۔ مغیث\n(1) بریرہ کے خاوند، ابو احمد بن جحش اسدی کے مولا۔ صحیح بخاری(2) میں بطریق خالد الحذاء عن عکرمہ ان کا ذکر ثابت ہے کہ بریرہ کے خاوند جن کا نام مغیث تھا غلام تھے ایسا لگتا ہے اب بھی میں انہیں اس کے پیچھے گھومتے، روتے دیکھ رہا ہوں۔ ان کے آنسو ان کی داڑھی پر بہہ رہے تھے تو نبی صلی اللہ علیہ وسلم نے فرمایا: کیا تمہیں مغیث کی بریرہ سے محبت اور بریرہ کی اس سے نفرت پر تعجب نہیں ہوتا.... بغوی نے بطریق قتادہ عن عکرمہ یہی الفاظ نقل کیے ہیں۔ حدیث عائشہ رضی اللہ عنہا میں بھی ان کا نام آیا ہے۔ چنانچہ ترمذی بطریق سفیان ثوری عن منصور عن ابراہیم عن الاسود بحوالہ عائشہ رضی اللہ عنہا روایت کرتے ہیں کہ آپ نے بریرہ کو خریدنا چاہا، ان کے خاوند کا نام مغیث تھا اور وہ غلام تھے تو رسول اللہ صلی اللہ علیہ وسلم نے (آزادی کے بعد) بریرہ کو مغیث کے ساتھ رہنے یا جدائی اختیار کرنے کا اختیار دیا تو انہوں نے جدائی کو اختیار کر لیا۔ وہ ان سے بے حد محبت کرتے تھے وہ مدینہ کی گلیوں میں روتے پھرتے تھے۔ رسول اللہ صلی اللہ علیہ وسلم کے ذریعے سفارش کروائی تو بریرہ عرض کرنے لگیں: اللہ کے رسول! کیا آپ کا حکم ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: نہیں! بلکہ سفارش کرتا ہوں۔ وہ عرض کرنے لگیں: میں اسے نہیں چاہتی۔ ان شاء اللہ تعالیٰ اس واقعے کی تفصیل سیدہ بریرہ کے حالات (ت ۱۰۹۲۵ حصہ خواتین) میں ہو گی۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۵۵) تجرید (۹۰/۲)\n(2) بخاری کتاب الطلاق باب شفاعۃ النبی صلی اللہ علیہ وسلم فی زوج بریرہ (۵۲۸۳)"}],[8156,"§۸۱۷۶ ۔ مغیث\nمولا مالک بن اوس اسلمی، اپنے مولا کے ساتھ ان کا ذکر ہو چکا ہے۔"],[8157,"§۸۱۷۷ ۔ مغیث اسلمی\nدوسرے ہیں۔ کنیت ابو مروان تھی کنیتوں میں ان کی حدیث بیان ہو گی (ت ۱۰۵۲۰ حصہ رجال)۔"],[8158,"§۸۱۷۸ ۔ المغیرہ بن الاخنس\n(1) بن شریق الثقفی بنی زہرہ کے حلیف۔ ان کے والد کے ساتھ ان کا نسب بیان ہوا ہے۔ ابو عمر نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ اور زبیر بن بکار کی کتاب «الموفقیات» میں ہے کہ مغیرہ بن اخنس نے زبیر بن عوام رضی اللہ عنہ کی ہجو کی تو منذر بن زبیر نے ان پر حملہ کر دیا اور ان کے پاؤں پر تلوار ماری۔ سیدنا عثمان رضی اللہ عنہ کو معلوم ہوا تو آپ نے ناراضگی کا اظہار فرمایا اور کھڑے ہو کر خطاب کیا.... پھر ایک واقعہ نقل کیا۔ مرزبان کا قول ہے: سیدنا عثمان رضی اللہ عنہ کے ساتھ «یوم الدار» کے واقعہ میں شہید ہوئے۔ وہی کہتے ہیں: «مجھے سیلاب کی طرح وہ غارت گری بھولی نہیں جس کا اعداد و شمار رات تک نہیں ختم ہوتا تھا»۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۵۹) استیعاب (ت: ۲۵۰۸) تجرید (۹۱/۲)"}],[8159,"§۸۱۷۹ ۔ المغیرہ بن الحارث\n(1) بن عبد المطلب۔ ابو سفیان ہاشمی۔ چونکہ یہ کنیت سے مشہور ہیں اس لیے وہاں ان کا تذکرہ ہو گا۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۶۱) استیعاب (ت: ۲۵۱۰) تجرید (۹۱/۲)"}],[8160,"§۸۱۸۰ ۔ المغیرہ بن الحارث\nبن عبد المطلب۔ بقول ابو عمر صحابی ہیں، صحیح قول کے مطابق ابو سفیان بن حارث کے بھائی ہیں۔ بقول: ابو سفیان ہی مغیرہ ہیں، جو صحیح نہیں۔ ابن الاثیر نے اس کا تعاقب کرتے ہوئے لکھا ہے۔ اہل نسب جیسے زبیر، ابن کلبی وغیرہ ہیں انہوں نے جزم و یقین سے لکھا ہے کہ ابو سفیان کا نام مغیرہ ہے۔ انہوں نے ان کا مغیرہ نامی کوئی بھائی ذکر نہیں کیا۔ جس کی کنیت ابو سفیان ہو، اور یہی بات بغوی نے اعتماد سے نقل ہے کہ ابو سفیان کا نام مغیرہ بن حارث ہے۔ واللہ اعلم"],[8161,"§۸۱۸۱ ۔ المغیرہ بن رؤیبہ\n(1) ابن قانع نے ان کا ذکر کیا اور بطریق سلمہ بن صالح عن ابی اسحاق بحوالہ ان کے روایت کی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: «بطھاء» میں دو رکعتیں پڑھا کرو۔ ابن فحون(2) نے اپنے استدراک میں ان کا ذکر کیا ہے کہ احتمال ہے یہ عمارہ بن رویبہ کے بھائی ہیں۔","",{"fn":"(1) تجرید (۹۲/۲)\n(2) مشکاۃ المصابیح (۵۲۶۵)"}],[8162,"§۸۱۸۲ ۔ المغیرہ بن شعبہ\n(1) بن ابی عامر بن مسعود بن معتب بن مالک بن کعب بن عمرو بن سعد بن عوف بن قیس ثقفی۔ ابو عیسیٰ یا ابو محمد۔ بقول طبری: ابو عبد اللہ کنیت کرتے تھے۔ لکھتے ہیں: گٹھے بدن والے، موٹے بازوؤں، کشادہ سینے والے، سرخ گنگھریالے بالوں والے تھے جن میں مانگ نہیں نکالتے تھے۔ عمرہ الحدیبیہ(2) سے پہلے اسلام لائے۔ اس میں اور بیعت رضوان میں شرکت کی جس میں ان کا ذکر ہے۔ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں۔ ان سے ان کی اولاد میں سے عروہ، عقار، حمزہ اور ان کا مولا روایت کرتا ہے۔ اور یہ اضافہ نقل کیا ہے ان کے والد کا چچا زاد بھائی حسن بن حبہ اور صحابہ رضی اللہ عنہم میں سے مسور بن مخرمہ روایت کرتے ہیں۔ اور مخضرمین اور ان کے بعد والے لوگوں میں سے قیس بن ابی حازم، مسروق، قبیصہ بن ذؤیب، نافع بن جبیر، بکر بن عبد اللہ المزنی، اسود بن بلال، زیادہ بن علاقہ اور دوسرے لوگ روایت کرتے ہیں۔\nابن سعد(3) لکھتے ہیں: انہیں مغیرہ الرائے کہا جاتا تھا۔ جنگ یمامہ، فتوحات شام و عراق میں شریک ہوئے۔ شعبی فرماتے ہیں: عرب کے زیرک و ہوشیار افراد میں سے تھے۔ یہی زہری کا قول ہے۔ قبیصہ بن جابر کا قول ہے: میں سیدنا مغیرہ رضی اللہ عنہ کے ساتھ رہا۔ ان کی ذہانت کا یہ عالم تھا کہ اگر کوئی ایسا شہر ہوتا جس کے آٹھ دروازے ہوتے اور ان میں سے ایک دروازے سے حیلہ بازی سے باہر نکلا جاتا تو مغیرہ اس سے سارے دروازوں سے نقل کر دکھا دیتے۔ سیدنا عمر رضی اللہ عنہ نے انہیں بصرہ کا گورنر بنایا پھر انہوں نے میدان، ہمدان اور کئی علاقے فتح کیے یہاں تک کہ جب ان کے خلاف سیدنا ابو بکرہ اور ان کے ساتھیوں نے گواہی دی تو انہیں معزول کر دیا۔(4)\nبغوی کا قول ہے: انہوں نے بصرہ میں سب سے پہلے دیوان (رجسٹریشن) مقرر کیا۔ ابن حبان لکھتے ہیں: سب سے پہلے ان کے لیے گورنری کو تسلیم کیا گیا۔ پھر سیدنا عمر رضی اللہ عنہ نے انہیں کوفہ کا گورنر بنا دیا۔ بعد میں سیدنا عثمان رضی اللہ عنہ نے انہیں برقرار رکھا۔ پھر انہیں معزول کر دیا۔ جب سیدنا عثمان رضی اللہ عنہ شہید ہوئے تو جنگوں سے کنارہ کش رہے۔ بعد میں حکمین کے ساتھ حاضر ہوئے۔ پھر جب سب لوگوں نے امیر معاویہ کو خلیفہ تسلیم کر لیا تو ان سے بیعت کر لی تو انہوں نے انہیں بعد میں کوفہ کا گورنر بنا دیا۔ جس پر تا دم زیست براجمان رہے اور اکثر کے نزدیک پچاس ۵۰ھ میں وفات ہوئی۔ جس پر خطیب نے اجماع نقل کیا ہے۔ بقول بعض: ایک سال پہلے اور ایک قول کے مطابق ایک سال بعد فوت ہوئے۔\nطبری لکھتے ہیں: وہ جس مشکل میں پڑتے اس کا حل تلاش کر لیتے اور جو دو کام ان پر مشتبہ یا گڈمڈ ہو جاتے تو ایک میں اپنی رائے ظاہر کر دیتے۔ طبری ہی کا قول ہے: وہ طائف میں ثقیف کا بت گرانے میں ابو سفیان (صخر بن حرب امیر معاویہ کے والد) کے ساتھ تھے۔ سیدنا صدیق اکبر رضی اللہ عنہ نے انہیں اہل انجیر کی جانب بھیجا تھا، جنگ یرموک میں ان کی آنکھ شہید ہوئی۔ پھر رستم کی جانب سیدنا سعد کے قاصد بن کر گئے۔ صحیح بخاری رحمہ اللہ میں اہل فارس کی جنگ میں نعمان بن مقرن کے واقعہ میں ان کا ذکر ہے کہ یہ نعمان بن مقرن کی طرف سے امریٰ القیس کی جانب اپیلچی بن کر گئے اور ان فتوحات میں شریک ہوئے۔ عبد اللہ بن بدیل بن ورقاء کے حالات میں ان کا ذکر ہوا ہے۔ بغوی کی روایت ہے مطلب بن حنطب کا قول ہے: سیدنا مغیرہ رضی اللہ عنہ نے (بطور مزاح) فرمایا: میں وہ شخص ہوں جس نے سب سے پہلے اسلام میں رشوت دی، میں یرفا دربان عمر رضی اللہ عنہ کے پاس آیا میں اس کے پاس بیٹھا کرتا تھا (یرفا کے حالات کے لیے دیکھیں عنوان نمبر ۹۳۹۱)۔ میں نے اس سے کہا: میرے عمامہ (پگڑی) لے کر باندھ لو میرے پاس دوسرا ہے۔ وہ چونکہ مجھ سے مانوس تھا اس لیے مجھے دروازے کی اندرونی جانب بیٹھنے کی اجازت دے دیتا۔ چنانچہ میں آکر دوپہر کے وقت اندرونی جانب بیٹھ جاتا، ہر گزرنے والا یہ سمجھتا وہ مغیرہ کا سیدنا عمر رضی اللہ عنہ کے ہاں بڑا مقام ہے وہ ایسے وقت آتا ہے جس میں کوئی اور نہیں آتا۔ بغوی نے بطریق زید بن اسلم روایت کی ہے کہ سیدنا مغیرہ رضی اللہ عنہ نے سیدنا عمر رضی اللہ عنہ سے اجازت چاہی۔ آپ نے پوچھا: کون ہے؟ انہوں نے کہا: ابو عیسیٰ۔ آپ نے فرمایا: ابو عیسیٰ کون ہے؟ کہا: مغیرہ بن شعبہ۔ سیدنا عمر رضی اللہ عنہ نے فرمایا: بھلا عیسیٰ علیہ السلام کا کوئی باپ تھا؟ صحابہ رضی اللہ عنہم میں سے کسی نے کہا کہ حضور نبی کریم صلی اللہ علیہ وسلم نے ان کی یہ کنیت رکھی ہے۔ آپ نے فرمایا: نبی صلی اللہ علیہ وسلم تو مغفور و معصوم ہیں، ہمیں پتہ ہے ہمارے ساتھ کیا ہوتا ہے؟ اور ان کی کنیت ابو عبد اللہ رکھ دی۔\nاور بغوی نے بطریق ہشام بن سعد عن زید بن اسلم عن ابیہ روایت کی ہے کہ سیدنا عمر رضی اللہ عنہ نے مغیرہ کو بحرین کا گورنر بنایا تو وہاں کے لوگوں نے انہیں ناپسند سمجھا اور آپ سے شکایت کر دی۔ آپ نے انہیں معزول کر دیا۔ انہیں یہ خطرہ ہوا کہ کہیں واپس نہ آجائیں۔ اس لیے ایک سوداگر کے پاس ایک لاکھ جمع کرا دیے، سوداگر نے وہ ایک لاکھ سیدنا عمر رضی اللہ عنہ کے پاس پیش کر دیے اور کہنے لگا: یہ مغیرہ کی خیانت کا مال ہے، جو انہوں نے میرے پاس امانت رکھے تھے۔ آپ نے انہیں بلا بھیجا اور ان سے دریافت کیا۔ انہوں نے کہا: یہ جھوٹ کہتا ہے۔ وہ تو دو لاکھ تھے۔ سیدنا عمر رضی اللہ عنہ نے فرمایا: تم نے ایسا کیوں کیا ہے؟ آپ نے کہا: میرے اہل و عیال زیادہ تھے۔ سوداگر کو بڑی پیشیمانی ہوئی۔ اس نے قسمیں کھائیں اور یقین سے کہنے لگا: انہوں نے میرے پاس کوئی تھوڑا بہت مال نہیں رکھا۔ سیدنا عمر رضی اللہ عنہ نے سیدنا مغیرہ سے کہا: تم نے ایسا کیوں کیا؟ انہوں نے کہا: اس نے میرے ذمہ جھوٹ گھڑا تو میں نے بھی چاہا کہ اسے سزا کروں۔\nابن شاہین نے بطریق کثیر بن زید عن المطلب جو ابن حطب ہیں۔ روایت کی ہے سیدنا مغیرہ نے فرمایا: میں آتا اور آکر سیدنا عمر رضی اللہ عنہ کے دروازے پر سیدنا عمر رضی اللہ عنہ کی اجازت لینے کے لیے بیٹھ جاتا۔ ایک دفعہ میں نے یرفا، دربان سیدنا عمر رضی اللہ عنہ سے کہا: میرا یہ عمامہ لے لو اور اسے باندھ لو۔ کیونکہ میرے پاس دوسرا ہے تو وہ مجھے دروازے کے اندر بیٹھنے کی اجازت دے دیتا۔ ابن سعد لکھتے ہیں، آپ طویل اور ایک چشم گل تھے۔ جنگ یرموک میں ان کی آنکھ شہید ہوئی۔ سرخ بال، دونوں ہونٹ سکڑے ہوئے تھے۔ سر بڑا تھا، موٹے بازو تھے، سینہ چوڑا تھا، آپ کو مغیرہ الرائے کہا جاتا تھا۔\nامام بخاری رحمہ اللہ(5) لکھتے ہیں: ابو نعیم عن زکریا عن الشعبی روایت کرتے ہیں: چون ۵۳ھ رجب بدھ کے دن سورج گرہن ہوا، تو مغیرہ کھڑے ہوئے، میں وہاں موجود تھا.... پھر ایک واقعہ ذکر کیا، جبکہ درست انچاس ۴۹ھ ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۶۴) استیعاب (ت: ۲۵۱۲) تجرید (۹۱/۲)\n(2) السیرۃ النبویۃ (۳۱۲/۱)\n(3) الطبقات الکبریٰ (۲۸۴/۲)\n(4) استیعاب (۷/۴)\n(5) التاریخ الکبیر (۴/۳۱۶)"}],[8163,"§۸۱۸۳ ۔ مغیرہ بن نوفل\n(1) بن حارث بن عبد المطلب بن ہاشم ہاشمی۔ بقول ابو عمر:(2) ہجرت سے پہلے پیدا ہوئے۔ بقول بعض: ہجرت سے چار سال بعد پیدا ہوئے۔ ابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق علی بن عیسیٰ ہاشمی عن سلیمان بن نوفل عن عبد الملک بن نوفل بن مغیرہ بن نوفل بن حارث عن ابیہ عن جدہ المغیرہ روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «جو انصاف کی تعریف اور ظلم کی مذمت نہ کرے تو (گویا) اس نے اللہ تعالیٰ کو برائی کے لیے للکارا ہے»۔ بقول ابن شاہین:(3) غریب حدیث ہے مجھے اس کے علاوہ مغیرہ کی کوئی روایت معلوم نہیں۔ ابو احمد عسکری نے یقین سے لکھا ہے: یہ حدیث مرسل ہے۔\nابن حبان ثقات التابعین میں ان کا ذکر کیا ہے۔ ابو عمر کی بات راجح ہے اور یہ حدیث ثابت نہیں۔ یہ مغیرہ خلافت عثمانی میں مدینہ کے قاضی تھے، پھر سیدنا علی رضی اللہ عنہ کے ساتھ ان کی جنگی مہمات میں شریک ہوئے۔ انہوں نے ہی ابن ملجم پر چادر ڈالی تھی جب اس نے سیدنا علی رضی اللہ عنہ پر وار کیا تھا تو انہوں نے اسے پکڑ لیا اور زمین پر گرا کر اس سے تلوار چھین لی اور سیدنا علی رضی اللہ عنہ کی وفات تک اسے قید رکھا۔(4)\nزبیر بن بکار کا قول ہے: امیر معاویہ نے امامہ بنت ابی العاص بن الربیع کی طرف سیدنا علی رضی اللہ عنہ کی وفات کے بعد نکاح کا پیغام بھیجا تو انہوں نے اپنا اختیار مغیرہ بن نوفل کو دے دیا جب انہیں پوری طرح بھروسہ ہو گیا تو اپنے ساتھ ان کی شادی کر لی۔ چنانچہ پھر انہی کے ہاں وہ فوت ہو گئیں۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۶۵) استیعاب (ت: ۲۵۱۳) تجرید (۹۱/۲)\n(2) استیعاب (۹/۴)\n(3) جامع المسانید (۵/۱۲) اسد الغابہ (۱۸۲/۴)\n(4) جامع المسانید (۵/۱۲) اسد الغابہ (۱۸۲/۴)"}],[8164,"§۸۱۸۴ ۔ مغیرہ المخزومی\nعہد نبی صلی اللہ علیہ وسلم میں فوت ہوئے۔ ان کے عقد میں بنت عائذ بن نعیم بن عبد اللہ بن نجام عدویہ تھیں تو ان کی والدہ رسول اللہ صلی اللہ علیہ وسلم سے فتویٰ طلب کرنے آئیں کہ ان کی بیٹی (جو ایام بیوگی، عدت گزار رہی ہے) کی آنکھوں میں تکلیف ہے، کیا وہ سرمہ لگا سکتی ہے؟ وہ حدیث صحیحین میں حدیث ام سلمہ رضی اللہ عنہا سے مروی ہے۔ صرف اس میں خاوند کا نام نہیں، نہ فتویٰ طلب کرنے والی خاتون اور نہ اس کی بیٹی کا تذکرہ ہے۔ ابن وہب نے اپنے موطا میں اس خاتون کا نام لیا ہے کہ ابن ابی عمیر عن محمد بن عبد الرحمن عن القاسم بن محمد عن زینب بنت ابی اسامہ کی سند سے بیان کیا کہ ان کی والدہ نے انہیں یہ روایت بیان کی۔ اس روایت کو قاضی اسماعیل نے «احکام القرآن» میں عن ابی ثابت عن ابن وہب انہی الفاظ میں نقل کیا ہے۔ ابن فحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[8165,"§۸۱۸۵ ۔ المغترب\nوہی اسود بن ربیعہ جن کا تذکرہ پہلے ہوا ہے۔"],[8166,"§۸۱۸۶ ۔ المقداد بن الاسود الکندی\n(1) ابن عمرو بن ثعلبہ بن مالک بن ربیعہ بن عامر بن مطرود البہرانی۔ بقول بعض: الحضرمی۔ ابن کلبی کا قول ہے: عمرو بن ثعلبہ سے اپنی قوم کا کوئی خون ہو گیا تھا تو وہ حضرموت پناہ گزیں ہو گئے۔ وہاں کندہ سے معاہدہ حلف کر لیا، جس کی بنا پر انہیں کندی کہا جانے لگا۔ وہیں ایک خاتون سے شادی کر لی جس سے مقداد پیدا ہوئے۔ جب مقداد جوان ہوئے تو ان میں اور ابو شمر بن حجر کندی کے درمیان جھگڑا ہو گیا۔ انہوں نے اس کا پاؤں تلوار سے کاٹ دیا اور مکہ بھاگ آئے۔ یہاں اسود بن عبد یغوث زہری(2) کے حلیف بن گئے۔ اور اپنے والد کو خط بھیجا تو وہ بھی آ گئے۔ اسود نے مقداد کو بیٹا بنا لیا تھا جس کی وجہ سے انہیں مقداد بن الاسود کہا جانے لگا، اور یہی ان کا نام مشہور ہو گیا۔ پھر جب یہ آیت ﴿ادعوہم لآبائہم﴾(3) نازل ہوئی تو انہیں مقداد بن عمرو کہا جاتا، لیکن شہرت ابن الاسود سے تھی۔ مقداد رضی اللہ عنہ کی کنیت ابو الاسود تھی، بقول بعض: ابو عمر یا ابو سعید کنیت تھی۔ قدیم الاسلام ہیں۔ ضباعہ بنت زبیر بن عبد المطلب نبی صلی اللہ علیہ وسلم کی چچا زاد بہن سے شادی کی، دو ہجرتیں کیں، بدر اور بعد کے معرکوں میں شریک رہے۔ بدر کے روز صرف وہی گھڑ سوار تھے یہاں تک کہ ان کے علاوہ کسی کا بدر میں گھڑ سوار ہونا ثابت نہیں۔\nزر بن حبیش رحمہ اللہ عن عبد اللہ بن مسعود رضی اللہ عنہ سے روایت کرتے ہیں، فرمایا: سب سے پہلے سات افراد نے اسلام ظاہر کیا، اُن میں ان کا نام بھی لیا۔ طارق بن شہاب بحوالہ ابن مسعود رضی اللہ عنہ روایت کرتے ہیں: ایک دفعہ میں مقداد کے پاس تھا مجھے ان کی جگہ ہونا اس کے برابر کی چیزوں سے زیادہ پسند تھا۔ بغوی روایت کرتے ہیں: سب سے پہلے مقداد نے گھوڑے پر بیٹھ کر اللہ کی راہ میں جنگ کی۔ کریمہ بنت مقداد بحوالہ اپنے والد روایت کرتی ہیں «میں اپنے گھوڑے سبحہ پر بیٹھ کر بدر میں شریک ہوا»۔ اور بطریق یعقوب بن سلیمان ثابت بنانی سے مروی ہے کہ مقداد اور عبد الرحمن بن عوف دونوں بیٹھے ہوئے تھے، تو مالک ان سے کہنے لگے: تم شادی نہیں کرتے؟ انہوں نے کہہ دیا: تم اپنی بیٹی کا رشتہ مجھے دے دو۔ جس پر عبد الرحمن غصے میں آگئے اور انہیں سخت کہا۔ انہوں نے نبی صلی اللہ علیہ وسلم سے اس کی شکایت کر دی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: میں تمہاری شادی کرتا ہوں۔ چنانچہ آپ نے اپنی چچا زاد ضباعہ بنت زبیر بن عبد المطلب سے ان کی شادی کر دی۔\nمدائنی سے مروی ہے:(4) مقداد دراز قد، گندم گوں، گھنے بالوں، سرخ آنکھوں والے تھے۔ داڑھی پر زرد خضاب لگاتے تھے۔ یعقوب بن حفیان اور ابن شاہین ان کے طریق کریمہ بنت مقداد تک کی اپنی سند سے بیان کرتے ہیں کہ مقداد بڑے شکم والے تھے، ان کا ایک رومی خادم تھا کہنے لگا: میں آپ کا پیٹ چاک کر کے اس میں سے چربی نکال دوں تاکہ یہ ہلکا ہو جائے؟ چنانچہ اس نے آپ کا پیٹ چاک کر کے دوبارہ سی دیا جس سے سیدنا مقداد فوت ہو گئے۔ تو غلام بھاگ گیا۔(5)\nابو ربیعہ الایادی عن عبد اللہ بن بریدہ عن ابیہ نبی صلی اللہ علیہ وسلم کے حوالہ سے روایت کرتے ہیں کہ اللہ تعالیٰ نے مجھے چار افراد سے محبت کرنے کا حکم دیا ہے اور بتایا ہے کہ اللہ بھی ان سے محبت کرتا ہے۔ علی والمقداد وابوذر اور سلمان فارسی۔(6) ترمذی، ابن ماجہ اس کی سند حسن ہے۔ سیدنا مقداد نے نبی صلی اللہ علیہ وسلم سے کئی احادیث کی روایت کی ہے۔ ان سے سیدنا علی، انس، عبید اللہ بن عدی بن الخیار، ہمام بن حارث، عبد الرحمن بن ابی لیلیٰ وغیرہ حضرات روایت کرتے ہیں۔ اس پر سب کا اتفاق ہے کہ ان کا انتقال خلافت عثمانی میں ۳۳ھ میں ہوا۔ اس وقت ستر برس کا سن تھا۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۶۹) استیعاب (ت: ۲۵۹۰) تجرید (۹۲/۲)\n(2) المعجم الکبیر (۲۰/۵۸) مجمع الزوائد (۹/۳۰۷)\n(3) سورۃ الاحزاب آیت (۵)\n(4) المعجم الکبیر (۲۰/۲۲۵)\n(5) اسد الغابہ (۱۸۴/۴)\n(6) ترمذی کتاب المناقب (۳۷۱۸) ابن ماجہ المقدمۃ (۱۴۹) المستدرک (۱۳۰/۳)"}],[8167,"§۸۱۸۷ ۔ المقداد بن معدیکرب\n(1) بن عمرو بن یزید بن معدیکرب۔ ابو کریمہ۔ بقول بعض: ابو یحییٰ کنیت تھی۔ حضور نبی کریم صلی اللہ علیہ وسلم کا ساتھ نصیب ہوا۔ اور آپ سے چند ایک احادیث روایت کیں۔ سیدنا خالد بن الولید، معاذ، ابو ایوب سے بھی روایت کی ہے۔ حمص فروش ہوئے۔ ان سے ان کا بیٹا یحییٰ، پوتا صالح بن یحییٰ، خالد بن معدان، حبیب بن عبید، یحییٰ بن جابر طائی، شعبی، شرح بن عبید اور عبد الرحمن بن ابی عوف وغیرہ روایت کرتے ہیں۔ ابن سعد اہل شام کے چھٹے طبقہ میں ان کا ذکر کرتے ہیں کہ ۸۸ھ میں فوت ہوئے۔ اکانوے(۹۱) کا سن تھا۔(2) عثمان کا قول ہے: ۸۳ھ۔ بقول بعض: ۸۷ھ میں فوت ہوئے۔ بغوی کی بطریق ابی یحییٰ سلیم کلاعی کی روایت ہے کہ ہم نے مقداد بن معدیکرب سے کہا: ابو کریمہ! لوگوں کا گمان ہے آپ نے رسول اللہ صلی اللہ علیہ وسلم کو نہیں دیکھا۔ آپ نے فرمایا: کیوں نہیں، اللہ کی قسم! میں نے آپ کو دیکھا ہے۔ ایک دفعہ میں اپنے چچا کے ساتھ جا رہا تھا آپ نے پیار سے میرے کان کی لو پکڑی، پھر میرے چچا سے فرمایا: تمہارا کیا خیال ہے یہ اسے یاد رکھے گا؟ میں نے سنا آپ صلی اللہ علیہ وسلم فرما رہے تھے: «قیامت کے دن ناتمام بچے سے لے کر بوڑھے کھوسٹ تک کی عمر کے لوگوں کو تیں(۳۰) سالہ کر کے اٹھایا جائے گا۔ ان میں سے ایمان والے حضرت آدم علیہ السلام کے قد والے ہوں گے....»۔ (الحدیث)(3) اور بطریق شعیب عن المقداد ابی کریمہ (جو ایک صحابی رسول صلی اللہ علیہ وسلم ہیں) مروی ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۷۰) استیعاب (ت: ۲۵۹۱) تجرید (۹۲/۲)\n(2) المعجم الکبیر (۲۰/۲۶۲) جامع المسانید (۲۹/۱۲) اسد الغابہ (۱۸۶/۴)\n(3) کنز العمال (۳۹۳۸۴) تہذیب تاریخ دمشق (۱۷/۱)"}],[8168,"§۸۱۸۸ ۔ مقسم بن بجرہ\n(1) ابن حارثہ بن قشیرہ الکندی ثم التجبی النخعی۔ ابو سعید بن یونس نے ان کا ذکر کیا ہے کہ حیات نبی صلی اللہ علیہ وسلم میں اسلام لائے اور یمن میں سیدنا معاذ کے ہاتھ پر بیعت کی۔ بقول بعض: صحابی ہیں۔ فتح مصر میں شریک ہوئے۔ اور زیاد بن لبید کے ساتھ مرقدوں سے شریک ایک کارزار ہوئے۔ سیدنا علی رضی اللہ عنہ بن ابی طالب سے روایت کی ہے پھر بطریق علی بن رباح روایت کی ہے۔ فرمایا: ہم لوگ غزوہ بحرین میں تھے۔ فضالہ بن عبید ہمارے امیر تھے۔ میں دشمن کے لیے بد دعا کرنے لگا: «اے اللہ! انہیں ہلاک کر، ان کی جڑ کاٹ دے»۔ تو مقسم بن بجرہ نے میرے کندھے پر ہاتھ مار کر کہا: ارے ناداں یوں کہو: اے اللہ! ہمیں ان پر غلبہ عطا فرما، اگر یہی نہ رہے تو ہمیں مال غنیمت کہاں سے ملے گا؟","",{"fn":"(1) تجرید (۹۲/۲)"}],[8169,"§۸۱۸۹ ۔ مقسم الفارسی\nطبرانی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور ابن فحون نے اپنے استدراک میں۔"],[8170,"§۸۱۹۰ ۔ مقسم (دوسرے)\nمقتب میں تذکرہ ہوا ہے۔"],[8171,"§۸۱۹۱ ۔ المقنع بن الحصین التمیمی\n(1) بصرہ فروش ہونے والے۔ مسند بقی بن مخلد میں ان کی ایک حدیث ذکر کی گئی ہے۔ ذہبی نے تجرید میں اپنے استدراک میں ان کا ذکر کیا ہے۔ بقول بعض: یہ المقنع ہیں جن کا تذکرہ ہوتا ہے۔","",{"fn":"(1) تجرید (۹۲/۲)"}],[8172,"§۸۱۹۲ ۔ المقنع (دوسرے)\nیہ سلمی ہیں۔ بنی سلیم کے وفد میں سے جو رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، جن پر عباس بن مرداس اپنے قصیدے میں فخر کرتے ہوئے کہتے ہیں: «اس وفد جیسا کوئی وفد نہیں جس نے محمد صلی اللہ علیہ وسلم کی رسی جوڑنے والی نہیں کے ساتھ ہماری ڈوری باندھی۔ ایسا وفد جن میں ابو قطن حزاب، ابو الغیوث، واسع اور مقنع شامل ہیں»۔"],[8173,"§۸۱۹۳ ۔ المقنع\nاز بنی ضرار بن غوث بن عوف بن مالک بن سلامان بن سعد بن زید۔ ابن کلبی ان کے بیٹے طارق بن المقنع کے حالات میں فرماتے ہیں: جب سیدنا حسین بن علی رضی اللہ عنہ کی شہادت ہوئی تو انہوں نے آپ کا مرثیہ کہا۔ لکھتے ہیں: ان کے آباء و اجداد میں بعض افراد نبی صلی اللہ علیہ وسلم کے ساتھ معرکوں میں شریک ہوئے ان کا شمار انصار میں ہوتا ہے۔"],[8174,"§۸۱۹۴ ۔ مکحول (مولی رسول اللہ صلی اللہ علیہ وسلم)\n(1) ابن اسحاق نے سیرت میں ان کا ذکر کیا ہے کہ نبی صلی اللہ علیہ وسلم نے انہیں اپنی رضاعی (دودھ شریک) بہن الشیماء کو ہبہ کر دیا۔ ساتھ ایک باندی بھی تھی۔ انہوں نے اس لڑکی سے ان کی شادی کر دی۔ پھر ان کی نسل میں سے اولاد باقی رہی۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (ت: ۵۰۷۳) تجرید (۹۲/۲)"}],[8175,"§۸۱۹۵ ۔ مکحول (دوسرے)\nمقاتل نے اپنی تفسیر میں گمان ظاہر کیا ہے کہ یہ نجاشی کا نام ہے اور دیگر حضرات نے یہ ممکن قرار دیا ہے کہ ان کے بیٹے کا نام ہو جنہوں نے ہجرت کی تھی۔"],[8176,"§۸۱۹۶ ۔ مکرز بن حفص\nبن الاخیف بن علقمہ بن عبد الحارث بن منقذ بن عمرو بن بغیض بن عامر بن لوی قرشی عامری۔ ابن حبان نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ لکھتے ہیں: بقول بعض: صحابی ہیں، کسی اور نے یہ بات نہیں لکھی۔ مغازی ابن اسحاق اور واقدی میں ان کا ذکر ملتا ہے۔ یہ وہی ہیں جو بدر کے روز سہیل بن عمرو کا فدیہ دینے آئے تھے۔ مرزبان(1) نے «معجم الشعراء» میں ان کا ذکر کیا ہے اور اس کے بارے میں بتایا ہے کہ جاہلیت کے زمانے کے ہیں۔ جس کا مطلب ہے وہ اسلام نہیں لائے۔ ورنہ ان کے بارے میں اتنا ذکر ملتا ہے کہ انہوں نے دور اسلام پایا ہے اور ہجرت کے بعد مدینہ آئے۔ جب سہیل بن عمرو کو بدر کے دن قید کر لیا گیا تھا۔ یہ ان کا فدیہ دینے آئے تھے: جس کے بارے میں کہتے ہیں: «ایسے نوجوان کی قید سے رہائی کے لیے عمدہ اونٹ آنے والے ہیں جن کے خالص پن تک ان کے عرب ہی پہنچ سکتے ہیں نہ کہ موالی»۔ میں نے ان کے بیٹوں سے کہا: سہیل ہمارا بہترین آدمی ہے، تم انہیں لے جاؤ یہاں تک کہ تمنا میں پھیر دو۔ پھر ان کا وہ واقعہ نقل کیا جس میں انہوں نے عامر بن الملوح کو قتل کیا جب عامر نے مکرز کے خاندان کا ایک آدمی مار دیا تھا۔ زبیر بن بکار نے ان کا وہ واقعہ نقل کیا ہے جس میں سہیل بن عمرو کا فدیہ دیا تھا کہ وہ مدینہ آکر کہنے لگے: اس کی جگہ میرے پاؤں میں بیڑیاں ڈال دو یہاں تک کہ فدیہ کا مال پہنچ جائے، اور یہ دو شعر کہے۔ بخاری میں صلح حدیبیہ کے موقع میں بھی ان کا ذکر ہے۔","",{"fn":"(1) معجم الشعراء (۴۲۸)"}],[8177,"§۸۱۹۷ ۔ مکرم الغفاری\n(1) ابن مندہ کی روایت ہے کہ غفار کا ایک شخص نبی صلی اللہ علیہ وسلم کے پاس آکر عرض کرنے لگا، آپ نے فرمایا: «تمہارا کیا نام ہے؟» اس نے کہا: مہان (ذلیل)۔ آپ صلی اللہ علیہ وسلم نے فرمایا: «نہیں بلکہ تم مکرم (عزت مند) ہو»۔(2) ابن مندہ کی روایت میں مہران لکھا اور ابو نعیم نے اسے درست کیا ہے کہ مہان ہے واقعی یہی بات ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۷۵) تجرید (۹۳/۲)\n(2) اسد الغابہ (۱۸۸/۴)"}],[8178,"§۸۱۹۸ ۔ مکرم (دوسرے)\nاور قرطبی کے حالات میں ان کا ذکر ہوا ہے کہ نبی صلی اللہ علیہ وسلم کی ملاقات قبیلہ اسلم کے دو آدمیوں سے ہوئی۔ آپ نے فرمایا: تم دونوں کون ہو؟(1) وہ کہنے لگے: ہم مہانان (دو ذلیل آدمی) ہیں۔ آپ نے فرمایا: نہیں! بلکہ تم مکرمان ہو (یعنی عزت والے ہو)۔","",{"fn":"(1) المصنف لابن ابی شیبہ (۱۱۴/۱۵) (۱۱۵/۱۵)"}],[8179,"§۸۱۹۹ ۔ مکرم (دوسرے)\nسابقہ شخصیت کے دوست ہیں۔"],[8180,"§۸۲۰۰ ۔ مکنف بن زید الخیل الطائی\n(1) ان کے والد کے حالات میں ان کا نسب بیان ہو چکا ہے۔ بقول ابن حبان: بھائیوں میں سب سے بڑے تھے۔ انہیں کے نام پر ان کے والد کی کنیت تھی۔ اسلام لائے تو اسلام خوب نکھرا۔ سیدنا خالد بن ولید(2) کے ساتھ مرتدوں کی سرکوبی میں شریک ہوئے۔ مغازی میں واقدی فرماتے ہیں: زید الخیل قبیلہ طے سے اور اسی طرح عدی بن حاتم اس سے تعلق رکھتے تھے۔ نبی صلی اللہ علیہ وسلم کی وفات کے بعد عدی اسلام پر ثابت قدم رہے۔ بغوی حریث بن زید الخیل کے حالات میں لکھتے ہیں۔ انہیں حارث بھی کہا جاتا تھا اور ان کے بھائی مکنف اسلام لائے اور نبی صلی اللہ علیہ وسلم سے فیضیاب ہوئے۔ بعد میں سیدنا خالد بن ولید کے ساتھ مرتدوں سے محاذ آرائی میں شرکت کی، پھر مکنف کا علیحدہ عنوان نہیں قائم کیا۔ جس کی بنا پر ابن فحون نے اپنے استدراک میں، طبری اور دارقطنی نے ان کا ذکر کیا ہے۔ واقدی کتاب الردہ میں لکھتے ہیں: یہ ان لوگوں میں سے ہیں جو اسلام پر قائم رہے اور بنی اسد جب طلیحہ کے ساتھ ارتداد کی نذر ہوئے تو انہوں نے ان سے جنگ کی، جس کے بارے میں اشعار کہتے ہیں: «یہ لوگ گمراہ ہوئے اور طلیحہ نے انہیں منی میں جھوٹ سے دھوکا دیا، اور ہمارے رب کا داعی (سیدنا محمد صلی اللہ علیہ وسلم) جھوٹ نہیں بولتا۔ جب انہوں نے ہمیں دیکھا تو بھاگ نکلے، ہماری کتاب قضاء کے ساتھ رسول اللہ صلی اللہ علیہ وسلم کے رب کی طرف بلاتی اور رغبت دلاتی ہے، نیز ان لوگوں کو اچھال رہے تھے اور جس طرف وہ مند کرتے ہم ان کا تعاقب کرتے»۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۷۸) تجرید (۹۲/۲)\n(2) جامع المسانید (۵۵/۱۲) اسد الغابہ (۱۸۸/۴)"}],[8181,"§۸۲۰۱ ۔ مکنف (دوسرے)\n(1) ابو عمر(2) نے عن عبد اللہ بن ابی بکر بن حزم عن مکلف الحارثی روایت کی ہے کہ نبی صلی اللہ علیہ وسلم نے محیصہ بن مسعود کو تیس وسق (خاص پیادہ) کھجوریں دیں۔ حسن بن سفیان نے اپنی مسند میں بطریق ابن اسحاق(3) عن عبد اللہ بن ابی بکر ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۷۷) استیعاب (ت: ۲۵۱۳) تجرید (۹۳/۲)\n(2) استیعاب (۴۵/۴)\n(3) السیرۃ النبویۃ (۲۷۰/۳، ۲۷۱/۳)"}],[8182,"§۸۲۰۲ ۔ مکیتیل\n(1) بقول بعض: مکیئر اللیثی۔ مغازی میں ابن اسحاق(2) کا قول ہے: مجھ سے محمد بن جعفر بن الزبیر نے بیان کیا کہ میں نے زیاد بن ضمیرہ بن سعد اسلمی کو بحوالہ عروہ بن زبیر بیان کرتے سنا کہ مجھ سے میرے والد اور میرے نانا نے بیان کیا اور یہ دونوں حضرات حنین میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے۔ فرماتے ہیں: ہمیں رسول اللہ صلی اللہ علیہ وسلم نے حنین کے دن ظہر کی نماز پڑھائی۔ پھر آپ ایک سایہ دار درخت کے نیچے بیٹھ گئے، اقرع بن حابس اور عیینہ بن حصن آپ کے پاس جانے لگے۔ عیینہ بن حصن ان دونوں عامر بن الاضبط (جن کا قتل ہوا تھا) کے خون کا مطالبہ کر رہے تھے۔ اور اقرع بن حابس قاتل کا دفاع کر رہے تھے۔ اتنے میں مکیتیل نامی شخص جو پورے مجمع میں سے کوتاہ قد تھا کھڑے ہو کر کہنے لگا: «آج آپ ایک قانون بنائیں گے اور کل اسے تبدیل کر دیں گے»۔ یہاں تک کہ اس نے کہا یہ لوگ دیت قبول کر لیں۔.... (حدیث)(3) عامر بن الاضبط کے حالات میں ان کا ذکر ہوا ہے۔ ابن ہشام کی زیادہ ابکائی سے مروی روایت میں ہے «مکو»۔ بغوی نے اسی طرح بطریق عبد الرحمن بن ابی الزناد عن عبد الرحمن بن الحارث عن محمد بن جعفر، اس سے مکمل سیاق کے ساتھ نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۷۹) تجرید (۹۳/۲)\n(2) السیرۃ النبویۃ (۲۰۷/۴) (۲۰۸/۴)\n(3) ابوداؤد کتاب الدیات باب الامام یأمر بالعفو فی الدم (۴۵۰۳) ابن ماجہ (۲۶۲۵) مسند احمد (۱۰/۶) السنن الکبریٰ (۱۱۶/۹) بخاری فی التاریخ الکبیر (۲۴۱/۴) (۲۴۲/۴)"}],[8183,"§۸۲۰۳ ۔ ملاعب الاسنہ\nمالک بن عامر، پہلے تذکرہ ہو چکا ہے۔"],[8184,"§۸۲۰۴ ۔ ملکان بن عبدہ انصاری\n(1) واقدی اور طبری نے ان کا ذکر کیا ہے جبکہ ابن ہشام نے ان کا نام مکلو بن عبدہ بتایا ہے اور ان لوگوں میں ان کا ذکر کیا ہے جنہیں نبی صلی اللہ علیہ وسلم نے خیبر سے تیس(۳۰) وسق کھجوریں دی تھیں۔(2)","",{"fn":"(1) اسد الغابہ (ت: ۵۰۸۴) تجرید (۹۳/۲)\n(2) السیرۃ النبویۃ (۲۵۲/۲)"}],[8185,"§۸۲۰۵ ۔ ملییل\n(1) ابن وہب بن خالد بن الجلان انصاری۔ ابن اسحاق اور واقدی وغیرہ نے شرکاء بدر میں ان کا ذکر کیا ہے۔ موسی بن عقبہ نے ان کے دادا کی نسبت سے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۸۶) استیعاب (ت: ۲۵۹۲) تجرید (۹۴/۲)"}],[8186,"§۸۲۰۶ ۔ المنبعث الثقفی\nمولا عمر بن معتب۔ ابن اسحاق سیرت میں فرماتے ہیں مجھ سے کسی آدمی نے بحوالہ ابن المنکدر بیان کیا، جب رسول اللہ صلی اللہ علیہ وسلم نے طائف کا محاصرہ کیا تو منبعث(1) آپ کے پاس آکر مسلمان ہو گئے۔ وہ آل عثمان بن عامر بن معتب کے مولا تھے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۸۷) تجرید (۹۶/۲)"}],[8187,"§۸۲۰۷ ۔ المنبعث (دوسرے)\n(1) ایک صحیح حدیث میں ان کا ذکر آتا ہے جو ابوداؤد نے کتاب الکنی میں عن محمد بن اسماعیل بن سالم عن محمد بن فضیل وکیع عن ہشام بن عروہ عن ابیہ بحوالہ سیدہ عائشہ رضی اللہ عنہا نقل کی ہے کہ نبی صلی اللہ علیہ وسلم ایک شخص کے پاس سے گزرے جسے مضطجع کہا جاتا تھا۔ تو آپ نے اس کا نام منبعث رکھ دیا۔ (مضطجع کا معنی لیٹنے والا، یعنی سست اور منبعث کا معنی اٹھنے والا یعنی چست) اسے محمد بن عبد اللہ بن یزید عن عبیدہ بن ہشام عن ابیہ مرسل نقل کیا ہے۔ اسی طرح ابن شاہین نے بطریق اسماعیل بن عیاش عن ہشام ان الفاظ میں نقل کیا ہے کہ نبی صلی اللہ علیہ وسلم نے نام کو اچھے نام میں تبدیل کر دیا کرتے تھے۔ چنانچہ آپ نے ایک شخص سے پوچھا تمہارا کیا نام ہے؟ پھر اس کا ذکر کیا۔ اسی طرح یحیی بن سعید انصاری عن سعید بن المسیب سے مروی ہے۔ ابوداؤد نے سنن میں باب الاسماء سے کتاب الادب میں تعلیقاً ذکر کیا ہے۔ نبی صلی اللہ علیہ وسلم نے مضطجع کا نام تبدیل کر کے منبعث رکھ دیا۔\nمیں کہتا ہوں: احتمال ہے کہ مذکورہ شخص پہلے والے ہوں۔ کیونکہ ان کا نسب بیان نہیں ہوا۔ ابن کلبی کی کتاب الانساب میں، المنبعث بن عمرو بن ربیعہ بن عبد اللہ بن ابی بکر بن کلاب لکھا ہے، اس کے علاوہ ان کے بارے میں کچھ نہیں بتایا لہذا احتمال ہے کہ وہ یہی ہوں۔","",{"fn":"(1) ابوداؤد کتاب الادب باب فی تغییر الاسم القبیح (۴۹۵۶)"}],[8188,"§۸۲۰۸ ۔ المنتجع النجدی\n(1) ابو سعید نقاش نے اور ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے، اور مجھول سند جو عبد اللہ بن ہشام عن ابی حجرہ الرقی بحوالہ ان کے دادا کہ صحیح النجدی تک ہوتی ہے۔ ان کا تعلق اہل نجد سے تھا اور ایک سو بیس(۱۲۰) سال ان کی عمر ہو گئی تھی۔ وہ کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ نے انبیاء بنی اسرائیل کے ایک نبی کی طرف وحی بھیجی کہ صبح کے وقت اپنا دامن سینٹنا سب سے پہلے جو چیز ملے اسے کھا لینا اور دوسری دفن کر دینا۔.... (حدیث)(2) ابو الشیخ نے کتاب الثواب میں اسی اسناد کے ساتھ ایک اور حدیث نقل کی ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۹۰) تجرید (۹۶/۲)\n(2) الدر المنثور (۱۸۶/۶) حلیۃ الاولیاء (۴۸/۳) جامع المسانید (۵۸،۵۹/۱۲)"}],[8189,"§۸۲۰۹ ۔ المنتذر\n(1) رشامی نے نقل کیا ہے۔ بقول بعض: تفعیل کا صیغہ ہے جیسا کہ تذکرہ ہوتا ہے کہ ابن مندہ کی کتاب میں دونوں طرح ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۹۱) تجرید (۹۶/۸)"}],[8190,"§۸۲۱۰ ۔ المنتشر بن الاجدع الہمدانی\n(1) مسروق کے بھائی۔ بقول بغوی: مجھے معلوم نہیں آیا یہ صحابی ہیں یا نہیں؟ البتہ ابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور ان کی یہ روایت نقل کی ہے کہ نبی صلی اللہ علیہ وسلم کی بیعت کا طریقہ یہ تھا، جب یہ آیت نازل ہوئی «جو لوگ آپ سے بیعت کرتے ہیں وہ تو اللہ سے بیعت کرتے ہیں»۔(2) اللہ اور حق کے لیے بیعت کرتا ہوں۔ اور سیدنا ابوبکر رضی اللہ عنہ کی بیعت اس طرح تھی میں جب تک اللہ کا اطاعت گزار رہتا ہوں مجھ سے بیعت کرتے رہو۔ اور سیدنا عمر اور بعد کے لوگوں کی بیعت نبی صلی اللہ علیہ وسلم کی بیعت کی طرح تھی۔(3) ابن ابی حاتم(4) لکھتے ہیں: میں نے ابو حجر سے پوچھا: کیا المنتشر نے نبی صلی اللہ علیہ وسلم کو دیکھا ہے؟ انہوں نے کہا: نہیں معلوم۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۹۲) استیعاب (۲۵۹۸) تجرید (۹۴/۸)\n(2) سورۃ الفتح آیت (۱۰)\n(3) جامع المسانید (۶۱/۱۲)\n(4) الجرح والتعدیل (۴۲۸/۸)"}],[8191,"§۸۲۱۱ ۔ المنفق\nبقول ابن شاہین: بحوالہ ابن ابی داؤد یہ الورز بن العقیلی ہیں۔ ان کا تعلق ہوا کہ ابو رزین کا نام تو لقیط ہے جیسا کہ کنیتوں میں بیان ہوگا۔ ایک اور حدیث میں عن المنفق یا ابن المنفق مروی ہے۔ عبد اللہ بن المنفق میں اس پر تنبیہ ہو چکی ہے۔"],[8192,"§۸۲۱۲ ۔ منجاب بن راشد\n(1) بن اسرم بن عبد اللہ بن زیاد اصلی، کوفہ فروکش ہوئے۔ ابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق سیف بن عمر بحوالہ منجاب بن راشد روایت کی ہے کہ تبوک کے سال ہمارے پاس نبی صلی اللہ علیہ وسلم کا خط آیا تو ہم لوگ تبوک کے لیے روانہ ہو گئے۔ آپ کے پاس تیم، رباب اور ان جیسے دوسرے قبیلے جمع ہو گئے، ہم لوگوں میں سے چوتھائی تھے اور سب لوگ تعداد میں اڑتالیس(۴۸) ہزار تھے۔\nالدار قطنی لکھتے ہیں: منجاب کوفہ فروکش ہوئے۔ نبی صلی اللہ علیہ وسلم سے کوئی احادیث روایت کی ہیں۔ ہمیں معلوم نہیں کہ ان سے ان کے بیٹے حکیم بن منجاب کے علاوہ کسی نے روایت کی ہو۔ ابو موسیٰ «ذیل» میں لکھتے ہیں: کوفہ کے معزز افراد میں سے تھے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۹۴) تجرید (۹۶/۲)"}],[8193,"§۸۲۱۳ ۔ منجاب بن راشد الناجی\n(1) ابو الحسن المدائنی اور سیف بن عمر نے ان لوگوں میں ان کا ذکر کیا ہے جو خلافت عثمانی میں فارس کے ضلع کے گورنر تھے اور نبی صلی اللہ علیہ وسلم سے ملاقات کی تھی۔ آپ پر ایمان لانے والوں میں سے اور ان کے بھائی حارث شامل ہیں۔ دونوں عثمانی تھے۔ سیدنا علی رضی اللہ عنہ سے بھاگ گئے۔ حارث نے تو زمین میں فساد برپا کیا تو سیدنا علی رضی اللہ عنہ نے ان کی طرف ایک لشکر روانہ کیا جس نے بنی ناجیہ(2) پر حملہ کر دیا اس کی کچھ تفصیل حارث کے حالات میں بیان ہو چکی ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۹۵) (۴۷۲/۴) استیعاب (۲۵۹۹) تجرید (۹۶/۲)\n(2) الکامل فی التاریخ (۱۸۳/۳) (۱۸۷/۳)"}],[8194,"§۸۲۱۴ ۔ مندوس\nبقول بعض: ابو مندوس۔ ابن قانع نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق سلیمان بن الازہر بن کتانہ بن ابیہ بن عن جدہ مندوس یہ حدیث نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «اگر یہ دین ثریا ستارے سے لٹکا ہوا بھی ہوتا تو فارس کے جوانوں کی ایک جماعت وہاں سے بھی اسے حاصل کر لیتے»۔(1) ابن فحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) کنز العمال (۳۴۱۲۰) تاریخ اصبہان (۳/۱) الفقیہ والمتفقہ (۱۱۶/۲)"}],[8195,"§۸۲۱۵ ۔ المنذر بن الاجدع الہمدانی\n(1) مسروق کے بھائی۔ ابن حبان نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور مستغفری نے بھی ان کی پیروی کی ہے، دونوں کا کہنا ہے۔ صحابی ہیں۔\nابن شاہین نے کتاب الجنائز میں بطریق ہشام بن عمرو بن ابی زائدہ روایت کی ہے کہ المنذر بن الاجدع جبل میں فوت ہوئے۔ جن کے ہاتھ پر ہرنی کی وجہ سے بطور سرکٹ دیئے گئے تھے۔ انہوں نے شعبی سے پوچھا: کیا ان کی نماز جنازہ پڑھی جائے گی؟ وہ کہنے لگے: تم کس کی طرف ان کی نسبت کرو گے؟","",{"fn":"(1) اسد الغابہ (ت: ۵۰۹۶) تجرید (۹۵/۲)"}],[8196,"§۸۲۱۶ ۔ المنذر بن الاشوع العبدی\nاسموی نے مغازی میں ان کا ذکر کیا ہے کہ وفد عبد القیس میں آئے۔ لوگوں نے عرض کی: اللہ کے رسول! ہم لڑائی کے بغیر صلح کرنے، اطاعت گزار بن کر نافرمانی کے بغیر آئے ہیں۔ آپ ہمیں تحریر دے دیجئے جو ہمارے پاس باقی عربوں کے مقابلہ میں باعث عزت ہو، آپ کو ان لوگوں سے دلی مسرت ہوئی، آپ نے انہیں چند باتوں کا حکم دیا اور کچھ چیزوں سے روکا اور انہیں نصیحت کی، اس کے بعد انہیں تحریر بھی عطا کی۔ ابن فحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[8197,"§۸۲۱۷ ۔ المنذر بن ابی حمیدہ\nقسم ثالث میں ذکر ہوگا۔"],[8198,"§۸۲۱۸ ۔ المنذر بن رفاعہ الغطفانی\nمقاتل بن سلیمان نے اپنی تفسیر میں اللہ تعالیٰ کے ارشاد «اور یتیمیوں کو ان کا مال دو»(1) کی تفسیر میں ذکر کیا ہے کہ غطفان کا منذر بن رفاعہ نامی ایک شخص تھا جس کے پاس کسی یتیم کا بہت سا مال تھا جو رشتے میں اس کا بھتیجا ہوتا تھا۔ جب وہ لڑکا جوان ہوا تو اس نے اپنا مال طلب کیا اس نے نہ دیا، دونوں نبی صلی اللہ علیہ وسلم کے پاس فیصلہ کرانے گئے۔ آپ نے اس کے سامنے یہ آیت پڑھی۔ تو وہ عرض کرنے لگا: ہم اللہ اور رسول کی بات مانتے ہیں اور اس بڑے گناہ سے اللہ کی پناہ چاہتے ہیں۔ پھر اسے اس کا مال دے دیا تو اس جوان نے اللہ کی راہ میں خرچ کیا، جس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اجر ثابت ہو گیا اور گناہ کا بوجھ باقی رہ گیا۔(2) کسی نے اس کے بارے میں پوچھا، تو فرمایا: نوجوان کے لیے اجر ثابت ہوا اور اس کے باپ کے لیے بوجھ بنا کیونکہ وہ مشرک تھا۔ کلبی نے یہ واقعہ نقل تو کیا ہے لیکن اس غطفانی شخص کا نام نہیں لیا۔ ثعلبی نے اسے کلبی اور مقاتل سے نقل کیا ہے انہوں نے بھی نام نہیں لیا۔ اسی بنا پر اس فن کے مصنفین نے ان کا ذکر نہیں کیا۔","",{"fn":"(1) سورۃ النساء (۲)\n(2) تفسیر القرطبی (۸/۵)"}],[8199,"§۸۲۱۹ ۔ المنذر بن ساوی\n(1) بن الاض بن بیان بن عمرو بن عبد اللہ بن زید بن عبد اللہ بن دارم تیمی داری۔ کلبی کے علاوہ لوگوں کا گمان ہے یہ عبد القیس سے تعلق رکھتے ہیں جس کا سبب رشامی نے یہ بیان کیا ہے کہ انہیں عبدی الرمصہ سے کہا جاتا ہے، کیونکہ یہ عبد اللہ بن دارم کی اولاد سے ہیں جس کی بنا پر کسی نے انہیں عبد القیس کا باشندہ سمجھ لیا۔ نافع العبدی کے حالات میں ان کا ذکر ہوا ہے کہ یہ وفد میں تھے، اکثریت اسے ثابت نہیں کرتی۔ بلکہ ان لوگوں کا کہنا ہے: وفد میں نہیں تھے۔ صرف ان کے ساتھ انہیں بھی سلامتی کا پروانہ ملا۔ بحرین(2) کے گورنر تھے، نبی صلی اللہ علیہ وسلم نے علاء بن حضرمی کے ہاتھ فتح مکہ سے پہلے ان کی طرف خط بھیجا تو یہ اسلام لے آئے۔ ابن اسحاق اور دیگر کئی حضرات نے ان کا ذکر کیا ہے۔ واقدی نے یہ اضافہ نقل کیا ہے۔ پھر نبی صلی اللہ علیہ وسلم نے العلا بن الحضرمی کو واپس بلا لیا تو انہوں نے منذر بن ساوی کو اپنی جگہ نائب مقرر کر دیا۔ طبرانی(3) کی روایت ہے، نبی صلی اللہ علیہ وسلم نے منذر بن ساوی کی طرف خط بھیجا، وہ کہتا جو شخص ہماری طرح نماز پڑھتا ہمارے قبلہ کی جانب رخ کرتا اور ہمارا ذبیحہ کھاتا ہو تو وہ مسلمان ہے۔ جس کے لیے اللہ اور اس کے رسول کی ذمہ داری ہے۔ ابن مندہ کی روایت ہے کہ منذر بن ساوی سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے ان کی طرف خط بھیجا کہ جس شخص کے پاس زمین نہیں اس پہ چار درہم اور ایک عباء واجب کرو۔ ابن مندہ لکھتے ہیں: وہ ہجر پر نبی صلی اللہ علیہ وسلم کے عامل تھے۔ ابو جعفر الطبری کا بیان ہے: ان منذر کی وفات نبی صلی اللہ علیہ وسلم کی وفات کے قریب ہوئی اس وقت عمرو بن عاص ان کے پاس تھے۔ انہوں نے ان سے پوچھا: نبی صلی اللہ علیہ وسلم نے میت کے لیے اس کی موت کے وقت کتنا مال مقرر کیا ہے؟ انہوں نے فرمایا: تہائی۔ پوچھا: آپ کی کیا رائے ہے؟ میں اپنے تہائی مال میں کیا تصرف کروں؟ انہوں نے فرمایا: اس کی دو صورتیں ہیں۔ اگر آپ چاہیں تو اسے بھلائی کے کاموں میں تقسیم کر دیں اور اگر چاہیں تو اس کی آمدن اس شخص پر خرچ ہوتی رہے گی جسے آپ پسند کریں گے۔ انہوں نے کہا: میں نہیں چاہتا کہ میں اپنے مال کو «سائبہ» کی طرح کروں بلکہ میں اسے تقسیم کروں گا۔ رشامی لکھتے ہیں: ابن عبد البر نے ان کا ذکر نہیں کیا۔ میں کہتا ہوں: یہ ان کی شرط کے مطابق ہیں، اگرچہ یہ ثابت نہیں کہ وہ خدمت نبوی میں آئے ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۵۰۹۹) استیعاب (۲۵۱۵) تجرید (۹۵/۲)\n(2) اسد الغابہ (۱۹۴/۴)\n(3) المعجم الکبیر (۳۵۵/۲۰)"}],[8200,"§۸۲۲۰ ۔ المنذر بن سعد\n(1) ابو حمید الساعدی۔ بقول بعض ان کا نام: عبد الرحمن ہے، کنیتوں میں تذکرہ ہوتا ہے۔","",{"fn":"(1) تجرید (۹۵/۲)"}],[8201,"§۸۲۲۱ ۔ المنذر بن عائذ العبدی\nعرف الامج۔ ابن افتح عبد القیس۔ بقول بعض: ان کا نام منقذ بن عائذ ہے جیسا کہ پہلے مطر بن فیل اور صحار بن العباس کے حالات میں بیان ہو چکا ہے۔"],[8202,"§۸۲۲۲ ۔ المنذر بن عبد اللہ\n(1) بن توال بن وث بن ثعلبہ بن طریف بن الخزرج بن ساعدہ انصاری خزرجی ساعدی۔ ابن اسحاق اور واقدی نے شہداء طائف میں ان کا ذکر کیا ہے۔ البتہ واقدی کی کتاب میں بغیر اضافت المنذر بن عبد ہے۔ اور ابو عمر(2) نے ان کے والد کا نام صحار بتایا ہے۔ پھر ابن عبد اللہ میں ان کا نام نہر برا ہے۔ ابن مندہ سے ان کے نسب میں سے توال نام رہ گیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۱۰۳) استیعاب (۲۵۱۹) تجرید (۹۵/۲)\n(2) استیعاب (۱۱/۴)"}],[8203,"§۸۲۲۳ ۔ المنذر بن عبد اللہ\nبن نوفل۔ واقدی نے طائف کے شہداء میں ان کا ذکر کیا ہے اور ابن فحون نے اپنے استدراک میں۔"],[8204,"§۸۲۲۴ ۔ المنذر بن عبد المدان\n(1) بقول ابن مندہ: مغازی میں ان کا ذکر ملتا ہے لیکن مجھے ان کی روایت کا پتہ نہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۵۱۰۴) تجرید (۹۵/۲)"}],[8205,"§۸۲۲۵ ۔ المنذر بن عدی\n(1) بن المنذر بن عدی بن حجر بن وہب بن ربیعہ بن معاویہ الکندی۔ طبری ان کا ذکر کرتے ہوئے لکھتے ہیں: آنے کی سعادت رکھتے ہیں۔ ابن فحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۱۰۵) استیعاب (۲۵۲۰) تجرید (۹۵/۲)"}],[8206,"§۸۲۲۶ ۔ المنذر بن علقمہ\nبن کلدہ بن عبد الدار بن عبد مناف الجدری۔ ان کا والد کافر قتل ہوا۔ اور اسلام کی حالت میں ان کے ہاں ایوب بن المنذر کی ولادت ہوئی، محمد بن ایوب بن المنذر رواۃ محمد میں شہید ہوئے۔ زبیر بن بکار نے ان کا ذکر کیا ہے۔"],[8207,"§۸۲۲۷ ۔ المنذر بن عمرو\n(1) بن خنیس بن حارث بن لوذان بن عبدود بن زید بن ثعلبہ بن الخزرج بن ساعدہ بن کعب بن الخزرج انصاری خزرجی ساعدی۔ بعض نے نسب میں سے حارث کو ساقط کیا ہے۔ بقول ابن ابی خیثمہ میں نے سعد بن عبد الحمید بن جعفر کو فرماتے سنا: المنذر بن عمرو کو بیعت عقبہ میں سے بدری نقیب ہیں۔ نیز معونہ میں شہید ہوئے۔ یہی ابن اسحاق(2) کا قول ہے: اس بات کا ثبوت کہ وہ بیر معونہ کے واقعہ میں شہید ہوئے، صحیح بخاری میں ہے۔ منذر بن الزبیر بن عوام کا نام ان کے نام پر رکھا گیا ان کا لقب معنق لیموت تھا۔ مغازی موسی بن عقبہ میں ہے کہ «عامر بن مالک ملاعب الاسنہ» رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، اور کہنے لگے: میرے ساتھ آپ جسے چاہیں بھیج دیں۔ میں ان کا ذمہ دار ہوں تو آپ نے ایک جماعت روانہ کی، جن میں منذر بن عمرو بھی تھے جنہیں «معنق لیموٹ» کہا جاتا تھا۔ عامر بن الطفیل کو ان لوگوں کی آمد کی خبر ہوئی تو اس نے بنی سلیم کو ان لوگوں کے مقابلہ کے لیے تیار کیا تو اس کے ساتھ ان میں بنی عصیہ اور ذکوان کا خاندان چل نکلا۔ جس کے نتیجہ میں واقعہ بیر معونہ پیش آیا اور منذر اپنے ساتھیوں سمیت شہید ہو گئے۔\nابن اسحاق(3) نے یہ واقعہ بواسطہ اپنے والد، مغیرہ بن عبد الرحمن بن حارث بن ہشام وغیرہ، طویل نقل کیا ہے جسے ابن مندہ نے بطریق اسماعیل بن نصر سدی سے نقل کیا ہے۔ فرماتے ہیں: اسے سلمہ بن فضل نے محمد بن اسحاق عن حمید عن انس طویل ذکر کیا ہے۔\nبغوی لکھتے ہیں: ان کی روایت نہیں۔ تو ابن قانع، ابن اسکن اور دارقطنی(4) کی اسنن میں نقل کردہ روایت کی وجہ سے ان کا تعاقب کیا گیا۔ چنانچہ بطریق عبد الیمین بن عباس بن سہل بن سعد عن ابیہ عن جدہ، بحوالہ منذر بن عمرو روایت ہے کہ نبی صلی اللہ علیہ وسلم نے سلام سے پہلے سہو کے دو سجدے کیے۔ الدارقطنی فرماتے ہیں: منذر نے اس کے علاوہ کوئی حدیث نہیں روایت کی اور عبد الیمین تو قوی راوی نہیں۔\nمیں کہتا ہوں: سند میں ان کے علاوہ بھی ہیں۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (ت: ۵۱۰۷) استیعاب (۲۵۲۱) تجرید (۹۵/۲)\n(2) السیرۃ النبویۃ (۴۶۶/۱) (۱۸۳/۳)\n(3) السیرۃ النبویۃ (۱۴۷/۳) (۱۴۶/۳)\n(4) السنن الدارقطنی (۳۷۴/۱)"}],[8208,"§۸۲۲۸ ۔ المنذر بن قدامہ\n(1) بن عرفجہ بن کعب بن اخناط بن کعب بن حارثہ بن غنم بن مالک بن الاوس انصاری اوسی۔ ابن اسحاق،(2) موسی بن عقبہ اور ابن کلبی وغیرہ نے شرکاء بدر میں ان کا ذکر کیا ہے۔ واقدی کا بیان ہے کہ بنی قینقاع کے قیدیوں پر مامور تھے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۱۰۶) استیعاب (۲۵۲۴) تجرید (۹۶/۲)\n(2) السیرۃ النبویۃ (۲۵۱/۲)"}],[8209,"§۸۲۲۹ ۔ المنذر بن قیس\n(1) بن عمرو بن عبید بن مالک بن عدی بن غنم بن عدی بن انجار۔ احد اور باقی معرکوں میں شریک ہوئے۔ یہ اور ان کے بھائی سلیط بن قیس، حمر ابی عبید کے روز شہید ہوئے۔ یہ عددی کا قول ہے۔ ابن فحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) استیعاب (۲۵۲۵) تجرید (۹۶/۲)"}],[8210,"§۸۲۳۰ ۔ المنذر بن کعب الدارمی\n(1) ابو العباس السراج اپنے شیخ احمد بن سعید بن صخر بن سلیمان بن عبد اللہ بن قیس بن عبد اللہ بن المنذر بن کعب بن الاسود بن عبد اللہ بن زید بن عبد اللہ بن دارم کے حالات میں لکھتے ہیں: نبی صلی اللہ علیہ وسلم کے پاس آئے۔ یہی نسب خطیب نے بیان کیا ہے۔ لکھتے ہیں: میں نے عبد اللہ بن الحسن طبری کو یہی کہتے سنا: فرماتے ہیں: بقول بعض: منذر بن کعب نبی صلی اللہ علیہ وسلم کے پاس آئے۔ خطیب نے نقل کیا ہے ان کے دادا اصغر وہی ابن سلیم بن قیس ہیں۔ ابن فحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۱۰۹) استیعاب (۲۵۲۳) تجرید (۹۶/۲)"}],[8211,"§۸۲۳۱ ۔ المنذر بن مالک\n(1) ابو نعیم نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے کہ ان کے حالات کا کچھ پتہ نہیں۔ پھر بطریق مسلم بن خالد عن مطرف الانصری عن حمید بن ہلال بحوالہ منذر بن مالک روایت کی ہے کہ میں نے عرض کی: اللہ کے رسول! سب سے افضل صدقہ کونسا ہے؟ آپ نے فرمایا: جو نادار کی محنت سے فقیر تک پوشیدہ طور پر پہنچے۔(2)\nمیں کہتا ہوں: احتمال ہے کہ یہ حدیث مرسل ہو۔ منذر بن مالک وہی ابو نضر، غفاری مشہور تابعی ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۵۱۱۰) تجرید (۹۶/۲)\n(2) مسند احمد (۳۶۶، ۳۶۵/۵) المعجم الکبیر (۲۵۹/۸)"}],[8212,"§۸۲۳۲ ۔ المنذر بن محمد\n(1) بن عقبہ بن احیج (تصغیر) ابن الجلاح انصاری خزرجی۔ ابو عبیدہ کنیت ہے، موسی بن عقبہ اور ابن اسحاق(2) وغیرہ نے شرکاء بدر میں ان کا ذکر کیا ہے، واقعہ بیر معونہ میں شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۱۱۱) استیعاب (۲۵۲۱) تجرید (۹۶/۲)\n(2) السیرۃ النبویۃ (۲۹۰/۱) (۱۸۵/۲)"}],[8213,"§۸۲۳۳ ۔ المنذر بن یزید\n(1) ابن غانم بن حدیدہ انصاری، عبد الرحمن کے بھائی۔ بقول عدوی: صحابی ہیں۔ ابن فحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۱۱۲) استیعاب (۲۵۲۲) تجرید (۹۶/۲)"}],[8214,"§۸۲۳۴ ۔ المنذر (بے نسبت)\nامام بخاری رحمہ اللہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے کہ دیہات میں رہتے تھے۔ نبی صلی اللہ علیہ وسلم سے روایت کی ہے جسے بغوی نے نقل کیا ہے۔ ابن فحون نے بحوالہ ابو جعفر الطبری اس کا مفہوم ذکر کیا ہے۔"],[8215,"§۸۲۳۵ ۔ منساۃ الجنتی\nابن درید کا بیان ہے کہ ان اہل نصیبین کے جنات میں سے ایک ہیں۔ جنہوں نے نخلستان میں نبی صلی اللہ علیہ وسلم سے قرآن سنا اور آپ صلی اللہ علیہ وسلم پر ایمان لائے۔"],[8216,"§۸۲۳۶ ۔ منصور بن عمیر\nبن ہاشم بن عبد مناف بن عبد الدار الجبری، مصعب کے بھائی۔ ابو الروم کنیت تھی اور کنیت سے مشہور ہوئے۔ موسی بن عقبہ اور ابن اسحاق نے مہاجرین حبشہ میں ان کا ذکر کیا ہے اور شرکاء احد میں ان کا ذکر کیا ہے۔ زبیر بن بکار کا قول ہے: یرموک میں شہید ہوئے۔"],[8217,"§۸۲۳۷ ۔ منظور بن زبان\n(1) بن سیار بن عمرو بن جابر بن عقیل بن ہلال بن کمی بن مازن بن فزارہ۔ الدارقطنی اور عبد الغنی بن سعید نے «المشتہ» میں مفضل الغلابی سے روایت کی ہے کہ انہوں نے حدیث براء بن عازب میں فرمایا: میں اپنے ماموں کے پاس آیا، ان کے پاس ایک جھنڈا تھا، میں نے کہا: کہاں کا ارادہ ہے؟ فرمایا: مجھے رسول اللہ صلی اللہ علیہ وسلم نے اس شخص کی گردن اتارنے کے لیے بھیجا ہے جس نے اپنے والد کی بیوی سے شادی کر لی ہے؟ فرماتے ہیں: وہ شخص منظور بن زبان(2) تھا۔ عمر بن شبہ کا بیان ہے: یہ آیت(3) ہے اور ان عورتوں سے نکاح نہ کرو جن سے تمہارے آباء نے نکاح کیا، ہاں جو پہلے ہو چکا سو ہو چکا(4) منظور بن زبان(5) کے بارے میں نازل ہوئی۔ انہوں نے اپنے والد کی بیوی، جس کا نام ملیکہ تھا، شادی کر لی تھی۔ سیدنا صدیق اکبر رضی اللہ عنہ جب خلیفہ بنے تو انہیں طلب فرمایا یا بالآخر وہ دونوں، بکرین سے برآمد ہوئے۔ دونوں کو مدینہ لائے اور دونوں میں تفریق کر دی۔ سیدنا عمر رضی اللہ عنہ نے منظور کو قتل کرنا چاہا، انہوں نے اللہ کی قسم کھائی کہ مجھے اس کی حرمت کا علم نہیں تھا، جس کے بارے میں ولید بن سعید بن المام المزنی نے کہا:\n«جہاں تک لوگوں کو معلوم ہے ماؤں کے بارے میں آباء کا بدترین نائب زبان کا باپ منظور ہے۔»\nاس سے معلوم ہوا کہ منظور عبدہ نبی صلی اللہ علیہ وسلم میں قتل نہیں ہوئے۔ شاہد سیدنا براء کے ماموں انہیں گرفتار نہ کر سکے بلکہ جب انہوں نے ناکہ وہ ان کے ارادے سے آ رہے ہیں وہ بھاگ کھڑے ہوئے۔\nالاعثانی میں ہے: منظور اپنی قوم کے سردار تھے، یہ ان لوگوں میں سے ایک ہیں جن کی ولادت تاخیر سے ہوئی۔ چنانچہ یہ چار سال بعد پیدا ہوئے، چونکہ لوگوں نے ان کا کافی انتظار کیا تھا۔ اس وجہ سے ان کا نام منظور پڑ گیا۔ یتیم بن عدی، بحوالہ ہشام بن کلبی نقل کرتے ہیں جس کا کچھ حصہ زبیر بن بکار نے بواسطہ اپنے چچا، بحوالہ الجلال نقل کیا ہے کہ لوگوں کا کہنا ہے کہ منظور بن زبان نے اپنے باپ کی بیوی سے جو ملیکہ بنت خارجہ بن سنان بن ابی حارثہ مزینی تھی نکاح کر لیا، جس سے ان کے ہاں ہاشم، عبد الجبار اور خولہ پیدا ہوئے اور وہ خلافت فاروقی تک ان کے پاس رہی۔ سیدنا عمر رضی اللہ عنہ کے ہاں ان کا مقدمہ پیش ہوا تو سیدنا عمر رضی اللہ عنہ نے پوچھ گچھ کی کہ لوگوں کا کہنا ہے کہ تم نے شراب لی اور اپنے باپ کی بیوی سے نکاح کر لیا ہے۔ جس کا انہوں نے اعتراف کر لیا اور کہنے لگے: مجھے معلوم نہیں تھا کہ حرام ہے، چنانچہ آپ نے انہیں عمر کی نماز کے قریب تک قید رکھا، پھر ان سے قسم لی کہ انہیں اس کا علم نہیں کہ اللہ نے اسے حرام قرار دیا ہے، چنانچہ لوگوں کے بیان کے مطابق انہوں نے چالیس(۴۰) قسمیں کھائیں پھر آپ نے انہیں چھوڑ دیا اور ان میں اور ملیکہ میں تفریق کر دی اور فرمایا: اگر تم نے تم نہ کھائی ہوتی تو میں تمہاری گردن اڑا دیتا۔ ابن کلبی کی اس کی روایت میں ہے کہ سیدنا عمر رضی اللہ عنہ نے فرمایا: تم نے اپنے باپ کی بیوی سے جو تمہاری ماں لگتی ہے نکاح کر لیا، کیا تمہیں یہ معلوم نہیں تھا کہ یہ حرام نکاح ہے؟ پھر ان دونوں میں تفریق کر دی، جو ان پر بڑا گراں گزرا، ایک دفعہ انہوں نے اسے راستے میں چلتے دیکھا تو بے ساختہ کہا:\n«سنو! مجھے اس کی کوئی پروا نہیں کہ زمانے نے آج جو کچھ کیا ہے، مجھ سے ملیکہ اور شراب کو روک دیا ہے، اگر اس کا دیدار کرنا دو ہو چکا ہے تو عزمی کی بیٹی کو جب تک فجر طلوع ہوتی رہے میرا سلام کہہ دینا۔»\nابھی کے اشعار میں سے ہے:\n«میرے باپ کی زندگی کی قسم! دین نے زبردستی میرے اور تمہارے درمیان جو تفریق کر دی ہے، وہ بڑی مشاق ہے۔»(6)\nسیدنا عمر رضی اللہ عنہ کو معلوم ہوا تو آپ نے انہیں طلب کر کے سزا دینا چاہی تو وہ بھاگ گئے۔ بعد میں طلحہ بن عبید اللہ نے ان سے شادی کر لی۔ زبیر بن بکار نے اخبار مدینہ میں لکھا ہے کہ جب سیدنا عمر رضی اللہ عنہ نے منظور اور ملیکہ میں تفریق کر دی تو فرمایا: اس (بچاری) کی کفالت کون کرے گا؟ تو سیدنا عبد الرحمن بن عوف بولے: میں۔ چنانچہ انہوں نے اسے اپنی حوالے میں ٹھہرایا، بعد میں وہ حوالے ہی کے نام سے دار ملیکہ مشہور ہو گئی۔ عمر بن شبہ، اخبار مدینہ میں لکھتے ہیں کہ یہ واقعہ دور فاروقی میں پیش آیا، جیسا کہ میں خواتین کے حصے میں، ملیکہ کے حالات میں اس کا ذکر کروں گا۔ ابن کلبی نے کتاب النسب میں ذکر کیا ہے کہ ان کی کنیت ام خولہ تھی، اور وہ زبان کے عقد میں تھیں۔ وفات ہوئے، ان سے ان کی کوئی اولاد نہ ہوئی تو زبان کے بیٹے نے ان سے جاہلیت کا نکاح کر لیا، پھر ایک لمبا واقعہ ذکر کیا۔ ابو موسیٰ ذیل میں ان ملیکہ کے حالات میں بطریق محمد بن عثمان بن عثمان بن جریج تک ہم نے مردودایت کرتے ہیں۔ اسلام نے چار عورتوں اور اپنے خاوند کے بیٹوں کے درمیان تفریق کی۔ پھر ان میں ملیکہ کا ذکر کیا جن سے منظور نے اپنے والد کے بعد نکاح کر لیا تھا۔ ابو الفرج ہی کا بیان ہے کہ سیدنا حسن بن علی نے ان منظور کی بیٹی خولہ کے ہاں اس وقت نکاح کا پیام بھیجا جب اس کا باپ غائب تھا۔ تو اس نے انہیں اختیار دے دیا۔ چنانچہ آپ نے اس سے شادی کر لی۔ انہیں معلوم ہوا تو کہنے لگے: کیا مجھ جیسے شخص کی بیٹی لے جائی جاتی ہے؟ مدینہ آئے اور مسجد نبوی میں سیاہ جھنڈا لگا کر آتے تو مدینہ میں جو قتلی بھی تھا وہ اس سے جمع ہو گیا۔ سیدنا حسن کو معلوم ہوا تو آپ نے فرمایا: اپنی بیٹی لے جاؤ، چنانچہ وہ اسے لے کر قریبا تک ہی پہنچے تھے کہ وہ آپ کو پکارنے لگی اور کہنے لگی: ابا جان! حسن جنتی نوجوانوں کے سردار ہیں۔ وہ بولے: اچھا اگر انہیں تمہاری ضرورت ہوئی تو ہم سے آ ملیں گے، تم یہیں ٹھہر واچنانچہ وہ دونوں قیام کیا، اتنے میں سیدنا حسن اپنے ساتھ سیدنا حسین، عبد اللہ بن جعفر، عبد اللہ بن عباس کو لے کر پہنچ گئے۔ چنانچہ انہوں نے سیدنا حسن سے اس کی شادی کر دی۔ اور آپ اسے لے کر واپس آ گئے۔ میرے خیال میں یہ دو لڑکی ہے جس کا تذکرہ فردوسی شاعر کے سوانح میں ہوا ہے یا اس کی بہن ہے۔ کیونکہ جب اس کی بیوی کو اور اس سے بھاگ کر ابن زبیر کی طرف مکہ میں چلی گئی اور وہ وہاں کے خلیفہ تھے تو رزق تک مکہ آیا اور علی عبد اللہ بن الزبیر کے ہاں فروش ہوا ان کی مدح کی اور نوار بنت منظور بن زبان کے ہاں ٹھہری ہوئی تھی۔ سیدنا عبد اللہ بن زبیر نے فرزدق کے خلاف نوار کے حق میں فیصلہ کیا جس کا واقعہ مشہور ہے اس کے بارے میں فرزدق شاعر کہتا ہے:\n«رے اس کے بیٹے تو ان کی سفارش نہ سنی گئی۔ منظور بن زبان کی بیٹی نے سفارش کی، جو سفارشی تمہارے پاس تہبند پہنے آئے وہ اس سفارشی کی طرح کی کائیں جو مٹکا ہو کر تمہارے پاس آئے۔»\nمرزبانی(7) لکھتے ہیں: منظور خضر میں ہی اپنے والد کی بیوی سے شادی کر لی تھی، جس کا نام ملیکہ تھا تو سیدنا عمر نے ان میں تفریق کر دی اور دونوں شعروں کا ذکر کیا۔ ابن الاثیر(8) ان کے حالات میں بحوالہ الامر بالی نضر بن ماکول(9) لکھتے ہیں کہ انہوں نے الاکمال میں ذکر کیا ہے: منظور بن زبان بن سنان، فراری کی طرف رسول اللہ صلی اللہ علیہ وسلم نے کسی شخص کو قتل کرنے بھیجا تھا۔ ابن الاثیر فرماتے ہیں: وہ اگر مسلمان نہ ہوتے تو اس کی وجہ سے انہیں قتل کرنے کا حکم نہ دیتے، بلکہ ان کا قتل کفری بنا پر ہوتا۔ ان کا واقعہ جو سیدنا ابو بکر و عمر پھر سیدنا حسن بن علی رضی اللہ عنہم کے ساتھ پیش آیا ہے۔ اس سے پتہ چلتا ہے کہ وہ خلافت عثمانی تک زندہ رہے۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (ت: ۵۱۱۴) تجرید (۹۶/۲)\n(2) مسند احمد (۲۹۰/۴)\n(3) سورۃ النساء آیت (۲۲)\n(4) تفسیر ابن کثیر (۲۱۵/۲)\n(5) اسد الغابہ (۱۹۸/۴)\n(6) الاغانی (۲۲۷/۱۲)\n(7) معجم الشعراء (۲۸۰)\n(8) اسد الغابہ (۱۹۸/۴)\n(9) الاکمال (۳۱۴/۲)"}],[8218,"§۸۲۳۸ ۔ منظور بن لبید\nبن عقبہ بن رفاع انصاری اہلی۔ محمود کے بھائی ہیں۔ عدوی کا قول ہے: بیعت رضوان میں شریک ہوئے، ابن فحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[8219,"§۸۲۳۹ ۔ منقذ بن خنیس اسدی\nابو لکب، اپنی کنیت سے مشہور ہیں، کنیتوں میں ان کا ذکر آئے گا۔"],[8220,"§۸۲۴۰ ۔ منقذ بن حبان عبدی\nصحار کے سوانح میں ان کا ذکر گزر چکا ہے، ان کے بھانجے ہیں۔ واللہ اعلم"],[8221,"§۸۲۴۱ ۔ منقذ بن زید بن حارث\n(1) ابو عمر(2) نے ان لوگوں کے حوالے سے ان کا ذکر کیا ہے، جنہوں نے صحابہ رضی اللہ عنہم کے بارے میں کتابیں لکھیں۔","",{"fn":"(1) اسد الغابہ (ت: ۵۱۱۶) استیعاب (۲۵۲۸) تجرید (۹۶/۲)\n(2) استیعاب (۱۴/۴)"}],[8222,"§۸۲۴۲ ۔ منقذ بن عائذ\nمنذر بن عائذ میں ان کا ذکر آئے گا۔"],[8223,"§۸۲۴۳ ۔ منقذ بن عمرو\n(1) بن عطیہ بن خصام بن مبذول بن عمرو بن غنم بن مازن بن نجار انصاری، مدنی۔ بخاری(2) کا قول ہے: صحابی ہیں۔ حدیث کے شان نزول میں اختلاف کا بیان حبان بن منقذ کے سوانح میں گزر چکا ہے، جب تم خرید و فروخت کرو تو کہو دھوکہ دہی نہیں ہو گی۔ کہ یہ قصہ حبان بن منقذ کا ہے یا ان کے والد منقذ بن عمرو کا ہے؟","",{"fn":"(1) اسد الغابہ (ت: ۵۱۱۷) استیعاب (۲۵۲۹) تجرید (۹۶/۲)\n(2) بخاری (۲۱۱۷) تاریخ کبیر (۱۷/۴)"}],[8224,"§۸۲۴۴ ۔ منقذ بن نباتہ اسدی\n(1) ابن اسحاق(2) نے بواسطہ بن خزیمہ میں سے مدینہ ہجرت کرنے والے لوگوں میں ان کا ذکر کیا ہے، ابن مندہ نے معبد نامی لوگوں میں ان کا ذکر کیا ہے۔ معروف منقذ ہے، ابو عمر(3) نے ان کے والد کے نام میں لفظی غلطی کی ہے، فرماتے ہیں: لباب۔","",{"fn":"(1) اسد الغابہ (ت: ۵۱۱۸) استیعاب (۲۵۳۰) تجرید (۹۷/۲)\n(2) السیرۃ النبویۃ (۴۷۲/۱)\n(3) استیعاب (۱۵/۴)"}],[8225,"§۸۲۴۵ ۔ منقذ اسلمی\nابن فحون نے ذیل میں، بحوالہ بادودی ان کا ذکر کیا ہے کہ انہوں نے صحابہ رضی اللہ عنہم میں سے صفین میں شریک ہونے والوں میں بطریق عبد اللہ بن ابی رافع ان کا ذکر کیا ہے، اس کی سند ضعیف ہے۔"],[8226,"§۸۲۴۶ ۔ منقع بن حصین\n(1) بن یزید بن ثعل بن حبان بن حارث بن عمرو بن کعب بن عبد شمس بن سعد بن زید مناۃ بن تمیم تیمی سعدی، ابن سعد(2) نے بصرہ فروش ہونے والے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ بخاری اور ابن ابی خیثمہ(3) نے اپنی تاریخ میں بطریق عصرہ بن بشر نقل کیا ہے کہ ہم سے فرع نے بحوالہ منقع ذکر کیا ہے، فرماتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس اپنے اونٹوں کی زکوۃ لے کر آیا، آپ صلی اللہ علیہ وسلم نے فرمایا: «اے اللہ! میں ان کے لیے اپنے بارے میں جھوٹ بولنے کی اجازت نہیں دیتا»۔(4) منقع کہتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کے حوالے سے صرف وہی حدیث بیان کی جو کتاب اللہ کے موافق تھی یا جو سنت کے مطابق ہے۔ سیف بن ہارون فرماتے ہیں: عصرہ کے حوالے سے اسے روایت کیا، میرا خیال ہے کہ وہ فرع ہیں، قادسیہ میں شریک ہوئے، اسے ابو علی بن سکن نے اس طریق سے طویل نقل کیا ہے۔ اس میں مذکورہ حدیث کا شان ورود کا اضافہ کیا، اس میں ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو اونٹنی پر سوار دیکھا، اسود اس کی رکاب پر پڑے ہوئے تھے۔ وہ نبی کریم صلی اللہ علیہ وسلم کے سر مبارک کے برابر تھے، میں نے ان سے زیادہ دراز قد شخص نہیں دیکھا۔","",{"fn":"(1) اسد الغابہ (ت: ۵۱۲۰) تجرید (۹۷/۲)\n(2) طبقات کبریٰ (۴۳/۶)\n(3) تاریخ کبیر (۵۳/۸)\n(4) المعجم الکبیر (۳۰۰/۲۰) مجمع الزوائد (۶۰۳/۱)"}],[8227,"§۸۲۴۷ ۔ منقع بن مالک\n(1) بن امیہ بن عبد غزی سلمی، قدور بن عمار سلمی کے سوانح میں ان کا ذکر گزر چکا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے انہیں ان کی قوم کی ایک جماعت پر امیر بنایا، منقع کا ذکر گزر چکا ہے، وہ بھی سلمی ہیں، مجھے معلوم نہیں کہ کیا وہ ایک ہیں اور ان کے نام میں اختلاف ہے یا وہ دو ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۵۱۲۱) تجرید (۹۷/۲)"}],[8228,"§۸۲۴۸ ۔ منکدر بن عبد اللہ\n(1) بن ہدیر تیمی۔ طبرانی(2) وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، انہوں نے بطریق حریث بن سنائب، بحوالہ محمد بن منکدر، عن ابیہ نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: «جس نے بیت اللہ کا ایک ہفتے تک طواف کیا اور اس میں کوئی لغو کام نہیں کیا تو اس کا ثواب ایک غلام آزاد کرنے کے برابر ہے۔»","",{"fn":"(1) اسد الغابہ (ت: ۵۱۲۲) استیعاب (۲۶۰۲) تجرید (۹۷/۲)\n(2) المعجم الکبیر (۷۶۰/۲۰)"}],[8229,"§۸۲۴۹ ۔ منہال بن اوس نکری\nرسول اللہ صلی اللہ علیہ وسلم کے پاس وفد میں آئے۔ رشاطی نے بحوالہ مدائنی ان کا ذکر کیا ہے۔ فرماتے ہیں: ابن عبد البر اور ابن فتحون نے ان کا ذکر نہیں کیا۔"],[8230,"§۸۲۵۰ ۔ منہال بن ابی منہال\nطبری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[8231,"§۸۲۵۱ ۔ منہال قیسی\nقتادہ بن ملحان میں ان کا ذکر گزر چکا ہے۔"],[8232,"§۸۲۵۲ ۔ منیب\n(1) ابن عبد سلمی، خطیب نے ان کا ذکر کیا ہے اور ابن ماکولا نے ان کی اتباع کی ہے ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔ انہوں نے بطریق اخوص بن علیم، بحوالہ منیب بن عبد سلمی جو صحابی ہیں، بحوالہ ابو امامہ مرفوع نقل کیا ہے: «جس نے صبح کی نماز مسجد میں پڑھی پھر ٹھہرا رہا اور چاشت کے دو نفل پڑھے اسے حج اور عمرے کا ثواب ملے گا۔»(2)","",{"fn":"(1) اسد الغابہ (ت: ۲۱۲۵) تجرید (۹۷/۲)\n(2) المعجم الکبیر (۱۷۴/۴) مجمع الزوائد (۱۱۶/۱۰) اتحاف السادۃ المتقین (۲۸/۵)"}]])